window.__D("text/zohar-hebrew-translation/c025",{"p":[[9522011982,"<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (דברים לא) וַיֹּאמֶר ה' אֶל מֹשֶׁה הִנְּךְ שּכֵב עִם אֲבתֶיךְ וְגוֹ'. בֹּא רְאֵה, כָּל זְמַן שֶׁמֹּשֶׁה הָיָה קַיָּם בָּעוֹלָם, הָיָה מוֹחֶה בִידֵי יִשְׂרָאֵל, כְּדֵי שֶׁלֹּא יִמָּצְאוּ בְחֵטְא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם שֶׁמֹּשֶׁה נִמְצָא בֵינֵיהֶם, לֹא יִהְיֶה כְּמוֹ אוֹתוֹ הַדּוֹר עַד הַדּוֹר שֶׁיָּבא הַמֶּלֶךְ הַמָּשִׁיחַ, שֶׁיִּרְאוּ אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹתָם, שֶׁהֵם נִדְבְּקוּ מַה שֶּׁלֹּא נִדְבְּקוּ דוֹרוֹת אֲחֵרִים.</p>\n<p>שֶׁשָּׁנִינוּ, רָאֲתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאֲתָה עֵינוֹ שֶׁל יְחֶזְקֵאל הַנָּבִיא. אִם הֵם כָּל כָּךְ נִדְבְּקוּ, נְשׁוֹת יִשְׂרָאֵל כָּל שֶׁכֵּן, בְּנֵיהֶם כָּל שֶׁכֵּן, וְהַגְּבָרִים כָּל שֶׁכֵּן, הַסַּנְהֶדְרִין כָּל שֶׁכֵּן, הַנְּשִׂיאִים כָּל שֶׁכֵּן, וְכָל שֶׁכֵּן הַנָּבִיא הָעֶלְיוֹן הַנֶּאֱמָן מֹשֶׁה, שֶׁהוּא עַל הַכֹּל. וְעַתָּה אֵלּוּ סוֹחֲרֵי הַמִּדְבָּר רוֹחֲשִׁים כָּל כָּךְ הַרְבֵּה חָכְמָה, כָּל שֶׁכֵּן חַכְמֵי הַדּוֹר, כָּל שֶׁכֵּן אֵלּו שֶׁעוֹמְדִים לִפְנֵי רַבִּי שִׁמְעוֹן וְלוֹמְדִים מִמֶּנּוּ בְּכָל יוֹם. כָּל שֶׁכֵּן, וְכָל שֶׁכֵּן רַבִּי שִׁמְעוֹן, שֶׁהוּא עֶלְיוֹן עַל הַכֹּל.</p>\n<p>אַחַר שֶׁמֵּת מֹשֶׁה, מַה כָּתוּב? וְקָם הָעָם הַזֶּה וְזָנָה וְגוֹ'. כָּךְ, אוֹי לָעוֹלָם כְּשֶׁיִּסְתַּלֵּק מִמֶּנּוּ רַבִּי שִׁמְעוֹן, שֶׁמַּעַיְנוֹת הַחָכְמָה יִסְתַּתְּמוּ מִן הָעוֹלָם, וְיִרְצֶה אָדָם דְּבַר חָכְמָה וְלֹא יִמָּצֵא מִי שֶׁיֹּאמַר, וְכָל הָעוֹלָם טוֹעִים בַּתּוֹרָה, מִשּׁוּם שֶׁלֹּא יִמָּצֵא בֵינֵיהֶם מִי שֶׁמִּתְעוֹרֵר בְּחָכְמָה. עַל אוֹתוֹ זְמַן כָּתוּב, וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ. וְאִם יִשְׁגּוּ בַתּוֹרָה וְלֹא יֵדְעוּ אֶת דְּרָכֶיהָ, בַּמֶּה זֶה? מִשּׁוּם שֶׁנֶּעְלַם דָּבָר מֵעֵינֵי הַקָּהָל, שֶׁלֹּא יִמָּצֵא מִן שֶׁיּוֹדֵעַ לְגַלּוֹת עֲמֻקּוֹת הַתּוֹרָה וּדְרָכֶיהָ. אוֹי לְאוֹתָם הַדּוֹרוֹת שֶׁיִּמָּצְאוּ אָז בָּעוֹלָם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַלּוֹת רָזִים עֲמֻקִּים שֶׁל הַתּוֹרָה בִּזְמַן שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, מִשּׁוּם (ישעיה יא) שֶׁמָּלְאָה הָאָרֶץ דֵּעָה אֶת ה' כַּמַּיִם לַיָּם מְכַסִּים. וְכָתוּב (ירמיה לא) וְלֹא יְלַמְּדוּ עוֹד אִישׁ אֶת רֵעֵהוּ וְאִישׁ אֶת אָחִיו לֵאמֹר דְּעוּ אֶת ה' כִּי כוּלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם, אָמֵן כֵּן יְהִי רָצוֹן.</p>"],[9522011983,"<p>אֲשֶׁר נָשִׂיא יֶחֱטָא וְעָשָׂה אַחַת וְגוֹ' בִּשְׁגָגָה וְאָשֵׁם. שָׁנָה רַבִּי יִצְחָק, מַה שּׁוֹנֶה שֶׁבְּכָל מָקוֹם כָּתוּב בָּהֶם וְאִם, כְּמוֹ שֶׁנֶּאֱמַר אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא, וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ, וְכָאן אֲשֶׁר נָשִׂיא יֶחֱטָא, וְלֹא כָתוּב וְאִם נָשִׂיא יֶחֱטָא? מַה זֶּה אוֹמֵר?</p>\n<p>אֶלָּא, שֶׁהַכֹּהֲנִים הַלָּלוּ אֵינָם נִמְצָאִים כָּךְ בְּחֵטְא, שֶׁהֲרֵי הַכֹּהֵן שׁוֹמֵר אֶת עַצְמוֹ תָּמִיד, מִשּׁוּם שֶׁמַּשָּׂאוֹ שֶׁל אֲדוֹנוֹ עָלָיו בְּכָל יוֹם, וְהַמַּשָּׂא שֶׁל כָּל יִשְׂרָאֵל, וְהַמַּשָּׂא שֶׁל כָּל אֶחָד וְאֶחָד, וְלָכֵן הַתְּמִיהָה, הוּא כְּשֶׁיֶּחֱטָא?! וּמִשּׁוּם כָּךְ כָּתוּב וְאִם. וְכֵן וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ, תְּמִיהָה הִיא שֶׁכֻּלָּם יִמָּצְאוּ בְּחֵטְא אֶחָד, שֶׁאִם אֵלֶּה יַחְטְאוּ - אֵלּוּ לֹא יַחְטְאוּ, וּמִשּׁוּם כָּךְ כָּתוּב וְאִם. אֲבָל כָּאן אֲשֶׁר נָשִׂיא יֶחֱטָא, וַדַּאי, מִשּׁוּם שֶׁלִּבּוֹ גַּס בּוֹ, וְהָעָם הוֹלְכִים אַחֲרָיו וְהִתְמַנּוּ תַחְתָּיו. וְעַל כֵּן אֲשֶׁר נָשִׂיא יֶחֱטָא. כְּגוֹן שֶׁהוּא עָבַר עַל מִצְווֹת לֹא תַעֲשֶׂה, וְהוּא עָשָׂה אַחַת מֵהֶן, וְלָכֵן לֹא כָתוּב בּוֹ וְאִם, שֶׁהֲרֵי דְּבָרָיו אֵינָם בְּסָפֵק.</p>\n<p>רַבִּי יְהוּדָה פָּתַח, וְהַנְּשִׂאִם הֵבִיאוּ אֵת אַבְנֵי הַשּׁהַם וְאֵת אַבְנֵי הַמִּלֻּאִים לָאֵפוֹד וְלַחֹשֶׁן. מַה שּׁוֹנֶה שֶׁאֶת הַדְּבָרִים הַלָּלוּ הִקְרִיבוּ הַנְּשִׂיאִים וְלֹא אָדָם אַחֵר? וַהֲרֵי כָּתוּב, (שמות לה) כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת ה', וְכָתוּב וְאַבְנֵי שּהַם וְאַבְנֵי מִלֻּאִים לָאֵפוֹד וְלַחֹשֶׁן.</p>\n<p>אֶלָּא, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁבְּכֻלָּם תְּלוּיָה הַנְּדָבָה הַזּוֹ, הָאֲבָנִים הַלָּלוּ עוֹלוֹת לַנְּשִׂיאִים. מָה הַטַּעַם? מִשּׁוּם שֶׁהֵן נִמְצָאוֹת עַל לֵב הַכֹּהֵן. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, יָבוֹאוּ נְשִׂיאִים שֶׁלִּבָּם גַּס בָּהֶם, וְיָבִיא אֶת הָאֲבָנִים הַלָּלוּ שֶׁנִּמְצָאוֹת עַל לִבּוֹ שֶׁל הַכֹּהֵן, וְיִתְכַּפֵּר עֲלֵיהֶם מִגַּסּוּת לִבָּם. וְכָתוּב וְהָיוּ עַל לֵב אַהֲרֹן בְּבאוֹ לִפְנֵי ה', וְעַל זֶה - וְהַנְּשִׂיאִים הֵבִיאוּ אֵת אַבְנֵי הַשֹּׁהַם וְאֵת אַבְנֵי הַמִּלֻּאִים, לְכַפֵּר עֲלֵיהֶם.</p>\n<p>וּמִשּׁוּם כָּךְ, אֲשֶׁר נָשִׂיא יֶחֱטָא, וַדַּאי. וְעָשָׂה אַחַת מִכָּל מִצְות ה' אֱלֹהָיו אֲשֶׁר לֹא תֵעָשֶׂינָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁעָבַר עַל מִצְוַת לֹא תַעֲשֶׂה. אוֹ הוֹדַע אֵלָיו חַטָּאתוֹ. שֶׁמִשּׁוּם שֶׁלִּבּוֹ גַּס בּוֹ, לֹא מַשְׁגִּיחַ בַּחֲטָאָיו, וְאַחַר כָּךְ נוֹדַע לוֹ וְעָשָׂה מִזֶּה תְשׁוּבָה.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי יְהוּדָה לְרַבִּי יוֹסֵי, רָאִיתִי שֶׁצַּחוּת הַתּוֹרָה בַּלַּיְלָה יוֹתֵר מֵאֲשֶׁר בַּיּוֹם. לָמָּה זֶה? אָמַר לוֹ, מִשּׁוּם שֶׁהַצַּחוּת שֶׁל תּוֹרָה שֶׁבִּכְתָב הִיא תוֹרָה שֶׁבְּעַל פֶּה, וְתוֹרָה שֶׁבְּעַל פֶּה שׁוֹלֶטֶת בַּלַּיְלָה, וּמִתְעוֹרֶרֶת יוֹתֵר מֵאֲשֶׁר בַּיּוֹם, וּבִזְמַן שֶׁהִיא שׁוֹלֶטֶת, אָז קַיֶּמֶת הַצַּחוּת שֶׁל הַתּוֹרָה.</p>"],[9522011984,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (איוב לה) וְלֹא אָמַר אַיֵּה אֱלוֹהַּ עֹשָׂי נֹתֵן זְמִרוֹת בַּלָּיְלָה. בּא רְאֵה, בְּשָׁעָה שֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן וְנֶחֱלָק הַלַּיְלָה, הֲרֵי בֵּאֲרוּ שֶׁשַּׁלְהֶבֶת אַחַת יוֹצֵאת וּמַכָּה תַּחַת כַּנְפֵי הַתַּרְנְגוֹל וּמַקִּישׁ אֶת כְּנָפָיו וְקוֹרֵא. וְאוֹתָהּ שַׁלְהֶבֶת, בִּזְמַן שֶׁמַּגִּיעָה אֵלָיו וּמִתְעוֹרֶרֶת כְּנֶגְדּוֹ, הוּא מִסְתַּכֵּל בָּהּ וּמִזְדַּעֲזֵעַ וְקוֹרֵא, וּמִסְתַּכֵּל וּמַשְׁגִּיחַ בִּשְׁבִיל כְּבוֹד רִבּוֹנוֹ כְּדֵי לַעֲשׂוֹת רְצוֹנוֹ, וְקוֹרֵא לִבְנֵי הָאָדָם.</p>\n<p>וְלָכֵן נִקְרָא שֶׂכְוִי, הַשְׁגָּחָה. וְנִקְרָא גֶבֶר, שֶׁמִּתְעוֹרֵר בְּשַׁלְהֶבֶת הַגְּבוּרָה, בַּצַּד שֶׁל הַגְּבוּרָה הוּא בָּא לְעוֹרֵר אֶת הָעוֹלָם, וְאָז אוֹתָם בְּנֵי הָאֱמוּנָה עוֹמְדִים וְנוֹתְנִים גְּבוּרָה וְכֹחַ לִכְנֶסֶת יִשְׂרָאֵל, וְאָז נִקְרֵאת רִנַּת הַתּוֹרָה. וְלָכֵן דָּוִד יָרַשׁ אֶת הַמַּלְכוּת הוּא וּבָנָיו לְעוֹלָמִים וּלְדוֹרֵי דוֹרוֹת.</p>\n<p>וּכְשֶׁהַתַּרְנְגוֹל קוֹרֵא וּבְנֵי אָדָם יְשֵׁנִים בְּמִטּוֹתֵיהֶם וְאֵינָם מִתְעוֹרְרִים, הַתַּרְנְגוֹל קוֹרֵא אַחַר כָּךְ, וְאוֹמֵר מַה שֶּׁאוֹמֵר, וַהֲרֵי פֵּרְשׁוּהָ. אַחַר כָּךְ מַכֶּה בִכְנָפָיו וְאוֹמֵר: אוֹי לִפְלוֹנִי הַנָּזוּף שֶׁל רִבּוֹנוֹ, שֶׁעָזַב אֶת רִבּוֹנוֹ, וְלֹא עוֹרֵר אֶת רוּחוֹ וְלֹא מַשְׁגִּיחַ עַל כְּבוֹד רִבּוֹנוֹ.</p>\n<p>כְּשֶׁמֵּאִיר הַיּוֹם, הַכָּרוֹז קוֹרֵא עָלָיו וְאוֹמֵר: וְלֹא אָמַר אַיֵּה אֱלוֹהַּ עֹשָׂי נֹתֵן זְמִרוֹת בַּלָּיְלָה. לְסַיֵּעַ לוֹ בְּאוֹתָן הַתִּשְׁבָּחוֹת, וְשֶׁיִּהְיֶה הַכֹּל בְּסִיּוּעַ אֶחָד. עֹשָׂי?! עוֹשַׂנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה עֹשָׂי? אֶלָּא בְּשָׁעָה שֶׁאָדָם קָם בַּחֲצוֹת הַלַּיְלָה וּמִשְׁתַּדֵּל בְּרִנַּת הַתּוֹרָה, שֶׁרִנַּת הַתּוֹרָה לֹא נִקְרֵאת אֶלָּא בַּלַּיְלָה, וּכְשֶׁהוּא נִמְצָא בַּתּוֹרָה כְּשֶׁמֵּאִיר הַיּוֹם, הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל מְתַקְּנִים לוֹ חוּט אֶחָד שֶׁל חֶסֶד לְהִנָּצֵל מִן הַכֹּל, וּלְהָאִיר לוֹ בֵּין הָעֶלְיוֹנִים וְהַתַּחְתוֹנִים.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אֲנִי שָׁמַעְתִּי שֶׁאָמַר רַבִּי אַבָּא אֶת הַפָּסוּק הַזֶּה, אַיֵּה אֱלוֹהַּ עֹשָׂי, עוֹשֶׂה לִי הָיָה צָרִיךְ לִהְיוֹת! מַהוּ עֹשָׂי? אֶלָּא כְּמוֹ שֶׁאָמַרְתָּ, בְּשָׁעָה שֶׁהוּא קָם בַּלַּיְלָה וּמִשְׁתַּדֵּל בַּתּוֹרָה, כְּשֶׁמֵּאִיר הַיּוֹם מִתְעוֹרֵר אַבְרָהָם בְּאוֹתוֹ חוּט שֶׁלּוֹ, שֶׁכָּתוּב בּוֹ (בראשית יד) אִם מִחוּט וְעַד שְׂרוֹךְ נַעַל וְגוֹ'. וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל מְתַקְּנִים אוֹתוֹ, וְעוֹשִׂים אוֹתוֹ בְּכָל יוֹם בְּרִיָּה חֲדָשָׁה. זֶהוּ שֶׁכָּתוּב אֱלוֹהַּ עֹשָׂי.</p>\n<p>וַהֲרֵי פֵּרְשׁוּהָ, א\"ל ו\"ה. א\"ל - זֶה אַבְרָהָם, שֶׁכָּתוּב בּוֹ, הָאֵל הַגָּדוֹל. ו' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. ה' - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְזֶה הוּא אֱלוֹהַּ. וְהֵם עוֹשִׂים אֶת הָאָדָם וּמְתַקְּנִים אוֹתוֹ בְּכָל יוֹם, וּמִשּׁוּם כָּךְ כָּתוּב עֹשָׂי, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמט) יִשְׂמַח יִשְׂרָאֵל בְּעוֹשָׂיו. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא, וְהַכֹּל דָּבָר אֶחָד.</p>"],[9522011985,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, אוֹ הוֹדַע אֵלָיו חַטָּאתוֹ אֲשֶׁר חָטָא. הוֹדַע אֵלָיו, מִצַּד שֶׁל מִי? אוֹ יָדַע (נודע) חַטָּאתוֹ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה הוֹדַע אֵלָיו? אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְצַוֶּה אֶת כְּנֶסֶת יִשְׂרָאֵל לְהוֹדִיעַ לָאָדָם אוֹתוֹ הַחֵטְא שֶׁהוּא חָטָא, וּבַמֶּה מוֹדִיעָה לוֹ? בְּדִינֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר (איוב כ) יְגַלּוּ שָׁמַיִם עֲונוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. הוֹדַע אֵלָיו, כְּמִי שֶׁמְּצַוֶּה לְאַחֵר.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁאָדָם חוֹטֵא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מַשְׁגִּיחַ עַל חֶטְאוֹ לַחֲזֹר בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ, וְזוֹרֵק אוֹתוֹ אַחַר כְּתֵפוֹ, נִשְׁמָתוֹ מַמָּשׁ עוֹלָה וּמְעִידָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז מְצַוֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל וְאוֹמֵר: אוֹ הוֹדַע אֵלָיו חַטָּאתוֹ אֲשֶׁר חָטָא, הוֹשִׁיטִי אֶת הַדִּין עָלָיו וְהוֹדִיעִי לוֹ אֶת חֶטְאוֹ, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל טז) הוֹדַע אֶת יְרוּשָׁלם אֶת תּוֹעֲבֹתֶיהָ.</p>\n<p>אַחַר שֶׁמַּגִּיעַ עָלָיו הַדִּין, אָז מִתְעוֹרֶרֶת רוּחַ לַחֲזֹּר בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ, וְנִכְנָע לְהַקְרִיב קָרְבָּן, שֶׁהֲרֵי מִי שֶׁלִּבּוֹ גַּס בּוֹ, חוֹטֵא, וְשׁוֹכֵחַ חֶטְאוֹ וְלֹא מַשְׁגִּיחַ עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזֻמָּן כְּנֶגְדּוֹ, וּמְצַוֶּה לְהוֹדִיעַ לוֹ אֶת אוֹתוֹ הַחֵטְא, כְּדֵי שֶׁלֹּא יִשְׁתַּכַּח מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּךְ זֶה וַדַּאי (מנין שכך) וְכָךְ מָצָאנוּ בְדָוִד, שֶׁכֵּיוָן שֶׁעָשָׂה אוֹתוֹ מַעֲשֶׂה שֶׁל בַּת שֶׁבַע, לֹא הִשְׁגִּיחַ בּוֹ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה שָׁכַחְתָּ אוֹתוֹ?! אֲנִי אַזְכִּיר לְךְ. מִיָּד מַה כָּתוּב? (שמואל ב יב) אַתָּה הָאִישׁ כֹּה אָמַר ה'. אַתָּה הָאִישׁ שֶׁלֹּא זָכַרְתָּ אוֹתוֹ, אַתָּה הָאִישׁ שֶׁשָּׁכַחְתָּ אוֹתוֹ. וּבַמָּה הוֹדִיעַ לוֹ? בְּדִין.</p>\n<p>אַף כָּאן, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, הוֹדַע אֵלָיו חַטָּאתוֹ אֲשֶׁר חָטָא, וְהַדָּבָר יָפֶה, וְכָךְ הוּא, שֶׁלֹּא כָתוּב אוֹ נוֹדַע אֵלָיו, כְּמוֹ שֶׁכָּתוּב (שמות כא) אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא, וּמִי שֶׁעוֹמֵד בַּלַּיְלָה לַעֲסֹק בַּתּוֹרָה, הַתּוֹרָה מוֹדִיעָה לוֹ אֶת חֶטְאוֹ, וְלֹא בְדֶרֶךְ שֶׁל דִּין, אֶלָּא כְּמוֹ אֵם שֶׁמּוֹדִיעָה לִבְנָהּ בְּדָבָר רַךְ, וְהוּא אֵינוֹ שׁוֹכֵחַ אוֹתוֹ, וְשָׁב בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ.</p>\n<p>וְאִם תֹּאמַר, דָּוִד, שֶׁהָיָה קָם בַּחֲצוֹת הַלַּיְלָה, לָמָּה הִתְעוֹרְרוּ עָלָיו בְּדִין? אֶלָּא דָּוִד שׁוֹנֶה, שֶׁהוּא עָבַר בְּמַה שֶּׁנִּקְשַׁר, וְצָרִיךְ דִּין, וּבְמַה שֶּׁעָבַר הוּא נִדּוֹן. הוּא חָטָא כְּנֶגֶד הַמַּלְכוּת הַקְּדוֹשָׁה וְלִירוּשָׁלַיִם הַקְּדוֹשָׁה, וּמִשּׁוּם כָּךְ גֹּרַשׁ מִירוּשָׁלַיִם, וְהַמַּלְכוּת הוּסְרָה מִמֶּנּוּ, עַד שֶׁהִתְתַּקֵּן כָּרָאוּי (ונענש).</p>\n<p>אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱנִישׁ אֶת דָּוִד עַל יְדֵי בְנוֹ, שֶׁכָּתוּב (שמואל ביב) הִנְנִי מֵקִים עָלֶיךְ רָעָה מִבֵּיתֶךְ? אָמַר רַבִּי יוֹסֵי, הֲרֵי בֵּאַרְנוּ, מִשּׁוּם שֶׁאִם יַעֲמֹד עָלָיו אִישׁ אַחֵר, לֹא יְרַחֵם עָלָיו. אָמַר לוֹ, וַהֲרֵי אַבְשָׁלוֹם רָצָה לַהֲרֹג אֶת אָבִיו בְּכַמָּה עֵצוֹת רָעוֹת (חבל תחבולות) עָלָיו יוֹתֵר מֵאָדָם אַחֵר? אָמַר לוֹ, לֹא שָׁמַעְתִּי.</p>\n<p>אָמַר לוֹ, אֲנִי שָׁמַעְתִּי, דָּוִד חָטָא בְּבַת שֶׁבַע סָתַם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יָבֹא בֵּן שֶׁל בַּת אֵל נֵכָר וְיִנְקם נְקָמָה, וּמִיהוּ? זֶה אַבְשָׁלום, שֶׁהָיָה בְּנָהּ שֶׁל יְפַת תֹּאַר, מֵהַקְּרָב. מִכָּאן לָמַדְנוּ, מִי שֶׁלּוֹקֵחַ הָאִשָּׁה הַזּוֹ בַּקְּרָב וְחוֹמֵד אוֹתָהּ, לַסּוֹף יוֹצֵא מִמֶּנָּה בֵּן סוֹרֵר וּמוֹרֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁעַד עַכְשָׁו לֹא פָסְקָה מִמֶּנּוּ זֻהֲמָה, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011986,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ, הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. אֲבָל בֹּא רְאֵה, כָּל זְמַן שֶׁאָדָם חוֹטֵא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, יֵשׁ דַּרְגָּה אַחַת נוֹדַעַת לְמַעְלָה כְּנֶגֶד הַחֵטְא הַזֶּה לָדוּן אֶת הָאָדָם, וּמִסְתַּכֶּלֶת (ומסכימה) עָלָיו. אִם שָׁב בִּתְשׁוּבָה שְׁלֵמָה לִפְנֵי רִבּוֹנוֹ, מָעֳבָר חֶטְאוֹ וְאֵין הַדִּין שׁוֹלֵט עָלָיו וְלֹא מַגִּיעַ עָלָיו. וְאִם לֹא שָׁב, נִרְשָׁם אוֹתוֹ הַחֵטְא לְאוֹתָהּ הַדַּרְגָּה. אִם הוֹסִיף לַחֲטֹא, הֲרֵי דַּרְגָּה אַחֶרֶת מִזְדַּמֶּנֶת כְּנֶגְדּוֹ וּמַסְכִּימָה עִם הַדַּרְגָּה הָרִאשׁוֹנָה, וְאָז צָרִיךְ תְּשׁוּבָה יְתֵרָה. (ואם לא שב) וְאִם מוֹסִיף לַחֲטֹא, מוֹסִיף דַּרְגָּה עַל דַּרְגָּה, עַד שֶׁמַּשְׁלִים לְחָמֵשׁ דְּרָגוֹת.</p>\n<p>כֵּיוָן שֶׁהַיָּמִין הִתְתַּקֵּן כְּנֶגְדּוֹ וְהִסְכִּים עָלָיו, הֲרֵי הַשְּׂמֹאל מְזֻמָּן לְהַסְכִּים עִם הַיָּמִין וּלְהִכָּלֵל בּוֹ. כֵּיוָן שֶׁהַשְּׂמֹאל מַסְכִּים עִם הַיָּמִין, אָז כְּבָר לֹא תָלוּי בִּתְשׁוּבָה, וַהֲרֵי פֵּרְשׁוּהָ, וְאָז הַכֹּל מַסְכִּימִים עָלָיו בַּדִּין, וְהַדִּין שׁוֹרֶה עָלָיו.</p>\n<p>וּכְשֶׁהַדִּין נִשְׁלָם וְשׁוֹרֶה עַל הָאָדָם, אָז מִסְתַּיֵּם וּמִתְתַּקְּנוֹת הָאֶצְבָּעוֹת חָמֵשׁ בְּתוֹךְ חָמֵשׁ, יָמִין בִּשְׂמֹאל, לְהַרְאוֹת שֶׁהֲרֵי הַכֹּל הִסְכִּימוּ עָלָיו בְּאוֹתוֹ דִין, וְיָדָיו מִתְיַשְּׁרוֹת לְהַרְאוֹת דָּבָר בְּלִי כַוָּנַת הָאָדָם, וְלֹא הִתְכַּוֵּן בּוֹ. וְעַל זֶה כָּתוּב, (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב, לְהִכָּלֵל שְׂמֹאל בְּיָמִין, וְנִשְׁלָם הַדִּין, וְאָז זוֹהִי עֲמִידָה שֶׁל הַכֹּל. וְלָכֵן, כְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּם הַכֹּל, כָּתוּב (ישעיה סב) נִשְׁבַּע ה' בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ וְגוֹ'.</p>"],[9522011987,"<p>רַבִּי יְהוּדָה פָּתַח, כָּתוּב (ויקרא כג) פְּרִי עֵץ הָדָר כַּפֹּת תְּמָרִים. פְּרִי עֵץ הָדָר מַה הוּא? זֶה אֶתְרוֹג. וְכִי אֶתְרוֹג מֵעֵץ הָדָר הוּא? וַהֲרֵי כַּמָּה קוֹצִים יֵשׁ סְבִיבוֹ, מִכָּאן וּמִכָּאן, וְאַתָּה אָמַרְתָּ פְּרִי עֵץ הָדָר? אֶלָּא סוֹד הַדָּבָר, שֶׁכָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה וַיְבִאֶהָ אֶל הָאָדָם. וְכָתוּב עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, וְזֶהוּ פְּרִי עֵץ הָדָר. מִנַּיִן לָנוּ שֶׁאָדָם נִקְרָא עֵץ? שֶׁכָּתוּב כִּי הָאָדָם עֵץ הַשָּׂדֶה.</p>\n<p>כַּפֹּת תְּמָרִים, שֶׁעוֹלִים לְשִׁבְעִים שָׁנִים, וּבוֹ נִתְקְנוּ שִׁבְעִים שָׁנִים עֶלְיוֹנוֹת. וְזֶה כָּפוּת לְמַעְלָה וּלְמַטָּה, וְלָכֵן נִקְרָא כַּפֹּת, כְּמוֹ שֶׁנֶּאֱמַר כְּפִיתוּ, שֶׁעוֹלֶה לְכָאן וּלְכָאן. זֶהוּ שֶׁכָּתוּב כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, דַּוְקָא.</p>\n<p>רַבִּי יוֹסֵי אָמַר, פְּרִי עֵץ הָדָר - זֶה מִזְבֵּחַ, שֶׁעוֹשֶׂה פֵרוֹת, וּמַעֲלֶה נִצָּנִים לְכָל הַצְּדָדִים. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל שִׁבְעִים הַשָּׁנִים נוֹתְנִים לָהּ חֵלֶק, וְהִיא מִתְבָּרֶכֶת מִכֻּלָּם. מַה זֶּה אוֹמֵר? מִשּׁוּם שֶׁמִּי שֶׁחוֹטֵא אֶל הַמִּזְבֵּחַ, הוּא חוֹטֵא בַּכֹּל, שֶׁהֲרֵי כָּפוּת כְּנֶגֶד אוֹתוֹ שֶׁכָּפוּת לְמַעְלָה, וְלָכֵן נִקְשְׁרוּ זֶה עִם זֶה, פְּרִי עֵץ הָדָר כַּפֹּת תְּמָרִים, וְלֹא כָתוּב וְכַפֹּת תְּמָרִים.</p>\n<p>כָּתוּב (ויקרא ז) זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. מַה זֶּה אוֹמֵר? אֶלָּא זֹּאת - זֶה מִזְבֵּחַ, שֶׁנִּמְשַׁח עַל יַד אַהֲרֹן, שֶׁכָּתוּב וּמָשַׁחְתָּ אֶת מִזְבַּח הָעֹלָה וְאֶת כָּל כֵּלָיו. וּמִשְׁחַת (זו משחת) בָּנָיו, שֶׁהֲרֵי נִמְשַׁח מִכֻּלָּם, וּמִתְגַּדֵּל וּמִתְבָּרֵךְ וּמִטַּהֵר.</p>\n<p>בֹּא רְאֵה, בֶּחָג סוֹבְבִים אֶת הַמִּזְבֵּחַ פַּעַם אַחַת בְּכָל יוֹם, וְאַחַר כָּךְ שֶׁבַע פְּעָמִים. מַה זֶּה אוֹמֵר? אֶלָּא, לְמֶלֶךְ שֶׁהִזְמִין אוֹרְחִים וְהִתְעַסֵּק עִמָּהֶם, וְהָיְתָה לַמֶּלֶךְ בַּת יְחִידָה. אָמְרָה לוֹ: אֲדוֹנִי הַמֶּלֶךְ, מִשּׁוּם הָאוֹרְחִים לֹא שַׂמְתָּ לֵב אֵלַי? אָמַר לָהּ: חַיָּיִךְ בִּתִּי, מָנָה אַעֲלֶה לָךְ בְּכָל יוֹם, (ששוה ככלם).</p>\n<p>כָּךָ בְּכָל יוֹם וָיוֹם שֶׁל הֶחָג מַקְרִיבִים יִשְׂרָאֵל כְּנֶגֶד אֻמּוֹת הָעוֹלָם. אָמַר הַמִּזְבֵּחַ לַמֶּלֶךְ הַקָּדוֹשׁ: לְכֻלָּם נִמְצָאִים מָנוֹת וַחֲלָקִים, וְלִי מָה אַתָּה נוֹתֵן? אָמַר לָהּ: בְּכָל יוֹם וָיוֹם יְסוֹבְבוּ אוֹתְךְ שִׁבְעָה יָמִים עֶלְיוֹנִים לְבָרֵךְ אוֹתְךְ, וְנוֹתְנִים לְךְ שִׁבְעִים חֲלָקִים (בכל יום). רַבִּי יוֹסֵי אָמַר, שִׁבְעִים חֲלָקִים בְּכָל יוֹם כְּנֶגֶד שִׁבְעִים פָּרִים שֶׁנִּקְרָבִים בֶּחָג.</p>\n<p>רַבִּי יְהוּדָה אָמַר, שִׁבְעָה בְּכָל יוֹם, מִשּׁוּם שֶׁהֲרֵי מִתְבָּרֶכֶת (ממקום) מִכֻּלָּם, וּלְסוֹף שִׁבְעָה הַיָּמִים מִתְבָּרֶכֶת מִמָּקוֹם שֶׁשֶּׁמֶן הַמִּשְׁחָה נִמְצָא. (ואחר כך) שֶׁבַע פְּעָמִים, כְּנֶגֶד כָּל אוֹתָם שִׁבְעָה יָמִים כְּדֵי לְהַעֲמִיד לָהּ בְּרָכוֹת מִמַּעְיַן הַנַּחַל שֶׁזּוֹרֵם תָּמִיד וְלֹא פוֹסֵק. נִמְצָא שֶׁמִּתְבָּרֶכֶת (תמיד) בְּכָל יוֹם וָיוֹם, עַד שִׁבְעָה יָמִים שֶׁמִּתְבָּרֶכֶת מִמַּעְיַן הַנַּחַל. וְכֵן פַּעַם אַחֶרֶת שֶׁבַע פְּעָמִים כְּאֶחָד, וּמִתְקַיְּמוֹת בָּהּ הַבְּרָכוֹת אַחַר כָּךְ מֵהַמָּקוֹם הָעֶלְיוֹן שֶׁהַמַּעְיָן יוֹצֵא וְלֹא פוֹסֵק, כְּפִי שֶׁאָמַרְנוּ.</p>\n<p>בְּכָל יוֹם מַכְרִיזִים עָלֶיהָ וְאוֹמְרִים, (שמואל א ב) עַד עֲקָרָה יָלְדָה שִׁבְעָה וְרַבַּת בָּנִים אֻמְלָלָה. עַד עֲקָרָה יָלְדָה שִׁבְעָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּתְבָּרֶכֶת מִשִּׁבְעָה בְּכָל יוֹם, וְעוֹלָה לְחֶשְׁבּוֹן עֶלְיוֹן. וְרַבַּת בָּנִים אֻמְלָלָה - אֵלּוּ אֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁעוֹלִים בַּיּוֹם הָרִאשׁוֹן לְחֶשְׁבּוֹן גָּדוֹל, וְאַחַר כָּךְ מִתְמַעֲטִים וְהוֹלְכִים בְּכָל יוֹם וָיוֹם, וְלָכֵן הַמִּזְבֵּחַ מְכַפֵּר עַל חֲטָאֵי יִשְׂרָאֵל, הַמִּזְבֵּחַ מְטַהֵר אוֹתָם וּמֵרִיק לָהֶם בְּרָכוֹת מִמַּעְלָה לְמַטָּה.</p>\n<p>וַעָנַף עֵץ עָבֹת - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁאָחוּז לִשְּׁנֵי צְדָדִים. וּמִשּׁוּם כָּךְ הֲדַס שְׁלֹשָׁה עֲנָפִים, שֶׁיֵּעָשֶׂה עֲנַף עֵץ עָבת שֶׁאָחוּז לְכָל צַד. וְעַרְבֵי נָחַל - אֵלּוּ שְׁנֵי עַמּוּדִים, שֶׁמִּכָּאן יוֹצֵא לְכַפּוֹת תְּמָרִים. כַּפֹּת תְּמָרִים, אָחוּז לְמַעְלָה וְאָחוּז לְמַטָּה, וַהֲרֵי נִתְבָּאֵר. אֶתְרוֹג יוֹצֵא מִתּוֹךְ הַקּוֹצִים שֶׁל הָאִילָן, וְכָךְ זֶה. גַּם כַּפֹּת תְּמָרִים אוֹחֵז בָּהֶם וַדַּאי. כָּל מַה שֶּׁיּוֹצֵא לָעוֹלָם - מִכָּאן יוֹצֵא וּמִכָּאן בָּאִים (נזון).</p>\n<p>רַבִּי יוֹסֵי פָּתַח, וְאָבוֹאָה אֶל מִזְבַּח אֱלֹהִים. מִי זֶה מִזְבַּח אֱלֹהִים? זֶהוּ הַמִּזְבֵּחַ שֶׁלְּמַעְלָה, מִזְבַּח אֱלֹהִים וַדַּאי. וְהַיְנוּ בְּאֵר שֶׁל יִצְחָק, וְלִפְעָמִים מִזְבַּח ה', כְּמוֹ שֶׁנֶּאֱמַר קָם מִלִּפְנֵי מִזְבַּח ה'. וְעַל זֶה יוֹרְשִׁים הָעוֹלָמוֹת מִכָּאן דִּין וְרַחֲמִים, מִשּׁוּם שֶׁהִיא יוֹנֶקֶת בַּצַּד הַזֶּה וּבַצַּד הַזֶּה, וַהֲרֵי בֵּאֲרוּ אֶת הַדָּבָר.</p>"],[9522011988,"<p>נֶפֶשׁ כִּי תִמְעֹל מַעַל וְגוֹ'. רַבִּי יִצְחָק אָמַר, הֲרֵי פֵּרְשׁוּהָ נֶפֶשׁ וַדַּאי. כָּתוּב וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת ה' אֱלֹהֶיךְ, וְכָתוּב וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיֵּשׁ לָהֶם חֵלֶק עֶלְיוֹן בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, בַּחֵלֶק הַקָּדוֹשׁ, בְּקִדּוּשׁ הַמֶּלֶךְ, מִשּׁוּם שֶׁהֵם מְקַדְּשִׁים אֶת עַצְמָם בִּקְדֻשּׁוֹת רִבּוֹנָם. וְכָל מִי שֶׁמִּתְקַדֵּשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַדֵּשׁ אוֹתוֹ, שֶׁכָּתוּב (ויקרא כ) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים. אָדָם מְקַדֵּשׁ עַצְמוֹ מִלְּמַטָּה - מְקַדְּשִׁים אוֹתוֹ מִלְמַעְלָה. וּכְשֶׁמִּתְקַדֵּשׁ אָדָם בִּקְדֻשַּׁת רִבּוֹנוֹ, מַלְבִּישִׁים (מורישים) אוֹתוֹ נְשָׁמָה קְדוֹשָׁה, יְרֻשַּׁת הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל, וְאָז יוֹרֵשׁ אֶת הַכֹּל. וְאֵלּוּ הֵם שֶׁנִּקְרָאִים בָּנִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא, כְּמוֹ שֶׁכָּתוּב (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, כָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, וּפֵרְשׁוּהָ נֶפֶשׁ חַיָּה סְתָם. וּמֵאוֹתוֹ חֵלֶק יָרַשׁ דָּוִד הַמֶּלֶךְ וְנִקְשַׁר בְּקֶשֶׁר עֶלְיוֹן וְיָרַשׁ מַלְכוּת, כְּמוֹ שֶׁנֶּאֱמַר. וּמִשּׁוּם כָּךְ וְהָיְתָה נֶפֶשׁ אֲדנִי צְרוּרָה בִּצְרוֹר הַחַיִּים. וַהֲרֵי פֵּרְשׁוּהָ שֶׁנֶּפֶשׁ נִקְשֶׁרֶת בְּרוּחַ, וְרוּחַ עִם נְשָׁמָה, וּנְשָׁמָה עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹרֵשׁ הַיְרֻשָּׁה הָעֶלְיוֹנָה הַזּוֹ.</p>\n<p>אוֹי לְאוֹתָם הָרְשָׁעִים שֶׁנַּפְשׁוֹתֵיהֶם אֵינָן זוֹכוֹת בָּעוֹלָם הַזֶּה, וְכָל שֶׁכֵּן בָּעוֹלָם הָבָּא, עֲלֵיהֶם כָּתוּב וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. שֶׁהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם וְלֹא מוֹצְאִים מָקוֹם לִמְנוּחָה לְהִתְקַשֵּׁר בּוֹ, וְנִטְמָאִים (ונשאבים) בְּתוֹךְ צַד הַטֻּמְאָה, וְהַכָּרוֹז קוֹרֵא וְאוֹמֵר: נֶפֶשׁ כִּי תִמְעֹל מַעַל בַּה'. מִקְדַּשׁ ה' טִמֵּא. שֶׁהֲרֵי לַקְּדֻשָּׁה לֹא נִכְנַס, וְלֹא נִכְלַל. וְהֵם מַזִּיקֵי הָעוֹלָם, מִשּׁוּם שֶׁנִּדְבָּקִים בָּהֶם וְנִטְמָאִים.</p>\n<p>רַבִּי יִצְחָק אָמַר, הֲרֵי פֵּרְשׁוּהָ נֶפֶשׁ, כְּשֶׁמִּתְעַטֶּרֶת כְּנֶסֶת יִשְׂרָאֵל בַּמֶּלֶךְ הַקָּדוֹשׁ מִתְעַטֶּרֶת וְנִקְרֵאת צְרוֹר הַחַיִּים, מִשּׁוּם שֶׁבָּהּ הַכֹּל נִקְשָׁר. רַבִּי אֶלְעָזַר אָמַר, כְּשֶׁשְּׁכִינָה נוֹסַעַת, הִיא נוֹסַעַת עִם הָאָבוֹת. זֶהוּ שֶׁכָּתוּב (שמות יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ וְגוֹ'.</p>\n<p>רַבִּי אַבָּא אָמַר, הַכֹּל נַעֲשָׂה עֲטָרָה אַחַת, כְּדֵי שֶׁיִּתְעַטֵּר כְּאֶחָד, וְהַשֵּׁם הַקָּדוֹשׁ נִרְאֶה בְתוֹכָם (בצורותיו). בְּאוֹתָהּ שָׁעָה נִקְרָא (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים. וְהָיוּ יִשְׂרָאֵל רוֹאִים אֶת זִיו הַכָּבוֹד הָעֶלְיוֹן נוֹסֵעַ לִפְנֵיהֶם. וְזֶהוּ שֶׁשָּׁנִינוּ, (דברים ד) וַיּוֹצִאֲךְ בְּפָנָיו בְּכֹחוֹ הַגָּדֹל מִמִּצְרָיִם. אֵלּוּ הָאָבוֹת. וּמִשּׁוּם כָּךְ הַשֵּׁם הַזֶּה מְשַׁבֵּר הָרִים וּמְשַׁבֵּר סְלָעִים, וְיֵשׁ בּוֹ לְטוֹב וּלְרַע. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל.</p>\n<p>רעיא מהימנא מִצְוָה זוֹ, הַמּוֹעֵל בְּהֶקְדֵּשׁ צָרִיךְ לְהָבִיא קֶרֶן וְחֹמֶשׁ. זֶהוּ שֶׁכָּתוּב וְאֶת חֲמִישִׁתוֹ יוֹסֵף עָלָיו, קֶרֶן ו'. הַחֹמֶשׁ שֶׁלּוֹ ה'. וְזוֹ קֶרֶן הַיּוֹבֵל. קֶרֶן שֶׁהָיְתָה בְמִצְחוֹ שֶׁל אוֹתוֹ פַּר שֶׁהִקְרִיב אָדָם הָרִאשׁוֹן. זֶהוּ הָעִקָּר שֶׁל כָּל הַקָּרְבָּנוֹת. הַקֶּרֶן קַיֶּמֶת לוֹ לָעוֹלָם הַבָּא, וְהַפֵּרוֹת שֶׁלּוֹ בָּעוֹלָם הַזֶּה. וְזֶה ה' ה'. (ע\"כ רעיא מהימנא).</p>"],[9522011989,"<p>בֹּא רְאֵה, עֵז לְקָרְבָּן לָמָּה? וַהֲרֵי אָמַר רַבִּי שִׁמְעוֹן, עֵז - הַשֵּׁם שֶׁלּוֹ גּוֹרֵם, לִלְמֹד מִשְּׁמוֹ, שֶׁהֲרֵי צַד רַע, וּמִין רַע הוּא. אֶלָּא כָּךְ אָמַר רַבִּי שִׁמְעוֹן, אֶת זֶה צָרִיךְ לְהַקְרִיב, שֶׁהֲרֵי אִם עוֹבֶרֶת עָלָיו רוּחַ טֻמְאָה אוֹ שֶׁהִתְעַסֵּק בּוֹ, הֲרֵי עֵז קָרְבָּנוֹ, בְּאוֹתוֹ גָוֶן שֶׁהוּא חָטָא בוֹ.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ, יֵשׁ מִי שֶׁזּוֹכֶה בִּנְשָׁמָה, וְיֵשׁ מִי שֶׁזּוֹכֶה בְּהִתְעוֹרְרוּת הָרוּחַ, וְיֵשׁ מִי שֶׁאֵינוֹ זוֹכֶה אֶלָּא רַק בְּנֶפֶשׁ. זֶה מִי שֶׁלֹּא זוֹכֶה אֶלָּא רַק בְּנֶפֶשׁ, וְלֹא עוֹלֶה יוֹתֵר, זֶה נִדְבָּק בְּאוֹתוֹ צַד שֶׁל הַטֻּמְאָה, וּכְשֶׁהוּא יָשֵׁן, אוֹתָם צְדָדִים רָעִים בָּאִים וְנִדְבָּקִים בּוֹ וּמוֹדִיעִים לוֹ בַּחֲלוֹם דְּבָרִים שֶׁל הָעוֹלָם, מֵהֶם כּוֹזְבִים, וּמֵהֶם אֱמֶת. וְלִפְעָמִים שֶׁצּוֹחֲקִים עִמּוֹ וּמַרְאִים לוֹ דִּבְרֵי שֶׁקֶר, וּמְצַעֲרִים אוֹתוֹ בַּחֲלוֹמוֹ. וְעַל כָּךְ אֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה, מֵהֶם שֶׁרוֹאִים בַּחֲלוֹמָם דִּבְרֵי אֱמֶת, מִשּׁוּם אוֹתוֹ צַד שֶׁנִּדְבָּקִים בּוֹ, וְכֻלָּם דְּבָרִים לִזְמַן קָרוֹב.</p>\n<p>בֹּא רְאֵה, בַּמִּינִים הָרָעִים הַלָּלוּ יֵשׁ שָׁלֹשׁ דְּרָגוֹת אֵלּוּ עַל אֵלּוּ. הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁלָּהֶם הֵם אוֹתָם שֶׁתְּלוּיִים בָּאֲוִיר. הַדַּרְגָּה הַיּוֹתֵר תַּחְתּוֹנָה שֶׁלָּהֶם הֵם אוֹתָם שֶׁצּוֹחֲקִים עִם בְּנֵי אָדָם וּמְצַעֲרִים אוֹתָם בַּחֲלוֹמוֹתֵיהֶם, מִשּׁוּם שֶׁכֻּלָּם חֲצוּפִים כְּמוֹ כְּלָבִים. וְיֵשׁ דַּרְגָּה עֶלְיוֹנָה עֲלֵיהֶם, שֶׁהֵם מֵעֶלְיוֹנִים וּמִתַּחְתּוֹנִים, וְאֵלּוּ מוֹדִיעִים לָאָדָם דְּבָרִים, מֵהֶם כּוֹזְבִים וּמֵהֶם אֲמִתִּיִּים, וְאֵלּוּ הַדְּבָרִים הָאֲמִתִּיִּים כֻּלָּם לַזְּמַן הַקָּרוֹב.</p>\n<p>וְאוֹתָהּ דַּרְגָּה מֵאוֹתָם הַתְּלוּיִים בָּאֲוִיר, שֶׁהֵם יוֹתֵר עֶלְיוֹנִים. אוֹתוֹ שֶׁלֹּא זוֹכֶה יוֹתֵר מֵאֲשֶׁר בַּנֶּפֶשׁ, וְאוֹתָהּ נֶפֶשׁ רוֹצָה לְהִתְתַּקֵּן וּלְקַבֵּל רוּחַ, טֶרֶם שֶׁהִרְוִיחָה אוֹתָהּ. יוֹצֵא מַה שֶּׁיּוֹצֵא מֵאוֹתָהּ מֵאוֹתָהּ הַנֶּפֶשׁ, וּמִתְפַּשֶּׁטֶת בָּעוֹלָם, וְרוֹצֶה לַעֲלוֹת וְלֹא רוֹצָה, עַד שֶׁפּוֹגֶשֶׁת בְּאוֹתָם שֶׁבָּאֲוִיר, וְהֵם מוֹדִיעִים לָהּ דְּבָרִים, מֵהֶם קְרוֹבִים וּמֵהֶם יוֹתֵר רְחוֹקִים, וּבְאוֹתָהּ דַּרְגָּה הוּא הוֹלֵךְ וְנִקְשָׁר בַּחֲלוֹמוֹ עַד שֶׁקּוֹנֶה רוּחַ.</p>\n<p>כֵּיוָן שֶׁקּוֹנֶה רוּחַ, אוֹתָהּ רוּחַ יוֹצֵאת, מְשַׁבֵּר הָרִים וּסְלָעִים, עוֹלֶה וּמִתְפַּשֵּׁט וְנִכְנָס בֵּין מַלְאָכִים עֶלְיוֹנִים קְדוֹשִׁים, וְשָׁם יוֹדֵעַ מַה שֶּׁיּוֹדֵעַ, וְלוֹמֵד דְּבָרִים, וְחוֹזֵר לִמְקוֹמוֹ. אָז הוּא קֶשֶׁר שֶׁל בֶּן אָדָם בִּקְדֻשָּׁה, עַד שֶׁזּוֹכֶה בִנְשָׁמָה וְקוֹנֶה אוֹתָהּ.</p>\n<p>כֵּיוָן שֶׁקּוֹנֶה נְשָׁמָה, הִיא עוֹלָה לְמַעְלָה לְמַעְלָה, וְשׁוֹמְרֵי הַפְּתָחִים לֹא מְעַכְּבִים אוֹתָהּ, וְהוֹלֶכֶת וּמִתְפַּשֶּׁטֶת וְנִכְנֶסֶת בֵּין אוֹתָם הַצַּדִּיקִים שֶׁצְּרוּרִים בִּצְרוֹר הַחַיִּים, וְשָׁם רוֹאָה אֶת עֹנֶג הַמֶּלֶךְ וְנֶהֱנֵית מִן הַזִּיו הָעֶלְיוֹן.</p>\n<p>וּכְשֶׁמִּתְעוֹרֶרֶת הָאַיֶּלֶת הַקְּדוֹשָׁה בְּרוּחַ צָפוֹן, יוֹרֶדֶת, וְעוֹמֵד אוֹתוֹ צַדִּיק שֶׁקָּנָה אוֹתָהּ, וּמִתְגַּבֵּר כְּמוֹ אַרְיֵה חָזָק בַּתּוֹרָה, עַד שֶׁבָּא הַבֹּקֶר וְהוֹלֵךְ עִם אוֹתָהּ הָאַיֶּלֶת הַקְּדוֹשָׁה לְהֵרָאות לִפְנֵי הַמֶּלֶךְ, לְקַבֵּל חוּט אֶחָד שֶׁל חֶסֶד. וּמִיהוּ זֶה? חוּט שֶׁל אַבְרָהָם, שֶׁהוּא קָנָה אוֹתוֹ, שֶׁכָּתוּב (בראשית יד) אִם מִחוּט וְעַד שְׂרוֹךְ נַעַל. הוּא לֹא נֶהֱנֶה מֵאַחֵר כְּלוּם, וְאָמַר אִם מִחוּט, זָכָה לַחוּט הַזֶּה, וְזֶה נִקְרָא הַחוּט שֶׁל אַבְרָהָם.</p>\n<p>וּכְשֶׁבָּא אוֹתוֹ צַדִּיק עִם הָאַיָּלָה הַזּוֹ, אֲזַי מִתְעַטֵּר עִמָּהּ לִפְנֵי הַמֶּלֶךְ, וְדָוִד אָמַר (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר, זוֹ כְּנֶסֶת יִשְׂרָאֵל. אַיֶּלֶת הַשַּׁחַר - הַשִּׁירָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל שֶׁאוֹמְרִים בַּגָּלוּת אֵלִי אֵלִי לָמָה עֲזַבְתָּנִי וְגוֹ'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵיהֶם בַּעֲלֵי הַנְּשָׁמָה, בַּעֲלֵי הַתּוֹרָה, בְּנֵי עֲבוֹדָתוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ. אוֹי לְאוֹתָם הָרְשָׁעִים שֶׁאֵין זוֹכִים לְהִדָּבֵק בְּרִבּוֹנָם וְלֹא זוֹכִים בַּתּוֹרָה, שֶׁכָּל מִי שֶׁלֹּא זוֹכֶה בַּתוֹרָה, לֹא זוֹכֶה לֹא בְרוּחַ וְלֹא בִנְשָׁמָה, וְהַהִדָּבְקוּת שֶׁלָּהֶם בְּאוֹתוֹ הַצַּד שֶׁל הַמִּינִים הָרָעִים. וְלָזֶה אֵין חֵלֶק בַּמֶּלֶךְ הַקָּדוֹשׁ, אֵין לוֹ חֵלֶק שֶׁל קְדֻשָּׁה. אוֹי לוֹ כְּשֶׁיֵּצֵא מִן הָעוֹלָם הַזֶּה, שֶׁהוּא הוּא מֻכָּר לְאוֹתָם הַמִּינִים הָרָעִים, בַּעֲלֵי הַחֻצְפָּה, עַזִּים כְּמוֹ כֶּלֶב, שְׁלִיחֵי אֵשׁ הַגֵּיהִנֹּם, שֶׁאֵין מְרַחֲמִים עֲלֵיהֶם.</p>\n<p>בֹּא וּרְאֵה מַה בֵּין יִשְׂרָאֵל לָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה. יִשְׂרָאֵל, אַף עַל גַּב שֶׁלֹּא זוֹכֶה אִישׁ יִשְׂרָאֵל אֶלָּא בְּנֶפֶשׁ, דַּרְגָּה עֶלְיוֹנָה עוֹמֶדֶת עָלָיו, וְאִם הוּא רוֹצֶה לִקְנוֹת רוּחַ וְאִם הוּא רוֹצֶה לִקְנוֹת נְשָׁמָה, הוּא קוֹנֶה וְזוֹכֶה בָּהּ. אֲבָל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה לֹא קוֹנִים לְעוֹלָמִים, פְּרָט לְאִם נִמּוֹל, שֶׁאָז קוֹנֶה נֶפֶשׁ (תחת נפש) מִמָּקוֹם אַחֵר.</p>\n<p>וְיִשְׂרָאֵל שֶׁעוֹמְדִים בְּדַרְגָּה תַחְתּוֹנָה בַּנֶּפֶשׁ, אִם אֵינוֹ רוֹצֶה לִזְכּוֹת יוֹתֵר, עָנְשׁוֹ רַב. אוֹי לְאוֹתוֹ רָשָׁע שֶׁשָּׁכַח אֶת מִצְווֹת הַתּוֹרָה וְלֹא הִשְׁתַּדֵּל בַּתּוֹרָה, שָׁכַח אֶת אֲדוֹנוֹ, עָלָיו כָּתוּב יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ.</p>\n<p>וּבֹא רְאֵה, יֵשׁ בְּנֵי אָדָם שֶׁנִּדְבָּקִים בַּצַּד הַזֶּה מִשּׁוּם אוֹתָהּ (בזו) נֶפֶשׁ ל שֶׁלֹּא זָכוּ יוֹתֵר, וּכְשֶׁעוֹבֶרֶת עֲלֵיהֶם אוֹתָהּ רוּחַ טֻמְאָה, שׁוֹרָה עֲלֵיהֶם וְנִדְבָּקִים בָּהּ. אֲזַי אוֹתוֹ הַחֵטְא שֶׁחוֹטֵא הָאָדָם הוּא מִצַּד שֶׁל אוֹתָהּ רוּחַ טֻמְאָה, וְקָרְבָּנוֹ הוּא עֵז אַחַת, מִשּׁוּם שֶׁהִיא בְּהֵמָה שֶׁבָּאָה מֵאוֹתוֹ צַד לְכַפֵּר עַל חֶטְאוֹ.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר בְּנוֹ, וַהֲרֵי כָּתוּב (דברים כא) לֹא תָלִין נִבְלָתוֹ עַל הָעֵץ וְגוֹ', וְלֹא תְטַמֵּא אֶת אַדְמָתְךְ. מִשּׁוּם שֶׁהָאָרֶץ הִיא קְדוֹשָׁה, (ובמקום ששורה) וְרוּחַ טֻמְאָה לֹא תִמְצָא מָקוֹם בָּאָרֶץ הַקְּדוֹשָׁה לִשְׁרוֹת עָלָיו. אִם כָּךְ, כֵּיוָן שֶׁעַל אוֹתָהּ בְּהֵמָה שׁוֹרָה רוּחַ טֻמְאָה, וְהִיא בָּאָה מִצִּדֶּיהָ, לָמָּה מַקְרִיבִים אוֹתָהּ לְצַד הַקְּדֻשָּׁה? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ.</p>\n<p>אֲבָל בֹּא רְאֵה, בְּנִי. כָּתוּב (שם ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא. יֵשׁ אֵשׁ אוֹכֶלֶת אֵשׁ. הָאֵשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹכֶלֶת אֵשׁ אַחֶרֶת. וּבֹא רְאֵה, יֵשׁ מַלְאָכִים שֶׁאוֹמְרִים שִׁירָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְבַּטְּלִים כְּשֶׁהֵם מְסַיְּמִים אֶת אוֹתָהּ הַשִּׁירָה בְּנִיצוֹץ שֶׁל אֵשׁ אוֹכֶלֶת. לְמַטָּה מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא אֵשׁ שֶׁל הַמִּזְבֵּחַ, וְהָאֵשׁ הַזּוֹ אוֹכֶלֶת וּמַשְׁמִידָה אֶת כָּל אוֹתוֹ הַצַּד, וְאוֹתוֹ הַצַּד מִתְבַּטֵּל בְּאוֹתָהּ שַׁלְהֶבֶת שֶׁל אֵשׁ וְלֹא מַשְׁאִירָה מִמֶּנּוּ בָּעוֹלָם. וְאוֹתוֹ אָדָם שֶׁמַּקְרִיב אֶת קָרְבָּנוֹ עוֹמֵד עָלָיו, וּבְאוֹתוֹ הָרֵיחַ שֶׁל הַקָּרְבָּן שֶׁעוֹלֶה, עוֹבֵר מִמֶּנּוּ הַצַּד שֶׁל רוּחַ הַטֻּמְאָה שֶׁשּׁוֹרָה עָלָיו וּמִתְכַּפֵּר. מִשּׁוּם כָּךְ הַכֹּל מִתְבַּטֵּל וּמֻשְׁמָד, וְאֵין מִי שֶׁעוֹמֵד בִּפְנֵי אוֹתָהּ אֵשׁ.</p>"],[9522011990,"<p>רַבִּי אָחָא הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְרַבִּי חִיָּיא וְרַבִּי יוֹסֵי נִפְגְּשׁוּ כְאֶחָד. אָמַר רַבִּי אָחָא, וַדַּאי אָנוּ שְׁלֹשָׁה עֲתִידִים לְקַבֵּל פְּנֵי שְׁכִינָה. הִתְחַבְּרוּ יַחַד וְהָלְכוּ. אָמַר רַבִּי אָחָא, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר קָשׁוּר לַתּוֹרָה, וְנֵלֵךְ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (ישעיה מה) הַרְעִיפוּ שָׁמַיִם מִמַּעַל וְגוֹ'. הַפָּסוּק הַזֶּה הוּא סוֹד שֶׁל חָכְמָה שֶׁלָּמַדְנוּ מֵהַמְּנוֹרָה הַקְּדוֹשָׁה. הַרְעִיפוּ שָׁמַיִם מִמַּעַל, מַה זֶּה הִרְעִיפוּ? כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) יַעֲרֹף כַּמָּטָר לִקְחִי. וְעַל הַצַּד שֶׁל הַמָּטָר שֶׁהוּא הַמָּזוֹן שֶׁל הַכֹּל הוּא אָמַר. וְעַל כֵּן כָּל עֵינֵי הָעוֹלָם מְצַפִּים לַקָּדוֹשׁ-בָּרוּךְ-הוּא לַמְּזוֹנוֹת, מִשּׁוּם שֶׁהוּא נוֹתֵן מָזוֹן לַכֹּל וְזָן אֶת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ וְגוֹ'.</p>\n<p>וְאִם תֹּאמַר שֶׁבַּמָּקוֹם הַזֶּה שֶׁנִּקְרָא שָׁמַיִם הַדָּבָר תָּלוּי - הֲרֵי שָׁנִינוּ, שֶׁלֹּא בִזְכוּת הַדָּבָר תָּלוּי, וּזְכוּת הֲרֵי פֵּרְשׁוּהָ זוֹ צְדָקָה. וְתַרְגּוּם שֶׁל צְדָקָה - זְכוּת. וּזְכוּת וְשָׁמַיִם זֶה דָּבָר אֶחָד, וְכָאן הַרְעִיפוּ שָׁמַיִם. (ואם תאמר בו תלוי) כָּתוּב מִמַּעַל, מִמַּעַל וַדַּאי. מֵהָעַתִּיק הַקָּדוֹשׁ זֶה בָּא, וְלֹא מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, וְנִקְרָא זְכוּת, אֶלָּא מִמַּעַל דַּוְקָא</p>\n<p>וּשְׁחָקִים יִזְּלוּ צֶדֶק. שֶׁכְּשֶׁשָּׁמַיִם נוֹטֵל אוֹתוֹ מִמַּעַל מֵאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁשּׁוֹרֶה עָלָיו, אֲזַי שְׁחָקִים יִזְּלוּ צֶדֶק. מִי הַשְּׁחָקִים? זֶה הַמָּקוֹם שֶׁטּוֹחֲנִים מָן לַצַּדִּיקִים. וּמִי הֵם? נֵצַח וְהוֹד, שֶׁהֵם וַדַּאי טוֹחֲנִים מָן לַצַּדִּיקִים. לְמִי? לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא צַדִּיק, שֶׁהֲרֵי הֵם טוֹחֲנִים אֶת אוֹתוֹ הַמָּן שֶׁבָּא מִלְמַעְלָה, וְכָל אוֹתוֹ טוּב מִתְכַּנֵּס בְּתוֹכָם לָתֵת אוֹתוֹ לְדַרְגָּה שֶׁל צַדִּיק, כְּדֵי שֶׁיִּתְבָּרְכוּ צֶדֶק מֵאוֹתָהּ נְזִילָה שֶׁלָּהֶם, וְעַל זֶה טוֹחֲנִים מָן לַצַּדִּיקִים. מִי הֵם הַצַּדִּיקִים? זֶה צַדִּיק וְצֶדֶק, יוֹסֵף וְרָחֵל, שֶׁכְּשֶׁמִּזְדַּוְּגִים כְּאֶחָד נִקְרְאוּ צַדִּיקִים.</p>\n<p>וְאֵלּוּ טוֹחֲנִים מָן לַצַּדִּיקִים וַדַּאי, וְעַל כֵּן - וּשְׁחָקִים יִזְּלוּ צֶדֶק. אָז תִּפְתַּח אֶרֶץ - לְמַטָּה. וְיִפְרוּ יֶשַׁע - בְּנֵי הָעוֹלָם. וּצְדָקָה תַצְמִיחַ יַחַד - כָּל הָרַחֲמִים וְכָל הַטּוֹב שֶׁל הָעוֹלָם מִתְרַבִּים, וּמְזוֹנוֹתֵיהֶם שֶׁל בְּנֵי אָדָם מְצוּיִים בָּעוֹלָם, אָז נוֹסֶפֶת שִׂמְחָה עַל שִׂמְחָה, וְכָל הָעוֹלָמוֹת מִתְבָּרְכִים. אָמַר רַבִּי אָחָא, אִלְמָלֵא לֹא בָאתִי אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי לִי.</p>"],[9522011991,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שופטים ה) לִבִּי לְחוֹקְקֵי יִשְׂרָאֵל הַמִּתְנַדְּבִים בָּעָם בָּרֲכוּ ה'. בֹּא רְאֵה, כָּל הָרָצוֹן וְכָל הַלֵּב שֶׁצָּרִיךְ אָדָם לְהָרִיק בְּרָכוֹת מִמַּעְלָה לְמַטָּה, לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, לְבַקֵּשׁ בִּתְפִלָּה לַקָּדוֹשׁ- בָּרוּךְ-הוּא בְּרָצוֹן וּבְכַוָּנַת הַלֵּב, לְהַשְׁפִּיעַ מֵאוֹתוֹ הַנַּחַל הֶעָמֹק, כְּמוֹ שֶׁכָּתוּב (תהלים קל) מִמַּעֲמַקִּים קְרָאתִיךְ ה', שֶׁשָּׁם הָעֹמֶק שֶׁל הַכֹּל, בָּעֳמָקִים הָעֶלְיוֹנִים, שֶׁהֵם הָרֵאשִׁית הָעֶלְיוֹנָה שֶׁאָב וָאֵם מִזְדַּוְּגִים. אַף כָּאן לִבִּי לְחוֹקְקֵי יִשְׂרָאֵל, מִי הֵם חוֹקְקֵי יִשְׂרָאֵל? לֹא כָתוּב חֲקוּקֵי יִשְׂרָאֵל, אֶלָּא לְחוֹקְקֵי, אֵלּוּ אַבָּא וְאִמָּא שֶׁהֵם מְחוֹקְקִים לְיִשְׂרָאֵל הַקָּדוֹשׁ שֶׁהוּא שׁוֹפֵעַ מִבֵּינֵיהֶם.</p>\n<p>הַמִּתְנַדְּבִים בָּעָם - אֵלּוּ הֵם הָאָבוֹת שֶׁנִּקְרָאִים נְדִיבִים, כְּמוֹ שֶׁנֶּאֱמַר נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם. אָז בָּרֲכוּ ה', לְהַשְׁפִּיעַ מִמֶּנּוּ בְּרָכוֹת לְמַטָּה, וְיִמָּצְאוּ בְרָכוֹת בָּעוֹלָם כֻּלָּם, שֶׁכְּשֶׁכָּאן נִמְצָאוֹת בְּרָכוֹת מִלְמַעְלָה, אָז הַכֹּל בְּשִׂמְחָה וְהַכֹּל בִּשְׁלֵמוּת. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵרִיק עֲלֵיהֶם בְּרָכוֹת וּמַקְשִׁיב לִתְפִלָּתָם, וַעֲלֵיהֶם כָּתוּב, פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָּתָם וְגוֹ'.</p>"],[9522011992,"<p>זֹאת תּוֹרַת הָעֹלָה וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרַשְׁנוּהוּ וְנִתְבָּאֵר. בֹּא רְאֵה, הָעוֹלָה הַזּוֹ מַעֲלָה וְקוֹשֶׁרֶת אֶת כְּנֶסֶת יִשְׂרָאֵל לְמַעְלָה, וְהַדְּבֵקוּת שֶׁלָּהּ בְּתוֹךְ הָעוֹלָם הַבָּא לִהְיוֹת הַכֹּל אֶחָד בְּקֶשֶׁר אֶחָד, בְּשִׂמְחָה. וּמִשּׁוּם שֶׁעוֹלָה לְמַעְלָה לְמַעְלָה, כָּתוּב זֹּאת תּוֹרַת, סוֹד שֶׁל זָכָר וּנְקֵבָה יַחַד, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה לַעֲלוֹת בַּחֲבִיבוּת.</p>\n<p>כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן, כְּמוֹ שֶׁבֵּאַרְנוּהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, אֲזַי הִיא עוֹלָה בַּחֲבִיבוּת, וּמִתְעַטֶּרֶת בְּיָמִין, וּמִתְחַבֶּרֶת עִם הָאֶמְצָעִי, וְהַכֹּל מֵאִיר מִסּוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, וְזֶה מִתּוֹךְ סוֹד שֶׁל אָדָם, בִּרְצוֹן הַכֹּהֵן וּבִתְפִלָּה וּבְשִׁירָה.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ שֶׁעוֹלָה קֹדֶשׁ קָדָשִׁים בְּסוֹד הָרוּחַ הָעֶלְיוֹנָה, מִשּׁוּם שֶׁשָּׁלֹשׁ רוּחוֹת קְשׁוּרוֹת כְּאַחַת: הָרוּחַ הַתַּחְתּוֹנָה שֶׁנִּקְרֵאת רוּחַ הַקֹּדֶשׁ, הָרוּחַ שֶׁלְּפָנִים בָּאֶמְצַע, שֶׁנִּקְרֵאת רוּחַ חָכְמָה וּבִינָה, וְכֵן הָרוּחַ הַתַּחְתּוֹנָה. אֲבָל הָרוּחַ הַזּוֹ שֶׁיּוֹצֵאת מִתּוֹךְ שׁוֹפָר, כְּלוּלִים בְּאֵשׁ וּמַיִם. הָרוּחַ הָעֶלְיוֹנָה שֶׁהִיא סְתוּמָה בַּחֲשַׁאי, שֶׁבָּהּ מִתְקַיְּמִים כָּל הָרוּחוֹת הַקְּדוֹשׁוֹת וְכָל הַפָּנִים מְאִירוֹת, וּמִשּׁוּם כָּךְ חוֹזֶרֶת הָעוֹלָה רוּחַ מַמָּשׁ.</p>\n<p>וְאַחַר כָּךְ מִסּוֹד שֶׁל הַבְּהֵמָה נֶהֱנִים וְנִזּוֹנִים לְהִתְקַשֵּׁר לְרוּחַ אַחֶרֶת, שֶׁהִיא בְּתוֹךְ הַטֻּמְאָה מֵאוֹתָם חֲלָבִים וְשֻׁמָּנִים, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמִשּׁוּם כָּךְ עוֹלָה קֹדֶשׁ קָדָשִׁים, שְׁאָר הַקָּרְבָּנוֹת כֻּלָּם כְּדֵי לַעֲשׂוֹת שָׁלוֹם בָּעוֹלָם מִכַּמָּה צְדָדִים וּבַעֲלֵי דִינִים, לְהַעֲבִיר וְלִהְיוֹת נָאוֹר מִתּוֹךְ הָרָצוֹן לְהִתְבַּשֵּׂם, וְנִקְרָאִים קָדָשִׁים קַלִּים, מִשּׁוּם שֶׁלֹּא מִתְעַטְּרִים לְמַעְלָה לְמַעְלָה בְּקֹדֶשׁ הַקְּדָשִׁים. וְעַל זֶה הֵם קָדָשִׁים קַלִּים וּשְׁחִיטָתָם בְּכָל מָקוֹם, כְּמוֹ שֶׁבֵּאֲרוּהָ. אֲבָל הָעוֹלָה, שֶׁהִיא סוֹד שֶׁל קֹדֶשׁ הַקְּדָשִׁים, אֵינָהּ כִּשְׁאָר קָרְבָּנוֹת, שֶׁכָּל מַעֲשֶׂיהָ קֹדֶשׁ.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד, הַלְּבוּשִׁים הַלָּלוּ מְיֻחָדִים לִקְדֻשָּׁה, בַד יְחִידִי, מְיֻחָד לִקְדֻשָּׁה. וְכָתוּב בִּגְדֵי קֹדֶשׁ הֵם וְרָחַץ בַּמַּיִם אֶת בְּשָׂרוֹ וּלְבֵשָׁם. מָה הַטַּעַם זֶה קֹדֶשׁ? אֶלָּא סוֹד הַדָּבָר, כְּמוֹ שֶׁאָמַר שֶׁהִיא קֹדֶשׁ קָדָשִׁים, שֶׁהַכֹּל עוֹלֶה וּמִתְעַטֵּר בְּקֹדֶשׁ הַקְּדָשִׁים בְּקֶשֶׁר אֶחָד, וְאַחַר כָּךְ מְפַנֶּה וּמַעֲבִיר רוּחַ טֻמְאָה, שֶׁמְּטַמֵּא הַכֹּל, שֶׁלֹּא יִשְׁלֹט וְלֹא יִקְרַב לְתוֹךְ הַמִּקְדָּשׁ, וּמָעֳבָר מִכָּל צִדְדֵי הַקְּדֻשָּׁה, וְהַכֹּל נִשְׁאָר קֹדֶשׁ בִּקְדֻשָּׁה יְחִידָה.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, הֲרֵי נִתְבָּאֵר, שֶׁכָּתוּב (תהלים לד) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. וְכָךְ עוֹלֶה סוֹד שֶׁל אָדָם מִצַּד שֶׁל אָדָם. בְּהֵמָה - מִצַּד שֶׁל בְּהֵמָה. וּמִשּׁוּם כָּךְ כָּתוּב אָדָם כִּי יַקְרִיב מִכֶּם, אָדָם וַדַּאי, שֶׁהֲרֵי קָרְבָּנוֹ לְמַעְלָה לִקְשֹׁר קֶשֶׁר, וְאַחַר מִן הַבְּהֵמָה. וְהַכֹּל הוּא בַּכָּתוּב - אָדָם וּבְהֵמָה. וְזֶהוּ סוֹד שֶׁצָּרִיךְ לְקָרְבָּן - אָדָם וּבְהֵמָה, כְּמוֹ שֶׁאָמַר. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּךְ עָשָׂה - אָדָם וּבְהֵמָה.</p>"],[9522011993,"<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב עוֹף יְעוֹפֵף עַל הָאָרֶץ, שֶׁהֲרֵי מֵהֶם מַקְרִיבִים קָרְבָּן, וַאֲפִלּוּ עוֹלָה, כְּמוֹ שֶׁכָּתוּב וְאִם מִן הָעוֹף עֹלָה קָרְבָּנוֹ - בֹּא רְאֵה, מִכָּל אוֹתָם עוֹפוֹת אֵין מַקְרִיבִים אֶלָּא מִן הַתּוֹרִים אוֹ בְּנֵי יוֹנָה, אֶלָּא סוֹד זֶה - מַה שֶּׁהֻכְשַׁר בָּזֶה, פָּסוּל בָּזֶה. זֶה יָמִין וְזֶה שְׂמֹאל, וְהַכֹּל אֶחָד.</p>\n<p>עוֹף יְעוֹפֵף עַל הָאָרֶץ, הֲרֵי בֵּאַרְנוּ שֶׁהֵם סוֹד הַמֶּרְכָּבָה, וּבָהֶם תִּתְעַלֶּה רוּחַ הַקֹּדֶשׁ לַעֲלוֹת לְמַעְלָה, שֶׁהֵם שְׁנַיִם, אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל. הָעוֹף לְיָמִין, וְזֶה מִיכָאֵל. יְעוֹפֵף לִשְׂמֹאל, וְזֶה גַבְרִיאֵל. זֶה לְיָמִין, וְזֶה לִשְׂמֹאל.</p>\n<p>וּמִשּׁוּם כָּךְ מַקְרִיבִים שְׁנֵי אֵלֶּה, כְּדֵי לְהַעֲלוֹת אֶת רוּחַ הַקֹּדֶשׁ, וְהַשְּׂמֹאל מְעַטֵּר וּמֵזִין לְמַטָּה, לְאוֹתוֹ הַצַּד שֶׁל הַשְּׂמֹאל, וְיָמִין וְיָמִין, וְאִשָּׁה נִקְשֶׁרֶת לְבַעְלָהּ לִהְיוֹת אֶחָד, וְהַכֹּל מִתְעַלֶּה וּמִתְקַשֵּׁר כְּאֶחָד, לְמַעְלָה וּלְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה לְבַדּוֹ וּמִתְחַזֵּק.</p>\n<p>וּבַסְּפָרִים הַקַּדְמוֹנִים, הֶעָנִי לֹא נוֹתֵן חֵלֶק לְהָזִין אֶלָּא לְהִתְקַשֵּׁר לְמַעְלָה, אֲבָל הַכֹּל - לְמַעְלָה וּלְמַטָּה - כָּל אֶחָד נִקְשָׁר לְצִדּוֹ כָּרָאוּי, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011994,"<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו וְאָמַר, הֲרֵי הַקֶּשֶׁר שֶׁל הַכֹּל נִקְשָׁר בְּקֹדֶשׁ הַקְּדָשִׁים כְּדֵי לְהָאִיר, הִדָּבְקוּת שֶׁל הָרָצוֹן שֶׁל כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים לְמַעְלָה, עַד הֵיכָן הִיא עוֹלָה?</p>\n<p>אָמַר לוֹ, הֲרֵי בֵּאַרְנוּ, עַד אֵין סוֹף. שֶׁכָּל קֶשֶׁר וְיִחוּד וּשְׁלֵמוּת, לְהַצְנִיעַ בְּאוֹתָהּ צִנְעָה שֶׁאֵינָהּ מֻשֶּׂגֶת וְלֹא נוֹדַעַת שֶׁבָּהּ רְצוֹן כָּל הָרְצוֹנוֹת. אֵין סוֹף אֵינוֹ עוֹמֵד לְהִוָּדַע, וְלֹא לַעֲשׂוֹת סוֹף, וְלֹא לַעֲשׂוֹת רֹאשׁ שֶׁל אַיִן (ראשכמו שאין). הָרִאשׁוֹן הוֹצִיא רֹאשׁ וָסוֹף, מִי הָרֹאשׁ? זוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה, שֶׁהִיא רֹאשׁ שֶׁל הַכֹּל הַנִּסְתָּר שֶׁעוֹמֶדֶת בְּתוֹךְ הַמַּחֲשָׁבָה. וְעוֹשָׂה סוֹף, שֶׁנִּקְרָא סוֹף דָּבָר, אֲבָל לְשָׁם אֵין סוֹף.</p>\n<p>אֵין רְצוֹנוֹת וְאֵין אוֹרוֹת וְאֵין נֵרוֹת בְּאוֹתוֹ אֵין סוֹף. כָּל הָאוֹרוֹת וְהַמְּאוֹרוֹת הַלָּלוּ תְּלוּיִים לְהִתְקַיֵּם בָּהֶם, וְלֹא עוֹמְדִים לְהַשָּׂגָה, מִי שֶׁיּוֹדֵעַ וְלֹא יוֹדֵעַ, אֵינוֹ אֶלָּא רָצוֹן עֶלְיוֹן נִסְתָּר שֶׁל כָּל הַנִּסְתָּריִם, אַיִן.</p>\n<p>וּכְשֶׁהַנְּקֻדָּה הָעֶלְיוֹנָה וְהָעוֹלָם הַבָּא הִתְעַלּוּ, אֵינָם יוֹדְעִים פְּרָט לְרֵיחַ, כְּמִי שֶׁהֵרִיחַ רֵיחַ וְהִתְבַּשֵּׂם, וְאֵין זֶה נַחַת (ניחח), שֶׁהֲרֵי כָּתוּב וְלֹא אָרִיחַ בְּרֵיחַ נִיחֹחֲכֶם, שֶׁהֲרֵי רֵיחַ נִיחֹחַ הוּא רֵיחַ שֶׁל רָצוֹן, שֶׁכָּל הָרְצוֹנוֹת הַלָּלוּ שֶׁל תְּפִלָּה, וְרָצוֹן שֶׁל שִׁירָה, וּרְצוֹן הַכֹּהֲנִים, שֶׁכֻּלָּם סוֹד שֶׁל אָדָם, אֲזַי כֻּלָּם נַעֲשִׂים רָצוֹן אֶחָד. וְהַהוּא נִקְרָא נִיחֹחַ, רָצוֹן כְּתַרְגּוּמוֹ. אָז הַכֹּל נִקְשָׁר וּמֵאִיר כְּאֶחָד כָּרָאוּי, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְעַל כֵּן נִתָּן הַצַּד הָאַחֵר בְּיַד הַכֹּהֵן, שֶׁכָּתוּב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. סוֹד כָּאן, שֶׁהֲרֵי בֵּאַרְנוּ, אֵין צַו אֶלָּא עֲבוֹדָה זָרָה. וְכָאן נִתָּן לוֹ לִשְׂרֹף אֶת אוֹתָהּ מַחֲשָׁבָה רָעָה וּלְהַעֲבִירָהּ מִתּוֹךְ הַקֹּדֶשׁ בָּרָצוֹן הַזֶּה שֶׁעוֹלֶה לְמַעְלָה, וּבֶעָשָׁן הַזֶּה וּבַחֲלָבִים שֶׁנִּשְׂרָפִים, כְּדֵי שֶׁיָּעָבְרוּ מִן הַקֹּדֶשׁ, וְהַצַּו הַזֶּה עוֹמֵד בִּרְשׁוּתָם לְהַפְרִידוֹ מִן הַקֹּדֶשׁ מִתּוֹךְ הַקָּרְבָּן הַזֶּה. וְאִם תֹּאמַר, צַו אֶת בְּנֵי יִשְׂרָאֵל - כָּךְ גַּם שֶׁהֲרֵי בִּרְשׁוּתָם עוֹמֵד (להפריש אותה מן הקדשה) כָּל זְמַן שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם, שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם.</p>\n<p>וְהַפָּסוּק הַזֶּה הַכֹּל בָּא לְהַרְאוֹת סוֹד הַדָּבָר, לְעַטֵּר אֶת רוּחַ הַקֹּדֶשׁ לְמַעְלָה לְמַעְלָה, וּלְהַפְרִיד אֶת רוּחַ הַטֻּמְאָה וּלְהוֹרִידָהּ לְמַטָּה לְמַטָּה, וְזֶה בְּרָצוֹן וּבִתְפִלָּה כְּפִי שֶׁאָמַרְנוּ, וְזֶה בְּמַעֲשֶׂה, הַכֹּל כְּמוֹ שֶׁרָאוּי לוֹ.</p>\n<p>וְהַכָּתוּב הַזֶּה מוֹכִיחַ עֲלֵיהֶם, שֶׁכָּתוּב צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. צַו - זוֹ עֲבוֹדָה זָרָה, רוּחַ הַטֻּמְאָה. לֵאמֹר - זוֹ הָאִשָּׁה, שֶׁנִּקְרֵאת יִרְאַת ה'. כָּתוּב כָּאן לֵאמֹר, וְכָתוּב שָׁם (ירמיה ג) לֵאמֹר הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ, וַהֲרֵי פֵּרְשׁוּהָ. מִשּׁוּם כָּךְ הַכֹּל נֶאֱמַר, וְהַכֹּהֵן עוֹמֵד לְתַקֵּן אֶת הַכֹּל בְּסוֹד שֶׁל אָדָם וּבְהֵמָה.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֵם יוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה וְהוֹלְכִים בָּהּ בְּדֶרֶךְ אֱמֶת, עֲלֵיהֶם כָּתוּב (ישעיה לא) ה' עֲלֵיהֶם יִחְיוּ. מִי עֲלֵיהֶם? אֵלּוּ דַּרְכֵי הַתּוֹרָה. יִחְיוּ - יִתְקַיְּמוּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011995,"<p>בֹּא רְאֵה, כָּתוּב זֹּאת תּוֹרַת הָעֹלָה. אָמַר רַבִּי חִיָּיא, הַפָּסוּק הַזֶּה בֵּאַרְנוּהוּ בַּצּוּרָה הַזּוֹ: (זאת תורת זו כנסת ישראל. העלה שהיא עולה ומתעטרת למעלה למעלה להתקשר כראוי, עד המקום שנקרא קדש קדשים).</p>\n<p>(דבר אחר) זֹּאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - זוֹ מַחֲשָׁבָה רָעָה שֶׁהִיא עוֹלָה עַל רְצוֹנוֹ שֶׁל הָאָדָם לְהָסִיט אוֹתוֹ מִדֶּרֶךְ אֱמֶת. הִיא הָעֹלָה - הִיא שֶׁעוֹלָה וּמַשְׂטִינָה עַל הָאָדָם, וְצָרִיךְ לִשְׂרֹף אוֹתָהּ בָּאֵשׁ כְּדֵי לֹא לָתֵת לָהּ מָקוֹם לְהַשְׂטִין.</p>\n<p>וּמִשּׁוּם כָּךְ, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מִי הַלַּיְלָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא זֹּאת, מִשּׁוּם שֶׁבָּאָה לְטַהֵר אֶת הָאָדָם מֵאוֹתוֹ רָצוֹן. עַל מוֹקְדָה, מִשּׁוּם שֶׁנְּהַר דִּינוּר הוּא מָקוֹם לִשְׂרֹף כָּל אֵלּוּ שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שֶׁהֲרֵי מַכְנִיסִים אוֹתָם בְּאוֹתָהּ אֵשׁ בּוֹעֶרֶת וּמַעֲבִירִים אֶת שִׁלְטוֹנָם מִן הָעוֹלָם, וּכְדֵי שֶׁלֹּא יִשְׁלֹט, צָרִיךְ עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְנִכְנָע וְלֹא שׁוֹלֵט.</p>\n<p>וְלָכֵן, כְּשֶׁזֶּה נִכְנָע, עוֹלָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא רוּחַ הַקֹּדֶשׁ שֶׁעוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה, שֶׁהֲרֵי עֲלִיָּתָהּ זֶה כְּשֶׁנִּכְנָע הַכֹּחַ הָאַחֵר הַזֶּה וְנִפְרָד מִמֶּנָּה, וְלָכֵן צְרִיכִים בְּסוֹד הַקָּרְבָּן, לְהַפְרִיד אֶת הַצַּד הַזֶּה מֵרוּחַ הַקֹּדֶשׁ, וְלָתֵת לוֹ חֵלֶק, כְּדֵי שֶׁרוּחַ הַקֹּדֶשׁ תִּתְעַלֶּה לְמַעְלָה.</p>\n<p>רַבִּי אָחָא פָּתַח וְאָמַר, וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ וְגוֹ'. וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ, לָמָּה? וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר, לָמָּה? וְכֹהֵן לָמָּה? וַהֲרֵי שָׁנִינוּ שֶׁאֵשׁ בְּכָל מָקוֹם הִיא דִּין, וְהַכֹּהֵן בָּא מִצַּד הַיָּמִין, וְרָחוֹק הוּא מִן הַדִּין, שֶׁהֲרֵי אֵין כֹּהֵן מִזְדַּמֵּן לְדִין לְעוֹלָמִים, וְכָאן הוּא צָרִיךְ לִשְׂרֹף דִּין בָּעוֹלָם, שֶׁכָתוּב וּבִעֵר עָלֶיהָ הַכֹּהֵן?</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, אָדָם שֶׁבָּא לַחֲטֹא לִפְנֵי רִבּוֹנוֹ, הוּא שׂוֹרֵף אֶת עַצְמוֹ בְּשַׁלְהֶבֶת הַיֵּצֶר הָרָע, וְיֵצֶר הָרָע בָּא מִצַּד שֶׁל רוּחַ הַטֻּמְאָה, וַהֲרֵי שׁוֹרָה בּוֹ רוּחַ טֻמְאָה. וְלִפְעָמִים נוֹדָעִים הַקָּרְבָּנוֹת שֶׁבָּאִים מֵהַצַּד הַזֶּה, וְצָרִיךְ לְהַקְרִיב עַל הַמִּזְבֵּחַ אֶת מַה שֶּׁדּוֹמֶה לוֹ, וְלֹא מִתְכַּלָּה וְלֹא מִתְבַּטֶּלֶת אוֹתָהּ רוּחַ הַטֻּמְאָה בֵּין מֵהָאָדָם וּבֵין מֵאוֹתוֹ הַצַּד שֶׁבָּא מִמֶּנּוּ, אֶלָּא רַק בָּאֵשׁ שֶׁל הַמִּזְבֵּחַ, שֶׁאוֹתָהּ הָאֵשׁ מַבְעֶרֶת אֶת רוּחַ הַטֻּמְאָה וּמִינִים רָעִים מִן הָעוֹלָם. וְהַכֹּהֵן מִתְכַּוֵּן בָּזֶה לְתַקֵּן אֵשׁ שֶׁתְּבַעֵר מִינִים רָעִים מִן הָעוֹלָם.</p>\n<p>וְלָכֵן צָרִיךְ שֶׁלֹּא תִכְבֶּה לְעוֹלָמִים וְלֹא יֶחֱלַשׁ הַכֹּחַ וְהַתֹּקֶף שֶׁלָּהּ, כְּדֵי לשְׁבֹּר הַכֹּחַ הָרָע הָאַחֵר מִן הָעוֹלָם, וְלָכֵן לֹא תִכְבֶּה. וְהַכֹּהֵן יְסַדֵּר עָלֶיהָ אֵשׁ בַּבֹּקֶר בַּבֹּקֶר, בִּזְמַן שֶׁשּׁוֹלֵט הַצַּד שֶׁלּוֹ וּמִתְעוֹרֵר בָּעוֹלָם כְּדֵי לְבַשֵּׂם אֶת הָעוֹלָם (ולבסם הדין), וְהַדִּינִים נִכְנָעִים וְלֹא מִתְעוֹרְרִים בָּעוֹלָם. וְעַל זֶה שָׁנִינוּ, יֵשׁ אֵשׁ אוֹכֶלֶת אֵשׁ. אֵשׁ שֶׁלְּמַעְלָה אוֹכֶלֶת אֵשׁ אַחֶרֶת, אֵשׁ הַמִּזְבֵּחַ אוֹכֶלֶת אֵשׁ אַחֶרֶת. וְעַל זֶה הָאֵשׁ הַזּוֹ לֹא תִכְבֶּה לְעוֹלָמִים, וְהַכֹּהֵן מְסַדֵּר אוֹתָהּ בְּכָל יוֹם.</p>"],[9522011996,"<p>מִצְוָה לַעֲשׂוֹת הָעוֹלָה כְּמִשְׁפָּטָהּ, וְעָלֶיהָ נֶאֱמַר זֹּאת תּוֹרַת הָעֹלָה וְגוֹ'. חֲמִשָּׁה אִשִּׁים הָיוּ יוֹרְדִים עַל הַקָּרְבָּן: אֵשׁ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. אֵשׁ שׁוֹתֶה וְאֵינוֹ אוֹכֵל. אֵשׁ אוֹכֵל וְשׁוֹתֶה. אֵשׁ אוֹכֵל לַחִים וִיבֵשִׁים. אֵשׁ שֶׁאֵינוֹ אוֹכֵל וְאֵינוֹ שׁוֹתֶה. כְּנֶגְדָּם הֵם: זֹּאת תּוֹרַת הָעֹלָה - אַחַת. הִיא הָעֹלָה עַל מוֹקְדָה - שְׁתַּיִם. עַל הַמִּזְבֵּחַ - שָׁלֹשׁ. כָּל הַלַּיְלָה - אַרְבַּע. וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ - חָמֵשׁ.</p>\n<p>וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הָעוֹלָה כֻּלָּהּ עוֹלָה לְגָבוֹהַּ, וְזוֹ בִּינָה, ה', ה' מַרְאוֹת שֶׁלָּהּ. י' בַּת יְחִידָה, (שמות כג) וּמַרְאֵה כְּבוֹד ה' כְּאֵשׁ אֹכֶלֶת. ו' אוֹר שֶׁל בַּת עַיִן, וְהִיא אֵשׁ שׁוֹתָה כָּל הַמַּיִם שֶׁל הַתּוֹרָה, וְאוֹכֶלֶת אֶת כָּל הַקָּרְבָּנוֹת שֶׁל הַתְּפִלָּה. וְאוֹכְלִים לַחִים וִיבֵשִׁים, אוֹתָם פְּשָׁטֵי הַתּוֹרָה שֶׁהֵם כְּמוֹ עֵצִים יְבֵשִׁים, וְסוֹדוֹת הַתּוֹרָה הֵם כְּמוֹ עֵצִים לַחִים. וְזוֹהִי אֵשׁ הָאוֹכֶלֶת לַחִים וִיבֵשִׁים.</p>\n<p>וְעוֹד אוֹכֶלֶת לַחִים, כָּל הַקָּרְבָּנוֹת שֶׁהָיוּ קְרֵבִים בִּתְפִלָּה עַל מִצְווֹת עֲשֵׂה. וִיבֵשִׁים - כָּל הַקָּרְבָּנוֹת שֶׁהָיוּ קְרֵבִים בִּתְפִלָּה עַל מִצְווֹת לֹא תַעֲשֶׂה. וְזֶהוּ סְקִילָה שְׂרֵפָה הֶרֶג וְחֶנֶק, עַל מִצְווֹת עֲשֵׂה, וְעַל מִצְווֹת לֹא תַעֲשֶׂה. אֵלּוּ הֵם הַקָּרְבָּנוֹת שֶׁל הַשְּׁכִינָה, תְּפִלָּה, שֶׁל מִצְווֹת עֲשֵׂה וְלֹא תַעֲשֶׂה. וּכְנֶגֶד חֲמֵשׁ הַמַּרְאוֹת הַלָּלוּ תִּקְּנוּ חָמֵשׁ תְּפִלּוֹת בְּיוֹם הַכִּפּוּרִים. וּכְנֶגֶד בַּת עַיִן אוֹתָם עֲשֶׂרֶת יְמֵי תְשׁוּבָה. חֲמִשָּׁה כְּנֶגֶד הָאוֹר שֶׁל בַּת עַיִן. חֲמִשָּׁה עִנּוּיִים כְּנֶגֶד ה' אַחֲרוֹנָה.</p>\n<p>הַמִּצְוָה אַחַר זוֹ, לַעֲשׂוֹת אֶת הַחַטָּאת כְּמִשְׁפָּטָהּ. תַּנָּאִים וְאָמוֹרָאִים, אַתֶּם שֶׁמִּצַּד מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאתֶם, שֶׁטְּרַחְתֶּם הַרְבֵּה לְנַקּוֹת אֶת הַבַּת שֶׁלִּי, שֶׁהִיא הֲלָכָה, מֵאוֹתָן הַקְּלִפּוֹת שֶׁל עֵרֶב רַב, שֶׁהֵן קֻשְׁיוֹת רָעוֹת שֶׁאֵין לָהֶם תֵּרוּץ וְלֹא פֵרוּק, שֶׁעֲלֵיהֶם נֶאֱמַר (קהלת א) מְעֻוָּת לֹא יוּכַל לִתְקֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת, אֶלָּא נֶאֱמַר בָּהֶם תִּיקוּ. וְכָל תִּיקוּ שֶׁל אִסּוּר - לְחֻמְרָה. וְהוּא תִּיקוּ חָסֵר ן', שֶׁאֵין לוֹ תִּקּוּן. חָסֵר נוּן, שֶׁהוּא הָעוֹלָם הַבָּא, שֶׁתִּיקוּ שֶׁל הָעוֹלָם הַבָּא שְׁתִיקָה, כְּמוֹ: שְׁתֹק, כָּךְ עָלָה בְּמַחֲשָׁבָה.</p>\n<p>וְיִשִׁ קֻשְׁיוֹת שֶׁהֵן הַלְּבוּשִׁים שֶׁל הֲלָכָה, שֶׁנֶּאֱמַר בָּהֶם מִשְׁבְּצוֹת זָהָב. זֶהוּ שֶׁכָּתוּב (תהלים מה) כָּל כְּבוּדָּה בַּת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ. וְאַתֶּם פּוֹסְקִים אוֹתָם בְּכַמָּה פְסָקִים, וְאַחַר כָּךְ מְתַקְּנִים וּמְיַשְּׁבִים אוֹתָם בְּכַמָּה פֵרוּקִים.</p>\n<p>וְאִם חָסֵר פְּסָק כָּלְשֶׁהוּ מִן הַמִּשְׁנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ זֶה חָסֵר מִן הַמִּשְׁנָה, אַתֶּם מְתַקְּנִים אוֹתָם, וְזֶהוּ חֶסְרוֹן שֶׁיּוּכַל לְהִמָּנוֹת. וְאִם יָבֹא טִפֵּשׁ וְיוֹצִיא שֵׁם רַע עַל אוֹתוֹ אָמָּן שֶׁחוֹתֵךְ לְבוּשִׁים, וְיֹאמַר: וְכִי הַתּוֹרָה הִיא חֲסֵרָה?! וַהֲרֵי כָּתוּב תּוֹרַת ה' תְּמִימָה, תְּמִימָה בְּכָל אֵיבְרֵי הַגּוּף, שֶׁהֵם רמ\"ח מִצְווֹת, זֶהוּ שֶׁכָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ, תְּמִימָה בִלְבוּשֶׁיהָ, וְאֵיךְ חָסֵר מִן הַמִּשְׁנָה?</p>\n<p>אַתֶּם תֹּאמְרוּ לוֹ: דַּיֵּק וְתִמְצָא חֲתִיכָה, וְתִמְצָא אוֹתָהּ מְעֹרֶבֶת עִם שְׁאָר פְּסָקִים וּמִשְׁנָיוֹת. שֶׁדֶּרֶךְ הָאָמָּן לַחְתֹּךְ לְבוּשִׁים לְכַמָּה חֲתִיכוֹת, וְהַתַּלְמִיד שֶׁאֵינוֹ בָּקִי לִקְשֹׁר אֶת הַהֲלָכָה בַּחֲתִיכוֹת הַלָּלוּ, מִתְחַלְּפוֹת לוֹ פְּסָקוֹת וְקֻשְׁיוֹת וְלֹא מוֹצֵא לָהֶם פֵּרוּק, עַד שֶׁיָּבֹא הָאָמָּן וּמְפָרֵק אוֹתָם אֶת כָּל הַסְּפֵקוֹת הַלָּלוּ שֶׁלָּהֶם. בְּאוֹתוֹ זְמַן, הֲלָכָה שֶׁהִיא בַּת, עוֹלָה לִפְנֵי הַמֶּלֶךְ שְׁלֵמָה בַּכֹּל, בְּגוּפָהּ בִּלְבוּשָׁהּ וּבְתַכְשִׁיטֶיהָ, וּמִתְקַיֵּם בָּהּ (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְלִפְעָמִים יֵשׁ לָאָמָּן תַּלְמִיד בָּקִי שֶׁיִּשְׁלַח לוֹ לְתַקֵּן אוֹתָם.</p>\n<p>קָמוּ כֻלָּם וְאָמְרוּ, וַדַּאי שֶׁאַתָּה הוּא הָאָמָּן, רוֹעֶה הַנֶּאֱמָן, שֶׁבְּךְ נֶאֱמַר מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וּמִשָּׁם וְאֵילָךְ כָּל הַתַּלְמִידִים הֵם שֶׁלְּךְ, מִיהוֹשֻׁעַ וְעַד סוֹף כָּל הַדּוֹרוֹת. זֶהוּ שֶׁאָמַר וּמְסָרָהּ לִיהוֹשֻׁעַ, וִיהוֹשֻׁעַ לִזְקֵנִים, וּזְקֵנִים לִנְבִיאִים, עַד הַסּוֹף שֶׁל כֻּלָּם. הַתַּלְמִיד הַבָּקִי שֶׁלְּךְ מִי הוּא? הֲרֵי רָאִינוּ שֶׁנֶּאֱמַר, הַכֹּל יְהֵא מֻנָּח עַד שֶׁיָּבא אֵלִיָּהוּ.</p>\n<p>אָמַר לָהֶם, וַדַּאי כָּךְ זֶה, שֶׁהוּא תַּלְמִיד חָבֵר, שֶׁעָלָיו נֶאֱמַר (במדבר כה) בֶּן אַהֲרֹן הַכֹּהֵן, כְּמוֹ שֶׁנֶּאֱמַר בְּאַהֲרֹן, (שמותד) הוּא יִהְיֶה לְּךְ לְפֶה, כָּךְ גַּם בְּנוֹ יִהְיֶה לִי לְפֶה, שֶׁהִיא הַתּוֹרָה שֶׁבְּעַל פֶּה. מִשּׁוּם שֶׁאֵיךְ שֶׁהָיִיתִי בָּרִאשׁוֹנָה כְּבַד פֶּה וּכְבַד לָשׁוֹן, וְכָךְ יָקִים אוֹתִי הַקָּדוֹשׁ בָּרוּךְ הוּא - כְּבַר פֶּה בַּתּוֹרָה שֶׁבְּעַל פֶּה, וּכְבַד לָשׁוֹן בַּתּוֹרָה שֶׁבִּכְתָב, שֶׁלֹּא יֹאמְרוּ אֵלּוּ שֶׁלֹּא מַכִּירִים אוֹתִי, זֶה מִישֶׁהוּ אַחֵר. וְאֵלִיָּהוּ הוּא יִהְיֶה לִי לְפֶה, יָבֹא לְתַקֵּן אֶת כָּל הַסְּפֵקוֹת הַלָּלוּ וּלְיַשֵּׁב אוֹתָם.</p>\n<p>בְּאוֹתוֹ זְמַן - זֹּאת תּוֹרַת הָעֹלָה, הַבַּת, שֶׁהָיְתָה לְחוּצָה שְׁפָלָה בַגָּלוּת, עוֹלָה עַל כָּל הַדְּרָגוֹת שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה, וַעֲלִיָּתָהּ תִּהְיֶה לְאַבָּא שֶׁהוּא לְיָמִין שֶׁל חֶסֶד, שֶׁבּוֹ הָרוֹצֶה לְהַחְכִּים יַדְרִים, מִשָּׁם חָכְמָ\"ה, כ\"ח מ\"ה.</p>\n<p>אָמַר תַּנָּא אֶחָד, וַדַּאי שֶׁבִּגְלַל כָּךְ נֶאֱמַר בְּךְ, מוֹלִיךְ לִימִין מֹשֶׁה, מִשּׁוּם הַכַּלָּה שֶׁלְּךְ שֶׁלֹּא תִהְיֶה לְךְ שְׁלֵמוּת אֶלָּא עִמָּהּ. שֶׁכְּשֶׁאַתָּה תִהְיֶה שָׁלֵם עִמָּהּ, נֶאֱמַר בְּךְ פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת. בְּמַרְאֶה, כְּמוֹ כַּלָּה שֶׁפּוֹשֶׁטֶת מַלְבּוּשֶׁיהָ וּמִתְיַחֶדֶת עִם בַּעְלָהּ בְּקֵרוּב בָּשָׂר, בְּרָמָ\"ח אֵיבָרִים שֶׁלָּהּ, וְלֹא מְכַסָּה אֵיבָר אֶחָד מִמֶּנָּה. וְזֶה בְּמַרְאֶה, רמ\"ח בְּחֶשְׁבּוֹן (ראוי לה שנאמר בו).</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, בָּרִאשׁוֹנָה נִרְאָה לְךְ הַמַּרְאֶה הַזֶּה, שֶׁנֶּאֱמַר בּו בְּמַרְאֶה, שֶׁהוּא לְךְ הַמַּרְאֶה הַגָּדול בַּסְּנֶה שֶׁנִּזְכַּר בּו חָמֵשׁ פְּעָמִים הַסְּנֶה. וְכָעֵת הִתְגַּלָּה לְךְ הַמַּרְאֶה הַזֶּה בְּרמ\"ח מִצְווֹת שֶׁהֵם בַּחֲמִשָּׁה חֻמְשֵׁי תוֹרָה. וְלֹא בְחִידת, שֶׁאוֹתָם לְבוּשִׁים שֶׁלָּהּ, שֶׁבָּהֶם רָאוּ כָּל הַנְּבִיאִים. שֶׁאֵין דֶּרֶךְ שֶׁתִּתְגַּלֶּה כַלָּה בְּקֵרוּב בָּשָׂר אֶלָּא לֶחָתָן שֶׁלָּהּ.</p>\n<p>בְּאוֹתוֹ זְמַן יִתְקַיֵּם בָּהֶם, (בראשית ב) וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ וְלֹא יִתְבֹּשָׁשׁוּ. כְּמוֹ אָדָם וְאִשְׁתּוֹ שֶׁכְּבָר הָעֳבַר הָעִרְבּוּב הָרָע שֶׁל עֵרֶב רַב, קֻשְׁיָה רָעָה מִן הָעוֹלָם, שֶׁהֵם הָעֲרָיוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, הָעֲרָיוֹת שֶׁל יִשְׂרָאֵל. כָּל שֶׁכֵּן הָעֲרָיוֹת שֶׁלְּךְ, רוֹעֶה הַנֶּאֱמָן. וּמֵהַהֲלָכָה שֶׁלְּךְ, שֶׁבִּשְׁבִילָם צָרִיךְ לְכַסּוֹת אֶת סוֹדוֹת הַתּוֹרָה, כְּמוֹ שֶׁבֵּאֲרוּהָ (משלי כה) כְּבֹד אֱלֹהִים הַסְתֵּר דָּבָר, עַד שֶׁעוֹבְרִים מִן הָעוֹלָם. וְאֵין מְלָכִים אֶלָּא יִשְׂרָאֵל, כְּמוֹ שֶׁבֵּאֲרוּהָ, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים הֵם. בְּאוֹתוֹ זְמַן, וּכְבֹד מְלָכִים חֲקֹר דָּבָר. אָמַר הָרוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לְעַתִּיק הַיָּמִים, שֶׁמִּשָּׁם אַתָּה, כְּעָנָף שֶׁמִּתְפַּשֵּׁט מִן הָאִילָן, כָּךְ הַנְּשָׁמוֹת עָנָף מִמֶּנּוּ.</p>\n<p>תַּנָּאִים וְאָמוֹרָאִים, הֲרֵי וַדַּאי עוֹלָה וְחַטָּאת וְאָשָׁם הֵן שָׁלֹשׁ מִצְווֹת, שְׁלֹשָׁה אָבוֹת. שְׁלָמִים הַגְּבִירָה. אֵיבָר שֶׁהִיא תַּשְׁלוּמִים שֶׁל כָּל אֵיבָר, כְּמוֹ הַיּוֹם הָרִאשׁוֹן שֶׁל חַג. (מקום שהוא תשלומים של הכל כדגמת).</p>\n<p>מִי שֶׁלֹּא חָג בְּיוֹם טוֹב רִאשׁוֹן, אֵין לוֹ תַּשְׁלוּמִים לָרִאשׁוֹן, וּשְׁאָר הַיָּמִים תַּשְׁלוּמִין זֶה בָזֶה, וּבָהֶם וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת. אֲבָל מִי שֶׁלֹּא חָג יוֹם טוֹב רִאשׁוֹן שֶׁל חַג, עָלָיו נֶאֱמַר מְעֻוָּת לֹא יוּכַל לִתְקֹן וְחֶסְרוֹן לֹא יוּכַל לְהִמָּנוֹת, וְזוֹהִי הַחַטָּאת שֶׁמְּעַכֶּבֶת אֶת הָעוֹלָה. (מה הטעם) הַחֵטְא הוּא זָכָר. הַחַטָּאת נְקֵבָה. וְלִפְעָמִים שֶׁהֲרֵי הַחַטָּאת מִתְבַּשֶּׂמֶת וְנִפְרֶדֶת מֵעוֹלָה בְּאוֹתוֹ שָׂעִיר, שֶׁנֶּאֱמַר (במדבר כח) וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת.</p>\n<p>אָשָׁם תָּלוּי אָחוּז בִּשְׁנֵיהֶם, כְּמִי שֶׁאוֹחֵז לְכָאן וּלְכָאן, וְהוּא תָּלוּי בָּאֶמְצַע. כְּמוֹ, הַכֹּל תָּלוּי עַד שֶׁיָּבֹא אֵלִיָּהוּ וְיַפְרִידוֹ מִשָּׁם. כָּךְ אָשָׁם תָּלוּי הוּא אָחוּז בִּשְׁנֵיהֶם עַד שֶׁנּוֹתְנִים לוֹ אֶת מְזוֹנוֹ, הַשֹּׁחַד שֶׁלּוֹ, וְיִפָּרֵד מִשָּׁם, וּמִתְקָרְבִים הָאֵיבָרִים שֶׁל הַכַּלָּה זֶה לָזֶה. שֶׁכָּךְ הוּא אָשָׁם וְחַטָּאת, כְּמוֹ סְרָכוֹת שֶׁאֲחוּזוֹת בָּרֵאָה, וְלֹא מְנִיחִים אוֹתָם לִפְרֹחַ לַעֲלוֹת כְּלַפֵּי מַעְלָה לְנַשֵּׁב בְּרוּחַ הַקֹּדֶשׁ.</p>\n<p>הַשֶּׂה הוּא לְעוֹלָה, שֶׁכָּתוּב (בראשית כב) וְאַיֵּה הַשֶּׂה לְעֹלָה. וְנֶאֱמַר בּוֹ שֶׂה תָמִים זָכָר. זֶהוּ שֶׁכָּתוּב אִישׁ תָּמִים. וַהֲרֵי צָרִיךְ לִשְׁאֹל, שֶׁהֲרֵי שֶׂה הוּא לְיָמִין, וְהַשָּׂעִיר הוּא לִשְׂמֹאל, שֶׁהַיְנוּ שְׂעִיר עִזִּים אֶחָד לְחַטָּאת. וְיֵשׁ שָׂעִיר וְיֵשׁ שָׂעִיר. שָׂעִיר אֶחָד לַה', וְשָׂעִיר אֶחָד לַעֲזָאזֵל. וְהַיְנוּ שֶׁכָּתוּב (ויקרא טז) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. וּבְאוֹתוֹ שָׂעִיר נֶאֱמַר בְּעֵשָׂו (בראשית כז) אִישׁ שָׂעִיר. וְזֶה הַכָּבֵד שֶׁנּוֹטֵל אֶת כָּל אוֹתָם הַשְּׁמָרִים שֶׁל הַדָּם - (שמשם) שְׁחִין אֲבַעְבּוּעוֹת פּוֹרְחוֹת, סַפָּחוֹת, וְכָל מִינֵי צָרַעַת. וְהַיְנוּ שֶׁכָּתוּב (ויקרא טז) וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם אֶל אֶרֶץ גְּזֵרָה. וְהֵם עֲונוֹת תָּם, שֶׁהוּא הַלֵּב, וְאָז נִפְרָד מִלְּהִתְעָרֵב בַּלֵּב, וְאָז מִתְבַּשֵּׂם, וְהוּא כָּבֵד בַּחֲטָאִים הַלָּלוּ וְלֹא קַל לַעֲלוֹת אֶל יַעֲקֹב אִישׁ תָּם. שָׂמְחוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁל הַיְשִׁיבוֹת, שֶׁיָּרְדוּ עִם הַתַּנָּאִים וְהָאָמוֹרָאִים.</p>\n<p>קָם אֶחָד מֵהֶם וְאָמַר, רוֹעֶה הַנֶּאֱמָן, תֵּן לִי רְשׁוּת לִשְׁאֹל, אַחַר שֶׁזָּכִיתִי לִשְׁמֹעַ דְּבָרִים נִכְבָּדִים אֵלּוּ מִפִּיךְ, שֶׁהַתּוֹרָה הַזּוֹ שֶׁיּוֹצֵאת מִפִּיךְ (משלי ג) יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצֶיךְ לֹא יִשְׁווּ בָהּ, וְעִם כָּל זֶה הֲלָכָה הִיא, וְלִלְמֹד אֲנִי צָרִיךְ. בַּשָּׂעִיר הַזֶּה לַעֲזָאזֵל זֶה נָאֶה, אַךְ אָשָׁם תָּלוּי בְּאֵיזֶה מָקוֹם הוּא?</p>\n<p>אָמַר לוֹ, בָּרוּךְ אַתָּה בְּנִי, יָפֶה שָׁאַלְתָּ. אֶלָּא מָה הָעַמּוּד הָאֶמְצָעִי אֲחוּזִים בּוֹ יָמִין וּשְׂמֹאל, שֶׁהֵם חֶסֶד וּגְבוּרָה, כְּמוֹ גוּף שֶׁאָחוּז בֵּין שְׁתֵּי הַזְּרוֹעוֹת שֶׁל הָאָדָם. אוֹ כְּמוֹ נֶשֶׁר, שֶׁאֲחוּזִים בּוֹ שְׁתֵּי כְנָפַיִם לִפְרֹחַ בָּהֶן. וּכְמוֹ יוֹנָה שֶׁאֲחוּזִים בָּהּ שְׁתֵּי כְנָפַיִם, שֶׁנִּמְשְׁלָה לַתּוֹרָה, וּכְנָפֶיהָ לְמִצְווֹת עֲשֵׂה, וּבָהֶן הִיא הָעוֹלָה, וּפוֹרַחַת לְמַעְלָה. כָּךְ מִצְווֹת לֹא תַעֲשֶׂה הֵן הַמַּלְכֹּדֶת שֶׁלָּהּ, כְּמוֹ צִפֳּרִים הַנֶּאֱחָזוֹת בְּפַח. וְכָל הַמַּלְכּוֹדוֹת שֶׁלָּהּ שֶׁמְּעַכְּבוֹת אוֹתָהּ מִלִּפְרֹחַ נִקְרָאוֹת סְרָכוֹת, כְּמוֹ הַסְּרָכוֹת הַלָּלוּ שֶׁמְּעַכְּבוֹת אֶת כַּנְפֵי הָרֵאָה מִלִּנְשֹׁב.</p>\n<p>כָּךָ אָשָׁם. שֶׁיִּשְׂרָאֵל אֲחוּזִים בְּכַנְפֵי הַשְּׁכִינָה, שֶׁהֵן חַיּוֹת הַכִּסֵּא, שֶׁלֹּא תִהְיֶה עוֹלָה בָהֶם בַּזְּכֻיּוֹת שֶׁל יִשְׂרָאֵל לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וּמְעַכְּבִים אוֹתָהּ, וּמַכְבִּידִים אֶת כְּנָפֶיהָ חי\"ת חי\"ת הַחַטָּאוֹת שֶׁלָּהֶם. וְאָשָׁם, אִמָּם שֶׁל עֵרֶב רַב, הַסִּרְכָה הָאֲחוּזָה בְּכִסֵּא, שֶׁשָּׁם הַגְּבִירָה, וְלֹא מְנִיחָה אוֹתָהּ לַעֲלוֹת מִן הַגָּלוּת, וְהַזְּכֻיּוֹת אֲחוּזוֹת בָּהּ לְהַעֲלוֹתָהּ, וְנִשְׁאֶרֶת בָּאֲוִיר כְּמוֹ סִרְכָה שֶׁתְּלוּיָה בָּאֲוִיר. וְזֶהוּ הָעַמּוּד הָאֶמְצָעִי (שהוא אויר). כָּךְ אָשָׁם תָּלוּי בַּצַּדִּיק, שֶׁהוּא אָחוּז בֵּין שָׁמַיִם וָאָרֶץ.</p>\n<p>הַחַטָאת הִיא יוֹתֶרֶת הַכָּבֵד, מַכְבִּידָה עָלֶיה בַּחַטָּאוֹת שֶׁל לִכְלוּכִים שֶׁל חֲטָאֵי יִשְׂרָאֵל, כְּמוֹ שֶׁהַכָּבֵד מַכְבִּיד עַל הַשְּׁמָרִים, שֶׁהֵם דָּמִים, עַל הָעֳרָקִים שֶׁל הַלֵּב. כָּךְ הַחַטָּאוֹת הַלָּלוּ מַכְבִּידוֹת עַל כַּנְפֵי הַשְּׁכִינָה, שֶׁהֵן מִצְווֹת עֲשֵׂה, שֶׁדּוֹמוֹת לְכַנְפֵי יוֹנָה. וְלֹא תַעֲשֶׂה, כְּשֶׁהֵן מַכְבִּידוֹת עַל עֲשֵׂה, שֶׁהֵן כְּשֶׁחֲטָאֵי יִשְׂרָאֵל מְרֻבִּים מִן הַזְּכֻיּוֹת, נֶאֱמַר בַּתּוֹרָה שֶׁהִיא גּוּף, (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְהִיא צוֹוַחַת, (איכה א) נְתָנַנִי ה' בִּידֵי לֹא אוּכַל קוּם, (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם.</p>\n<p>וּמִשּׁוּם זֶה תִּקְּנוּ תַּנָּאִים וְאָמוֹרָאִים תְּפִלּוֹת בִּמְקוֹם קָרְבָּנוֹת, לְהַעֲבִיר מִמֶּנָּה חַטָּאוֹת וַאֲשָׁמוֹת, וּמִשּׁוּם כָּךְ תִּקְּנוּ תְּפִלַּת שַׁחֲרִית כְּמוֹ קָרְבַּן הַשַּׁחַר, וּתְפִלַּת מִנְחָה כְּמוֹ קָרְבַּן בֵּין הָעַרְבַּיִם, וּתְפִלַּת עַרְבִית כְּמוֹ אֵמוּרִים וּפְדָרִים שֶׁהָיוּ מִתְאַכְּלִים כָּל הַלַּיְלָה. וּשְׁלֹשֶׁת הָאָבוֹת שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת, כְּנֶגֶד הַמֶּרְכָּבָה שֶׁהֵם קְשׁוּרִים בָּהּ, כְּמוֹ שֶׁבֵּאֲרוּהָ, הָאָבוֹת הֵן הֵן הַמֶּרְכָּבָה, שֶׁהֵם פְּנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם. (ע\"כ רעיא מהימנא).</p>\n<p>אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. רַבִּי חִיָּיא פָּתַח, (בראשית כב) וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיֹּאמֶר אָבִי וַיֹּאמֶר הִנֶּנִּי בְנִי וְגוֹ'. וַיֹּאמֶר וַיֹּאמֶר, שָׁלֹשׁ פְּעָמִים שֶׁל יִצְחָק, וַיֹּאמֶר אֶחָד שֶׁל אַבְרָהָם. לָמָּה זֶה כָּךְ? אֶלָּא שְׁלֹשָׁה לְמַעֲשֵׂה בְרֵאשִׁית, שֶׁהֵם הָיוּ הַשָּׁלֹשׁ שֶׁל יִצְחָק, וְאֶחָד שֶׁל אַבְרָהָם בָּרְבִיעִי, שֶׁכָּתוּב הִנֶּנִּי בְנִי, דָּחוּק (ודוקא) הִנֶּנִּי. וְכָתוּב (בראשית א) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, מְאֹרֹת חָסֵר.</p>\n<p>וְאִם תֹּאמַר, וַיֹּאמֶר וַיֹּאמֶר הֵם יוֹתֵר - אֶלָּא שֶׁהֵם הָיוּ נִסְתָּרִים בַּמַּחֲשָׁבָה, וְאֵלּוּ הִתְגַּלּוּ מִתּוֹךְ הַחֲשֵׁכָה. וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם - וְכָתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וַיֹּאמֶר אָבִי - וְכָתוּב וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. וַיֹּאמֶר הִנֵּה הָאֵשׁ - וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם. וַיֹּאמֶר הִנֶּנִּי - וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת.</p>"],[9522011997,"<p>וְעוֹד אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ' - זוֹ הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (ירמיה כג) הֲלֹא כֹה דְבָרִי כָאֵשׁ נְאֻם ה'. לֹא תִכְבֶּה וַדַּאי, שֶׁעֲבֵרָה אֵינָהּ מְכַבָּה תּוֹרָה. אֲבָל עֲבֵרָה מְכַבָּה מִצְוָה, וּמִי שֶׁעוֹבֵר עֲבֵרָה שֶׁמְּכַבָּה מִצְוָה, שֶׁהִיא נֵר, כָּךְ מְכַבֶּה אֶת נֵרוֹ, שֶׁנֶּאֱמַר (משלי ב) נֵר ה' נִשְׁמַת אָדָם, מִגּוּפוֹ, וְזֶהוּ כִבּוּי, שֶׁנִּשְׁאָר הַגּוּף בַּחֲשֵׁכָה. וְכָךְ מִי שֶׁמְּסַלֵּק שְׁכִינָה מִמְּקוֹמָהּ, גּוֹרֵם (לכל העולם) כִּבּוּי וַחֲשֵׁכָה לְאוֹתוֹ מָקוֹם. וַחֲשֵׁכָה הִיא עֲבֵרָה, (משלי ל) וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ.</p>\n<p>וַעָלִיַּת הַמִּצְוָה שֶׁל עַם הָאָרֶץ מְכַבָּה לָהֶם אֶת הַמִּצְוָה, לְקַיֵּם בָּהֶם וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמוּ. אֲבָל לְבַעֲלֵי תוֹרָה אֵין לָהּ כְּבִיָּה עוֹלָמִית בָּהֶם, שֶׁמְּאִירִים לָהּ בְּכַמָּה סוֹדוֹת שֶׁל הַתּוֹרָה, שֶׁאוֹר נִקְרָא רָ\"ז. וּמִצְווֹת הַתּוֹרָה שֶׁמְּקַיְּמִים אוֹתָן חֲכָמִים, זוֹ תוֹרָה לְגַבֵּיהֶם, לַיְלָה וְיוֹמָם לֹא תִכְבֶּה עֲלֵיהֶם, מִשּׁוּם שֶׁמְּקַיְּמִים בָּהּ וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה.</p>"],[9522011998,"<p>וְהֶעָשָׁן שֶׁעוֹלֶה מִפִּיהֶם בְּדִבְרֵי תוֹרָה, הוּא עֲשַׁן הַמַּעֲרָכָה שֶׁמְּסַדְּרִים אוֹתָהּ וְעוֹרְכִים אוֹתָהּ לְבַעְלָהּ, כְּמוֹ (במדבר ח) בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת, שֶׁנֶּאֱמַר בָּהֶם לְהַעֲלוֹת נֵר תָּמִיד. וּבַעֲשַׁן הַמַּעֲרָכָה וּבַעֲנַן הַקְּטֹרֶת, שֶׁהַתּוֹרָה הוּא הֶעָשָׁן שֶׁלָּהּ, יִתְעוֹרֵר מֵהַלֵּב לַחָכְמָה, שֶׁהוּא כְּמוֹ מֹחַ, כְּמוֹ הֶעָנָן. שֶׁהִתְעוֹרְרוּת שֶׁל הֶעָנָן הִיא מֵהַלֵּב. זֶהוּ שֶׁכָּתוּב (בראשית ב) וְאֵד יַעֲלֶה מִן הָאָרֶץ, וְאַחַר כָּךְ - וִהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה.</p>\n<p>כָּךָֹ יִתְעוֹרֵר עָשָׁן מִבִּינָה, שֶׁהִיא בַּלֵּב, שֶׁבֵּאֲרוּהָ אֶצְלוֹ, הַלֵּב מֵבִין, וְעוֹלֶה לַחָכְמָה שֶׁהִיא (במח) כְּמוֹ מֹחַ. (ומה) וּמִי הֶעָשָׁן? (דעת) זֶה הָעַמּוּד הָאֶמְצָעִי, דַּעַת, לֵב מֵבִין דַּעַת.</p>\n<p>אַחַר שֶׁיּוֹרֵד עָשָׁן, חָכְמָה לְבִינָה, שֶׁהֵם זֶה לִשְׂמֹאל וְזֶה לְיָמִין. הוּא יוֹרֵד מָלֵא מֵאַבָּא וְאִמָּא, מָלֵא י\"ה, לִשְׂרֹף עֵצִים שֶׁהֵם תַּלְמִידֵי חֲכָמִים, מִצַּד שֶׁל עֵץ הַחַיִּים, שֶׁהֵם אֵיבָרִים שֶׁל הַגּוּף, שֶׁשָּׁם ה' הָעֵצִים וַדַּאי, לִשְׂרֹף אוֹתָם בְּשַׁלְהֲבוֹת הַתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. בְּשַׁלְהֲבוֹת נֵר שֶׁל מִצְוָה בְּאַהֲבָה.</p>\n<p>מִצְוָה לְהַקְרִיב בְּכָל יוֹם תְּמִידִים וְאַחֲרָיו לְהַדְלִיק אֵשׁ. זֶהוּ שֶׁכָּתוּב אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. וְאַחֲרָיו תְּרוּמַת הַדֶּשֶׁן, וְאַחֲרָיו קָרְבַּן נֶדֶר אוֹ נְדָבָה. תַּנָּאִים וְאָמוֹרָאִים, כָּל אֵלּוּ תְּמִידִים, הֵם מִדּוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁצְּרִיכִים לִהְיוֹת לָהֶם נַחַת. וְאַף עַל גַּב שֶׁכָּל הַסְּפִירוֹת כֻּלָּן אַחַת, מִכָּל מָקוֹם כָּל סְפִירָה וּסְפִירָה מְמֻנָּה עַל שַׁבָּתוֹת וּזְמַנִּים וְיָמִים טוֹבִים, וְאוֹתָהּ מִדָּה שֶׁשּׁוֹלֶטֶת בְּאוֹתוֹ זְמַן, כָּל הַסְּפִירוֹת נִכְלָלוֹת בָּהּ, וְכֻלָּן נִקְרָאוֹת עַל שֵׁם אוֹתָהּ מִדָּה., בְּחֶסֶד חֲסָדִים, בִּגְבוּרָה גְּבוּרוֹת, וְכָךְ בְּכָל מִדָּה.</p>"],[9522011999,"<p>וְיִשִׁ הַשְׁבָּתַת מְלָאכָה, כְּמוֹ שׁוֹר שֶׁיֵּשׁ לוֹ עֹל, וַחֲמוֹר שֶׁיֵּשׁ לוֹ מַשָּׂא. בֵּין עֹל מַלְכוּת שָׁמַיִם, כְּמוֹ תְּפִלִּין, בֵּין עֹל מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, כְּפִי מַעֲשֵׂיהֶם בַּיָּמִים הַלָּלוּ יֵשׁ לָהֶם הַשְׁבָּתַת מְלָאכָה וּמְנוּחָה. מִי שֶׁלֹּא מִתְעַסֵּק בְּתוֹרָה וּבַמִּצְווֹת, יֵשׁ לוֹ עֹל מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּמִי שֶׁמִּתְעַסֵּק בְּתוֹרָה וּמִצְווֹת, יֵשׁ לוֹ עֹל מַלְכוּת שָׁמַיִם, שֶׁהִיא ה' אַחֲרוֹנָה, שֶׁנִּקְרֵאת מַלְכוּת שָׁמַיִם.</p>\n<p>עֹל מִצְווֹת הִיא וַדַּאי, מִשּׁוּם שֶׁבָּהּ נִבְרְאוּ כָּל הַבְּרִיּוֹת שֶׁל שָׁמַיִם וָאָרֶץ, זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. בְּה' בְּרָאָם. וּכְשֶׁיָּבֹא שַׁבָּת וְיוֹם טוֹב, יוֹרֶדֶת בִּינָה, שֶׁהִיא יה\"ו, עַל ה', שֶׁהִיא מַלְכוּת שָׁמַיִם נְשָׁמָה יְתֵרָה, וְהוּא (שמות לב) חָרוּת עַל הַלֻּחֹת. אָנֹכִי בִּיצִיאַת מִצְרַיִם, וּפוֹרֶשֶׂת כְּנָפֶיהָ עַל הַבַּת וְעַל הַמַּחֲנוֹת שֶׁלָּהּ, וְיֵשׁ לָהֶם מְנוּחָה. וְנֶאֱמַר בְּמַרְכְּבוֹתָיו שֶׁל סָמָאֵ\"ל וְנָחָשׁ, (דברים כח) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ. אוֹת תְּפִלִּין וְאוֹת שַׁבָּת וְאוֹת יָמִים טוֹבִים וְאוֹת בְּרִית - כֻּלָּם שְׁקוּלִים.</p>\n<p>וְיִשִׁ אוֹת שֶׁל שַׁדַּ\"י, שֶׁהוּא מטטרו\"ן עֶבֶד, וְכַמָּה עֲבָדִים תְּלוּיִים מִמֶּנּוּ, שֶׁמְּמֻנֶּה עַל אֵלּוּ שֶׁעוֹשִׂים מִצְווֹת עַל מְנָת לְקַבֵּל פְּרָס. מטטרו\"ן וְהַמַּחֲנוֹת שֶׁלּוֹ מְמֻנִּים עֲלֵיהֶם. בִּשְׁבִילָם נֶאֱמַר, לְמַעַן יָנוּחַ שׁוֹרְךְ וַחֲמוֹרְךְ וְעַבְדְּךְ וַאֲמָתְךְ. אֲבָל אוֹתָם שֶׁעוֹשִׂים מִצְווֹת שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, הֵם בְּנֵי הַמֶּלֶךְ וְהַגְּבִירָה, וְהֵם הַכְּתָרִים וְהַתָּגִים עַל הָרֹאשׁ הָעֲבָדִים בִּימוֹת הַחֹל, וּבִשְׁבִילָם נֶאֱמַר וּדְאִשְׁתַּמַּשׁ בְּתָגָא חֲלָף, וְהַזָּהר הַקָּרֵב אֲלֵיהֶם יוּמַת. שֶׁנִּקְרָאִים שַׁבָּתוֹת אֶל הָעֲבָדִים.</p>\n<p>וּמִשּׁוּם כָּךְ, אִם כְּבָנִים אִם כַּעֲבָדִים. אִם כְּבָנִים, שֶׁנֶּאֱמַר בָּהֶם בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. אִם כַּעֲבָדִים, כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים, וְלֹא שְׁאָר הָאֻמּוֹת. אֲבָל אוֹתָם הָרְשָׁעִים שֶׁאֵין מִשְׁתַּדְּלִים בַּתּוֹרָה וּבַמִּצְווֹת וְאֵין עֲלֵיהֶם עֹל תּוֹרָה וְעֹל תְּפִלִּין וּשְׁאָר מִצְווֹת, הֵם עֲבָדִים לְאֻמּוֹת הָעוֹלָם וּמִשְׁתַּעְבְּדִים בָּהֶם, כְּמוֹ עֲבָדִים הָיִינוּ לְפַרְעֹה בְּמִצְרָיִם.</p>\n<p>וְאִם שׁוֹמְרִים שַׁבָּתוֹת וְיָמִים טוֹבִים, נֶאֱמַר בָּהֶם וַיּוֹצִיאֵנוּ ה' אֱלֹהֵינוּ. וְיִתְקַיֵּם בָּהֶם, לְמַעַן יָנוּחַ שׁוֹרְךְ וַחֲמוֹרֶךְ, חֲמוֹר בַּתּוֹרָה וּבַמִּצְווֹת, וְיִנָּפֵשׁ בֶּן אֲמָתְךְ וּבְהֶמְתֶּךְ, עַם הָאָרֶץ נִקְרָא בְּהֵמָה. וְאַחַר שֶׁיַּכְנִיס אֶת עַצְמוֹ תַּחַת אָדָם בַּתּוֹרָה, יִתְקַיֵּם בּוֹ אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. אִם הוּא כְּמוֹ סוּס שֶׁרוֹכֵב עָלָיו אֲדוֹנוֹ, וְסוֹבֵל אוֹתוֹ, וְלֹא בוֹעֵט בַּאֲדוֹנוֹ.</p>\n<p>וּמַהוּ הַסֵּבֶל שֶׁעַם הָאָרֶץ לְתַלְמִיד חָכָם? מִשּׁוּם שֶׁתַּלְמִיד חָכָם כְּמוֹ יוֹם הַשַּׁבָּת הוּא צָרִיךְ, שֶׁאֵין לוֹ מִשֶּׁלּוֹ. וְאִם עַם הָאָרֶץ סוֹבֵל אוֹתוֹ בְּמָמוֹנוֹ וְנוֹהֵג בּוֹ כְּפִי רְצוֹנוֹ לְשַׁמֵּשׁ אוֹתוֹ וּלְהִתְנַהֵג בַּמִּצְווֹת כְּפִי רְצוֹנוֹ, יִתְקַיֵּם בּוֹ - אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. יוֹשִׁיעַ אוֹתוֹ מִשּׁוֹד וּמִגְּזֵלָה, יוֹשִׁיעַ אוֹתוֹ מִמַּלְאַךְ הַמָּוֶת שֶׁלֹּא יִשְׁלֹט עָלָיו וְיִשְׁחַט אוֹתוֹ בְּסַכִּינוֹ הַפְּגוּמָה. וְכָל מִי שֶׁנִּשְׁחַט בְּסַכִּין פְּגוּמָה, הוּא נְבֵלָה, שֶׁנֶּאֱמַר בּו לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ, שֶׁהוּא סָמָאֵ\"ל.</p>"],[9522012000,"<p>וְהַנֶּפֶשׁ שֶׁל תַּלְמִיד חָכָם נִקְרֵאת שַׁבָּת הַמַּלְכָּה, נֶפֶשׁ יְתֵרָה שֶׁל שַׁבָּת, וְהָעֹנֶג שֶׁלָּהּ נִשְׁמַת חַיִּים וְרוּחַ שִׂכְלִי. וְהֵם נְשָׁמָה יְתֵרָה, רוּחַ יְתֵרָה, עַל נְשָׁמָה וְרוּחַ וְנֶפֶשׁ, שֶׁהֵם עֲבָדִים שֶׁשּׁוֹלְטִים בַּגּוּף שֶׁל יְמוֹת הַחֹל. נְשָׁמָה יְתֵרָה, נִשְׁמַת כָּל חַי, כֶּתֶר הָרֹאשׁ צַדִּיק, שֶׁהוּא יוֹם הַשַּׁבָּת. וּבַנְּשָׁמָה הַיְתֵרָה הַזּוֹ תְּהַלֵּל יָהּ, שֶׁהֵם אַבָּא וְאִמָּא, שֶׁעֲלֵיהֶם נֶאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ, מִשּׁוּם שֶׁהִיא מֶרְכָּבָה לְעִלַּת הָעִלּוֹת, שֶׁהוּא מְכֻסֶּה וְלֹא שׁוֹלֶטֶת עָלָיו הָעַיִן, וּמִשּׁוּם כָּךְ עַיִן לֹא רָאָתָה.</p>\n<p>רוּחַ יְתֵרָה, הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן מִבֵּין אַבָּא וְאִמָּא, וּמַהֲלָכוֹ חֲמֵשׁ מֵאוֹת שָׁנָה, וּמַגִּיעַ לַשִּׁשִּׁי שֶׁהוּא צַדִּיק לְהַשְׁקוֹת אֶת הַגָּן, שֶׁהִיא נֶפֶשׁ יְתֵרָה, מַלְכוּת.</p>\n<p>הַנְּשָׁמָה שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל עַל עֶבֶד ה' הִיא מִכִּסֵּא הַכָּבוֹד, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַנְּשָׁמוֹת גְּזוּרוֹת מִתַּחַת כִּסֵּא הַכָּבוֹד. וְרוּחַ שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל עַל עֶבֶד ה', הִיא מֵעֶבֶד הַמֶּלֶךְ מטטרו\"ן, כּוֹלֵל שִׁשָּׁה סִדְרֵי מִשְׁנָה, וְהִיא שֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְהַנֶּפֶשׁ שֶׁשּׁוֹלֶטֶת בִּימוֹת הַחֹל הִיא מִכִּסֵּא דִין, סַנְדַּלְפוֹ\"ן, תְּכֵלֶת שֶׁבַּצִּיצִית, כְּמַעֲשֵׂה לִבְנת הַסַּפִּיר. אֲבָל בַּת הַמֶּלֶךְ, בְּפֶסַח, הִיא נֶפֶשׁ הַשִּׂכְלִית, לֵיל שִׁמּוּרִים, מַצָּה שְׁמוּרָה, וְרוּחַ שִׁמּוּר כְּנֶגְדָּהּ הִיא יוֹם טוֹב, וְהִיא יוֹם שַׁבָּת, זָכוֹר וְשָׁמוֹר, מִשּׁוּם שֶׁהִיא אֲצִילוּת מִמַּלְכוּת.</p>\n<p>וְכָךָ תַּלְמִידֵי חֲכָמִים, בְּנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, נִקְרְאוּ שַׁבָּתוֹת וְיָמִים טוֹבִים, וְאֵין לָהֶם מִשֶּׁלָּהֶם, שֶׁאֵינָם בַּעֲלֵי מְלָאכָה כְּמוֹ שְׁאָר הָעֲבָדִים בְּנֵי הַחֻלִּין. שְׂכָרָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא לְעַנֵּג אוֹתָם בְּכָל מִינֵי מַאֲכָל וּמִשְׁתֶּה, ז וּלְכַבְּדָם בלבוּשִׁים יָפִים כמו שֶׁשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ, כַּבְּדֵהוּ בִּכְסוּת נְקִיָּה. כָּל מַה שֶּׁעוֹשֶׂה אָדָם לְשַׁבָּתוֹת וְיָמִים טוֹבִים, יֵשׁ לַעֲשׂוֹת לָהֶם.</p>\n<p>וּמִי שֶׁמְּחַלֵּל שַׁבָּת חַיָּב סְקִילָה. וְכֵן מִי שֶׁמִּשְׁתַּמֵּשׁ בְּכֶתֶר חוֹלֵף. וְכָךְ מִי שֶׁמִּשְׁתַּמֵּשׁ בְּמִי שֶׁשּׁוֹנֶה הֲלָכוֹת, שֶׁמְּחַלֵּל אֶת תּוֹרָתוֹ. וְכָל שֶׁכֵּן הַמְבַזֶּה אוֹתוֹ, כְּאִלּוּ מְבַזֶּה שַׁבָּתוֹת וּמוֹעֲדוֹת. וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַמְבַזּה אֶת הַמּוֹעֲדוֹת, כְּאִלּוּ כּוֹפֵר בָּעִקָּר.</p>\n<p>וּכְמוֹ שֶׁכָּל כְּלֵי בֵּית הַמִּקְדָּשׁ שֶׁנִּקְרְאוּ קֹדֶשׁ, כָּךְ כָּל אוֹתָם שֶׁמְּשַׁמְּשִׁים תַּלְמִידֵי חֲכָמִים נִקְרָאִים קֹדֶשׁ. וְתַלְמִידֵי רַב, שֶׁהֵם כְּנֶגֶד אֵיבְרֵי הַגּוּף, נִקְרְאוּ קֹדֶשׁ קָדָשִׁים. וְסוֹד הַדָּבָר רָמוּז בָּהֶם, (שמותכו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים. וּמטטרו\"ן, אַתָּה וּמַחֲנוֹתֶיךְ, צְרִיכִים לְהַקְרִיבָם קָרְבָּן לִפְנֵי ה' בְּכָל לַיְלָה.</p>\n<p>עָשִׂיָּה, לְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם, זוֹ קַבָּלַת יִסּוּרִים שֶׁל עֲנִיּוּת לְתַלְמִיד חֲכָמִים, שֶׁהוּא מָוֶת לְגוּף הַבְּהֵמוֹת. שֶׁמְּזוֹן הַתּוֹרָה הוּא מָזוֹן שֶׁל הַנְּשָׁמָה וְרוּחַ וְנֶפֶשׁ הַשִּׂכְלִיִּים, שֶׁהֵם כֹּהֵן לֵוִי וְיִשְׂרָאֵל. הַכֹּהֵן בּוֹ י', חָכְמָה וַדַּאי. הַלֵּוִי בּוֹ ה', תְּבוּנָה. יִשְׂרָאֵל בּוֹ דַּעַת, וְזוֹ ו'. נֶפֶשׁ יְתֵרָה, ה' אַחֲרוֹנָה, רמ\"ח מִצְווֹת עֲשֵׂה וּשס\"ה לֹא תַעֲשֶׂה. וְתוֹרָה זוֹ אָדָם. זֶהוּ שֶׁכָּתוּב זֹּאת הַתּוֹרָה אָדָם. וְזֶה כּוֹלֵל אֶת הַשֵּׁם הַמְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. זוֹהִי הַתּוֹרָה מָזוֹן לָאָדָם בְּאַרְבַּע הַפָּנִים שֶׁלּוֹ. מְזוֹן הַבְּהֵמוֹת לֶחֶם וְיַיִן וּבָשָׂר וְכָל מִינֵי פֵרוֹת, (קהלת ו) זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>\n<p>וְצָרִיךָ אָדָם לְהַקְרִיב בְּכָל לַיְלָה קָרְבַּן נֶפֶשׁ וְרוּחַ וּנְשָׁמָה שֶׁל בְּהֵמוֹת לִפְנֵי ה', וְיִתְוַדֶּה בְּכַמָּה מִינֵי וִדּוּיִים, וְיַעֲלֶה אוֹתָם בְּמַחֲשַׁבְתּוֹ קָרְבָּן לִפְנֵי ה'. לְהוֹצִיא אוֹתָם בִּקְרִיאַת שְׁמַע (בלבאחד) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיוֹצִיא אֶת רוּחוֹ שֶׁדּוֹפֵק בְּעוֹרְקֵי הַלֵּב. הַנֶּפֶשׁ, יְכַוֵּן בִּשְׂרֵפָתָהּ וּבִשְׁחִיטָתָהּ וּבִנְחִירָתָהּ, שֶׁהָיוּ הַכֹּהֲנִים נוֹחֲרִים, זֶהוּ שֶׁכָּתוּב וּמָלַק אֶת רֹאשׁוֹ מִמּוּל עָרְפּוֹ וְלֹא יַבְדִּיל. וְהַיְנוּ חֶנֶק. וּשְׁלֹשׁ הַמִּיתוֹת הַלָּלוּ הָיוּ כְּמוֹ מָרָה אֲדֻמָּה, יְרֻקָּה וּשְׁחֹרָה, שֶׁהֵם בַּכָּבֵד, בַּמָּרָה וּבַטְּחוֹל, וְהֵם כִּשְׁלֹשׁ קְלִפּוֹת הָאֱגוֹז.</p>\n<p>וְקֹדֶם לָכֵן יְתַקֵּן מִזְבַּח אֲבָנִים, וִיכַוֵּן לַעֲשׂוֹת סְקִילָה מִמָּרָה הַלְּבָנָה שֶׁשּׁוֹלֶטֶת בְּכַנְפֵי רֵאָה בְּאוֹתָן סְרָכוֹת שֶׁאוֹתָן הַבְּהֵמוֹת תְּפוּסוֹת שָׁם. וְיוֹרֶדֶת אֵשׁ תְּכֵלֶת וּמְכַלָּה אוֹתָם, וְיִהְיוּ הַחַיּוֹת וְהַבְּהֵמוֹת וְהָעוֹפוֹת טְהוֹרִים לִקְרַב לַה' וּלְהַשְׁרוֹת שְׁמוֹ עֲלֵיהֶם. בְּאוֹתוֹ זְמַן יִתְקַיֵּם בָּהֶם, (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים. וְיִהְיוּ כְּמוֹ סוּס שֶׁאֲדוֹנוֹ רוֹכֵב עָלָיו. זֶהוּ שֶׁכָּתוּב (חבקוק ג) כִּי תִרְכַּב עַל סוּסֶיךְ מַרְכְּבֹתֶיךְ יְשׁוּעָה. וּבְאוֹתוֹ זְמַן - אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'.</p>\n<p>וְהַתַּלְמִיד חָכָם שָׁקוּל לְכָל בַּעֲלֵי הַתּוֹרָה, וְכָךְ צָרִיךְ לִשְׁקֹל עַצְמוֹ מִצִּדָּהּ שֶׁל הַתּוֹרָה, וּמִצַּד הָאֵיבָרִים שֶׁל הַגּוּף צָרִיךְ לִשְׁקֹל לְעַצְמוֹ לְכָל עַמֵּי הָאָרֶץ, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ כָּל הָעוֹלָם כֻּלּוֹ תָּלוּי בּוֹ. וִיכַוֵּן בְּנַפְשׁוֹ וּבְרוּחוֹ וּבְנִשְׁמָתוֹ לַעֲשׂוֹת אוֹתָם קָרְבָּנוֹת עִם כָּל בְּנֵי הָעוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה. וּבָזֶה, אָדָם וּבְהֵמָה תּוֹשִׁיעַ ה'. קָמוּ כָּל הַתַּנָּאִים וְהָאָמוֹרָאִים אֵלָיו, וְאָמְרוּ כֻלָּם בְּקוֹל אֶחָד: אַתָּה הוּא הָרוֹעֶה הַנֶּאֱמָן שֶׁיֵּשׁ לְךְ רְשׁוּת לַעֲשׂוֹת אֶת כָּל זֶה, שֶׁאַתָּה שָׁקוּל לְכָל יִשְׂרָאֵל, וּמִשּׁוּם כָּךְ שָׁלַח אוֹתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּינֵיהֶם. (ע\"כ הרעיא מהימנא).</p>\n<p>זֹאת תּוֹרָה הָעֹלָה. אָמַר רַבִּי חִיָּיא, אֶת הַפָּסוּק הַזֶּה בֵּאַרְנוּ בַּגָּוֶן הַזֶּה: זֹּאת תּוֹרַת - זוֹ כְּנֶסֶת יִשְׂרָאֵל. הָעֹלָה - זוֹ מַחֲשָׁבָה רָעָה, שֶׁעוֹלָה עַל רְצוֹנוֹ שֶׁל אָדָם לַהֲסִיטוֹ מִדֶּרֶךְ הָאֱמֶת. הִיא הָעֹלָה - הִיא הִיא שֶׁעוֹלָה לְהַסְטִין עַל הָאָדָם, וְרוֹצֶה לִשְׂרֹף אוֹתוֹ בָּאֵשׁ, כְּדֵי שֶׁלֹּא יִנָּתֵן לוֹ מָקוֹם לְהַשְׂטִין. וְלָכֵן, עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. מִי הַלַּיְלָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא זֹּאת, לְטַהֵר אֶת הָאָדָם מֵאוֹתוֹ רָצוֹן.</p>\n<p>עַל מוֹקְדָה, מִשּׁוּם שֶׁנְּהַר דִּינוּר הוּא מָקוֹם לִשְׂרֹף אֶת כָּל אֵלּוּ שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שֶׁהֲרֵי מַכְנִיסִים אוֹתָם לְאוֹתָהּ אֵשׁ בּוֹעֶרֶת וּמַעֲבִירִים אֶת שְׁלִיטָתָם מִן הָעוֹלָם. וּכְדֵי שֶׁלֹּא תִשְׁלֹט, (צריך) עַל מוֹקְדָה כָּל הַלַּיְלָה, וְתִכָּנַע וְלֹא תִשְׁלֹט.</p>"],[9522012001,"<p>כָּתוּב (מלכים א יט) וְהִנֵּה ה' עֹבֵר וְרוּחַ גְּדוֹלָה וְחָזָק וְגוֹ'. רוּחַ גְּדוֹלָה שֶׁאָמַרְנוּ, וְכָתוּב לֹא בָרוּחַ ה'. וְאַחַר הָרוּחַ רַעַשׁ, שֶׁכָּתוּב (יחזקאל א) וַתִּשָּׂאֵנִי רוּחַ וָאֶשְׁמַע אַחֲרַי קוֹל רַעַשׁ גָּדוֹל. הֲרֵי רַעַשׁ אַחַר הָרוּחַ. וְאַחַר הָרַעַשׁ אֵשׁ, זֶהוּ שֶׁכָּתוּב (דניאל ז) נְהַר דִּינוּר יוֹצֵא וְשׁוֹפֵעַ מִלְפָנָיו וְגוֹ'. רַבִּי יִצְחָק אָמַר, הַיְנוּ שֶׁכָּתוּב (יחזקאל א) וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם</p>\n<p>כְּגַחֲלֵי אֵשׁ בּעֲרוֹת כְּמַרְאֵה הַלַּפִּדִים הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת וְנֹגַהּ לָאֵשׁ וּמִן הָאֵשׁ יוֹצֵא בָרָק. וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה, הַקּוֹל הַזֶּה קוֹל אַחֲרוֹן, שֶׁהוּא דְּמָמָה דַקָּה, שֶׁאֵין לָהּ דָּבָר פְּרָט מִשֶּׁלָּהּ, אֶלָּא הִיא דּוֹמֶמֶת מֵעַצְמָהּ. וּכְשֶׁמִּתְכַּנְּסִים עָלֶיהָ, הִיא נִשְׁמַעַת בְּכָל הָעוֹלָמוֹת, וְכֻלָּם מִזְדַּעְזְעִים מִמֶּנָּה. דְּמָמָה דַקָּה, לָמָּה הִיא דַּקָּה? מִשּׁוּם (שהיא) (שבאה) הַקְּטַנָּה מִכֻּלָּן.</p>\n<p>רַבִּי חִיָּיא אָמַר, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה - זֶה אִשּׁוֹ שֶׁל יִצְחָק, שֶׁכָּתוּב (בראשית כב) הִנֵּה הָאֵשׁ וְהָעֵצִים, וְהַיְנוּ אֵשׁ תָּמִיד, שֶׁעוֹמֶדֶת תָּמִיד. וְהָעֵצִים - אֵלּוּ הָעֵצִים שֶׁל אַבְרָהָם, שֶׁכָּתוּב וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר.</p>\n<p>שָׁנִינוּ, מֵהָאֵשׁ שֶׁל יִצְחָק שׁוֹפֵעַ וּמַגִּיעַ לַמִּזְבֵּחַ הַזֶּה, וְיוֹצֵאת גַּחֶלֶת אַחַת לְצַד מִזְרָח, וְגַחֶלֶת אַחֶרֶת לְצַד מַעֲרָב, וְגַחֶלֶת אַחַת לְצַד צָפוֹן, וְגַחֶלֶת אַחַת לְצַד דָּרוֹם, לְאַרְבַּע קַרְנוֹת הַמִּזְבֵּחַ, וְהַכֹּהֵן מְסוֹבֵב אוֹתָהּ לְאַרְבַּע קְרָנוֹת.</p>\n<p>בַּמִּזְבֵּחַ (במזרח) יֵשׁ כֶּבֶשׁ אֶחָד בִּדְרָגוֹת יְדוּעוֹת, וְהַדַּרְגָּה הַתַּחְתּוֹנָה מַגִּיעָה וְיוֹרֶדֶת לַתְּהוֹם הָעֶלְיוֹן, מִתּוֹךְ שֵׁשׁ אַחַת. וּבְשָׁעָה שֶׁאוֹתָן הַגֶּחָלִים מַגִּיעוֹת לְאַרְבַּע הַקְּרָנוֹת, רוּחַ אַחַת מִתְעוֹרֶרֶת וְיוֹרֶדֶת לְאוֹתוֹ הַתְּהוֹם הָעֶלְיוֹן.</p>\n<p>וּבְאוֹתוֹ מָקוֹם יֵשׁ צְבָאוֹת צְבָאוֹת שֶׁאוֹמְרִים קָדוֹשׁ בְּקוֹל גָּדוֹל עֶלְיוֹן. וּמִצַּד אַחֵר אוֹמְרִים קָדוֹשׁ בְּקוֹל נְעִימוּת עֶלְיוֹנָה. וּמִצַּד אַחֵר צְבָאוֹת אֲחֵרִים שֶׁאוֹמְרִים קָדוֹשׁ. וְכֵן לְאַרְבַּע הַקְּרָנוֹת. שֵׁשׁ מֵאוֹת אֶלֶף רְבָבוֹת צְבָאוֹת בְּכָל קֶרֶן נִמְצָאִים, וַעֲלֵיהֶם מְמֻנֶּה אֶחָד, וְכֻלָּם לְבוּשִׁים אֵפוֹד, וְעוֹמְדִים לְסַדֵּר עֲבוֹדַת הַמִּזְבֵּחַ כְּנֶגֶד הַתַּחְתּוֹנִים.</p>\n<p>בְּמָקוֹם אַחֵר נִמְצָאִים גַּלֵּי הַיָּם שֶׁנּוֹהֲמִים וְיוֹרְדִים בִּדְרָגוֹת יְדוּעוֹת, וְשָׁם צְבָאוֹת שֶׁאוֹמְרִים בְּקוֹל נְעִימוּת, בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְכֻלָּם מְשַׁבְּחִים בְּשִׁירָה וְלֹא שׁוֹקְטִים בַּיּוֹם וּבַלַּיְלָה, וְכֻלָּם מְסַדִּרִים שֶׁבַח בְּקוֹל נְעִימוּת.</p>\n<p>בְּמָקֹוֹם אַחֵר נִמְצָאִים צְבָאוֹת צְבָאוֹת, עוֹמְדִים בְּפַחַד, בְּזִיעַ, בְּרֶתֶת, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וְנֹגַהּ לָהֶם וְיִרְאָה לָהֶם. (וגבה להם ויראה להם). וְכֻלָּם מִסְתַּכְּלִים אֶל אוֹתוֹ מִזְבֵּחַ שֶׁלְּמַעְלָה.</p>\n<p>וּבְשָׁעָה שֶׁמַּגִּיעָה הָאֵשׁ שֶׁל יִצְחָק עַל גַּבֵּי הַמִּזְבֵּחַ, כַּמָּה זִיקִים עוֹלִים וְיוֹרְדִים לְכָל עֵבֶר, וְלוֹהֲטִים מֵהֶם כַּמָּה תַקִּיפִים בַּעֲלֵי כֹחַ, גִּבּוֹרִים שֶׁל הָעוֹלָם. וְאִלְמָלֵא שֶׁהַכֹּהֵן עוֹמֵד עַל הַמִּזְבֵּחַ וּמְסַדֵּר עֵצִים, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד לִפְנֵיהֶם. מֵאֵלֶּה הַגֶּחָלִים וְהַזִּיקִים שֶׁיּוֹצְאִים, לוֹהֲטִים גַּבֵּיהֶם שֶׁל אוֹתָן חַיּוֹת, כְּמוֹ שֶׁנֶּאֱמַר וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם כְּגַחֲלֵי אֵשׁ בּעֲרוֹת כְּמַרְאֵה הַלַּפִּדִים.</p>\n<p>מִצַד יָמִין שֶׁל אוֹתָן הַחַיּוֹת מִתְעוֹרֶרֶת רוּחַ אַחַת מִלְמַעְלָה, נוֹשֶׁבֶת וְיוֹשֶׁבֶת בְּאוֹתָהּ הָאֵשׁ, וּמִתְלַהֶטֶת וּמִתְבַּשֶּׂמֶת, וְלוֹהֶטֶת, וְשׁוֹכֶכֶת בְּזִיו יָקָר, וּמְאִירָה לְכַמָּה צְבָאוֹת שֶׁעוֹמְדִים בְּצַד יָמִין. וּמִצַּד הַשְּׂמֹאל מִתְעוֹרֶרֶת רוּחַ אַחֶרֶת חֲזָקָה מְשַׁבֶּרֶת סְלָעִים וְנוֹשֶׁבֶת (ויושבת) בְּאוֹתָהּ הָאֵשׁ וּמִתְחַזֶּקֶת וּמִתְגַּבֶּרֶת. וְאָז מִתְלַבֶּשֶׁת מִמֶּנָּה אוֹתָהּ רוּחַ שֶׁמִּצַּד שְׂמֹאל, וּמְאִירָה (ולוהטת) לְכַמָּה צְבָאוֹת שֶׁעוֹמְדִים בְּאוֹתוֹ צַד, וְכֵן לְאַרְבַּעַת הַצְּדָדִים, לְאַרְבַּע מַחֲנוֹת. וְכֻלָּם מִתְבַּשְּׂמִים בְּשָׁעָה שֶׁהַכֹּהֵן עוֹלֶה עַל הַמִּזְבֵּחַ.</p>"],[9522012002,"<p>אָמַר רַבִּי אַבָּא, שְׁנֵי מִזְבְּחוֹת הֵם לְמַטָּה, וּשְׁנַיִם לְמַעְלָה, אֶחָד פְּנִימִי שֶׁל הַכֹּל, שֶׁנִּקְרֶבֶת בּוֹ הַקְּטֹרֶת הַפְּנִימִית וְדַקָּה, קֶשֶׁר הָאֱמוּנָה, וְהַכֹּהֵן הָעֶלְיוֹן מֵהַכֹּל קוֹשֵׁר (מקטיר) אֶת הַקְּטֹרֶת הַזּוֹ בְּקֶשֶׁר הָאֱמוּנָה, וְזֶה נִקְרָא מִזְבַּח הַזָּהָב. וּמִכָּאן נִקְטָר וְנִקְשָׁר קֶשֶׁר הָאֱמוּנָה בְּקֶשֶׁר אֶחָד. וּמִזְבֵּחַ אֶחָד אַחֵר שֶׁנִּקְרָא מִזְבַּח הַנְּחֹשֶׁת, וְזֶהוּ בַּחוּץ, (גדול עליון) וּמִיכָאֵל הַשַּׂר הַגָּדוֹל מַקְרִיב עָלָיו קָרְבָּן נִיחֹחַ לַקָּדוֹשׁ בָּרוּךְ הוּא. וּלְמַטָּה - מִזְבַּח הַזָּהָב וּמִזְבַּח הַנְּחֹשֶׁת, בָּזֶה קְטֹרֶת, וּבָזֶה חֲלָבִים וְאֵמוּרִים.</p>\n<p>וְעַל זֶה כָּתוּב, (משליכו) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְלֹא כָתוּב שֶׁמֶן וַחֲלָבִים וְאֵמוּרִים יְשַׂמַּח, אַף עַל גַּב שֶׁהֵם הִתְבַּשְּׂמוּת שֶׁל הָרֹגֶז וְהַדִּין. אֲבָל שֶׁמֶן וּקְטֹרֶת הֵם שִׂמְחַת הַכֹּל, וְלֹא מִצַּד הָרֹגֶז וְהַדִּין. וְהַמִּזְבֵּחַ הַזֶּה שֶׁהוּא פְּנִימִי שֶׁל קְטֹרֶת (שהם פנימיות הקטרת) דַּקָּה, בְּדַקּוּת שֶׁל הַכֹּל, בְּקֶשֶׁר הָאֱמוּנָה, נִקְרָא קוֹל דְּמָמָה דַקָּה, וּמִשּׁוּם שֶׁהוּא הַמִּזְבֵּחַ הַפְּנִימִי שֶׁנִּקְשָׁר בְּקֶשֶׁר הָאֱמוּנָה.</p>\n<p>מִזְבֵּחַ אַחֵר נִקְרָא מִזְבֵּחַ הַחִיצוֹן, וְהַפְּנִימִי נִקְרָא מִזְבַּח ה'. הָאַחֵר נִקְרָא מִזְבַּח הַנְּחֹשֶׁת, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ח) מִזְבַּח הַנְּחֹשֶׁת אֲשֶׁר לִפְנֵי ה' קָטֹן מֵהָכִיל וְגוֹ'. רַבִּי יוֹסֵי אָמַר מִכָּאן, (דברים לג) וְכָלִיל עַל מִזְבְּחֶךְ, שְׁנַיִם. וְכָתוּב עַל מִזְבְּחוֹתַי לְרָצוֹן.</p>\n<p>רַבִּי אַבָּא (אחא) אָמַר, כָּתוּב (שמות יז) וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וְגוֹ', כְּנֶגֶד אוֹתוֹ פְּנִימִי בָּנָה אֶת זֶה, וְעַל זֶה נִקְרָא ה' נִסִּי. מַה זֶּה נִסִּי? שֶׁרָשַׁם אֶת הָרֹשֶׁם שֶׁל אוֹת הַבְּרִית הַקָּדוֹשׁ. שֶׁבְּשָׁעָה שֶׁעֲמָלֵק בָּא לְהַעֲבִיר אֶת הָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה מִיִּשְׂרָאֵל, הַמִּזְבֵּחַ הַזֶּה עָמַד כְּנֶגְדּוֹ לִנְקֹם אוֹתָהּ נִקְמַת אוֹת הַבְּרִית, וְלָכֵן נִקְרָא (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וְזוֹ הִתְקִינָה לְיִשְׂרָאֵל רֹשֶׁם קָדוֹשׁ. וּמֹשֶׁה בָּנָה כְּנֶגְדָּהּ מִזְבֵּחַ, וְקָרָא לוֹ ה' נִסִּי, וְזֶהוּ מִזְבֵּחַ הַפְּנִימִי, (מלכים א יט) קוֹל דְּמָמָה דַקָּה.</p>\n<p>וְעַל כֵּן, אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ וְגוֹ', אֵשׁ שֶׁנִּמְצֵאת תָּמִיד. וּמִי הִיא? הָאֵשׁ שֶׁל יִצְחָק. וְאָז הַשֵּׁם הַזֶּה - אֲדֹנָ\"י. וּכְשֶׁיְּסַדֵּר עָלָיו הַכֹּהֵן אוֹתָם עֵצִים, הוּא מִתְבַּשֵּׂם בַּשֵּׁם, וְקוֹרְאִים לוֹ בְּשֵׁם הָרַחֲמִים - יְיָ, וְקוֹרְאִים לָהּ בַּשֵּׁם הַזֶּה. וְלִפְעָמִים עוֹמֶדֶת כְּמוֹ זֶה, וְלִפְעָמִים עוֹמֶדֶת כְּמוֹ זֶה. רַבִּי שִׁמְעוֹן אָמַר, שְׁנַיִם הָיוּ, וְהַפְּנִימִי עוֹמֵד עַל אוֹתוֹ אֶחָד שֶׁבַּחוּץ, וּמִמֶּנּוּ נִזּוֹן, וְנִקְשָׁרִים זֶה עִם זֶה.</p>\n<p>זְהִ קָרְבַּן אַהֲרֹן. רַבִּי חִזְקִיָּה פָּתַח, (תהלים קמה) צַדִּיק ה' בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו. צַדִּיק ה' בְּכָל דְּרָכָיו, הֲרֵי שָׁנִינוּ, כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִתְבּוֹנֵן בִּכְבוֹד רִבּוֹנָם שֶׁלֹּא יִסְטוּ מִדַּרְכָּם הַחוּצָה, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם הַדִּין תָּלוּי בָּעוֹלָם, מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא וְעוֹמֵד עַל הַדִּין.</p>\n<p>וְלָכֵן צָרִיךְ אָדָם לְהִשָּׁמֵר מֵחֲטָאָיו, שֶׁלֹּא יֵדַע אֶת הַזְּמַן שֶׁהַדִּין שׁוֹרֶה עָלָיו. יוֹשֵׁב בְּבֵיתוֹ - הַדִּין שׁוֹרֶה עָלָיו. יוֹצֵא מִבֵּיתוֹ הַחוּצָה - הַדִּין שׁוֹרֶה עָלָיו, וְלֹא יֵדַע אִם יָשׁוּב לְבֵיתוֹ וְאִם לֹא. יוֹצֵא לַדֶּרֶךְ - עַל אַחַת כַּמָּה וְכַמָּה, שֶׁהֲרֵי הַדִּין יוֹצֵא כְנֶגְדּוֹ. זֶהוּ שֶׁכָּתוּב (שם פה) צֶדֶק לְפָנָיו יְהַלֵּךְ. מִשּׁוּם כָּךְ צָרִיךְ לְהַקְדִּים וּלְבַקֵּשׁ רַחֲמִים מִלִּפְנֵי הַמֶּלֶךְ כְּדֵי שֶׁיִּנָּצֵל מִן הַדִּין בְּשָׁעָה שֶׁהוּא שׁוֹרֶה בָּעוֹלָם, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם שׁוֹרֶה הַדִּין בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם.</p>"],[9522012003,"<p>עֵתָּה יֵשׁ לוֹמַר, הֲרֵי שָׁנִינוּ, וְהִתְעוֹרְרוּ הַחֲבֵרִים, אֵל בְּכָל מָקוֹם חֶסֶד הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים י) הָאֵל הַגָּדֹל, וְזֶה אוֹר שֶׁל חָכְמָה עֶלְיוֹנָה, וְאַתָּה אָמַרְתָּ וְאֵל זֹּעֵם בְּכָל יוֹם. עָזַב הַפָּסוּק כָּל אֵלּוּ הַשֵּׁמוֹת וְאָחַז בָּזֶה. אִם כֵּן, לֹא עוֹמְדִים הַדְּבָרִים. וְעוֹד, שֶׁכָּתוּב (ישעיה ט) אֵל גִּבּוֹר, אוֹ שֶׁנַּעֲמִיד אוֹתוֹ בְדִין, אוֹ שֶׁנַּעֲמִיד אוֹתוֹ בְרַחֲמִים.</p>\n<p>אֶלָּא כָּךְ שָׁמַעְנוּ, הָרְשָׁעִים מְהַפְּכִים רַחֲמִים לְדִין. שֶׁאֵין לְךְ בְּכָל אֵלּוּ כְּתָרִים עֶלְיוֹנִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁלֹּא כְלוּלִים רַחֲמִים בְּדִין, וְדִין בְּרַחֲמִים. וְרְשָׁעִים מְהַפְּכִים רַחֲמִים לְדִין.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, טוֹב בָּזֶה שֶׁכָּתוּב אֵל גִּבּוֹר, אֶלָּא אֵל זֹּעֵם בְּכָל יוֹם מַהוּ? שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם עוֹמֵד בְּדִין, בֵּין שֶׁבְּנֵי הָעוֹלָם זַכָּאִים, בֵּין שֶׁלֹּא זַכָּאִים. לֹא הָיָה בְיָדוֹ. בָּאוּ וְשָׁאֲלוּ לוֹ לְרַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי אֵל זֹּעֵם בְּכָל יוֹם, וַהֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים, לְעִתִּים הוּא דִּין וּלְעִתִּים הוּא רַחֲמִים. אִם זוֹכִים בְּנֵי הָעוֹלָם, הֲרֵי אֵל עוֹמֵד, וְהוּא חֶסֶד. וְאִם לֹא זוֹכִים, הֲרֵי אֵל עוֹמֵד, וְנִקְרָא גִּבּוֹר, וְעַל זֶה עוֹמֵד בְּכָל יוֹם.</p>\n<p>אֲבָל דָּבָר נָאֶה הוּא, אֵל בְּכָל מָקוֹם זֶהוּ אוֹר (רב) הַחָכְמָה הָעֶלְיוֹנָה, וְעוֹמֵד בְּקִיּוּמוֹ בְּכָל יוֹם, שֶׁכָּתוּב (תהלים נו) חֶסֶד אֵל כָּל הַיּוֹם. וְאִלְמָלֵא שֶׁאֵל הַזֶּה מִתְעוֹרֵר בָּעוֹלָם, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד אֲפִלּוּ שָׁעָה אַחַת מִלִּפְנֵי הַדִּינִים הַקָּשִׁים שֶׁמִּתְעוֹרְרִים בָּעוֹלָם בְּכָל יוֹם. זֶהוּ שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם, בַּהִתְעוֹרְרוּת שֶׁל אַבְרָהָם עוֹמְדִים, וּכְשֶׁמִּתְעוֹרֵר אַבְרָהָם בָּעוֹלָם, כָּל אוֹתָם הַדִּינִים שֶׁנִּמְצָאִים בְּכָל יוֹם וָיוֹם, הוּא דּוֹחֶה אוֹתָם הַחוּצָה וְלֹא עוֹמְדִים לְפָנָיו.</p>\n<p>זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם. נִזְעָם אוֹ זָעוּם בְּכָל יוֹם לֹא כָתוּב, אֶלָּא זוֹעֵם. בְּכָל יוֹם וָיוֹם שֶׁנִּמְצָא דִין, דּוֹחֶה אוֹתָם הַחוּצָה, וְהוּא עוֹמֵד וּמְבַשֵּׂם אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וְאִלְמָלֵא זֶה, לֹא יָכוֹל הָעוֹלָם לַעֲמֹד אֲפִלּוּ רֶגַע אֶחָד. וְלָכֵן הַכֹּל עוֹמֵד מִשּׁוּם אַבְרָהָם.</p>\n<p>וְזְהִ שֶׁכָּתוּב אֵל גִּבּוֹר. לֹא שֶׁהוּא גִּבּוֹר, אֶלָּא הַפָּסוּק הַזֶּה רֶמֶז הוּא שֶׁרוֹמֵז לָאָבוֹת, וְרֶמֶז הוּא שֶׁרוֹמֵז לָאֱמוּנָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה, שֶׁכָּתוּב פֶּלֶא יוֹעֵץ אֵל גִּבּוֹר אֲבִי עַד שַׂר שָׁלוֹם. פֶּלֶא - זוֹ הַחָכְמָה הָעֶלְיוֹנָה שֶׁמֻּפְלָאָה וּמְכֻסֵּית מֵהַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברים יז) כִּי יִפָּלֵא מִמְּךְ דָבָר. יוֹעֵץ - זֶהוּ נָהָר עֶלְיוֹן שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלֹא פוֹסֵק. וְזֶה יוֹעֵץ לַכֹּל וּמַשְׁקֶה אֶת הַכֹּל. אֵל - זֶה אַבְרָהָם, כְּמוֹ שֶׁבֵּאַרְנוּ הָאֵל הַגָּדוֹל. גִּבּוֹר - זֶה יִצְחָק, שֶׁכָּתוּב הַגִּבּוֹר. אֲבִי עַד - זֶה יַעֲקֹב, שֶׁאוֹחֵז בַּצַּד הַזֶּה וּבַצַּד הַזֶּה וְעוֹמֵד בְּקִיּוּם שָׁלֵם. שַׂר שָׁלוֹם - זֶה צַדִּיק, שֶׁהוּא הַשָּׁלוֹם שֶׁל הָעוֹלָם, שְׁלוֹם הַבַּיִת, שְׁלוֹם הַגְּבִירָה.</p>\n<p>בָּאוּ רַבִּי חִזְקִיָּה וְרַבִּי יְהוּדָה וְנָשְׁקוּ אֶת יָדוֹ. בָּכוּ וְאָמְרוּ: אַשְׁרֵי חֶלְקֵנוּ שֶׁשָּׁאַלְנוּ אֶת זֶה. אַשְׁרֵי הַדּוֹר שֶׁאַתָּה שָׁרוּי בְּתוֹכוֹ.</p>"],[9522012004,"<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב זֶה קָרְבַּן אַהֲרֹן וּבָנָיו אֲשֶׁר יַקְרִיבוּ לַה'. בֹּא רְאֵה, הָרְשָׁעִים שֶׁל הָעוֹלָם גּוֹרְמִים לַקָּדוֹשׁ בָּרוּךְ הוּא לְהִסְתַּלֵּק מִכְּנֶסֶת יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (משלי טז) אִישׁ תַּהְפֻּכוֹת יְשַׁלַּח מָדוֹן וְנִרְגָּן מַפְרִיד אַלּוּף. מִי הָאַלּוּף? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא (שהוא אלופו של עולם), כְּמוֹ שֶׁנֶּאֱמַר אַלּוּף נְעוּרַי אָתָּה. וְהֵם (הרשעים) מַפְרִידִים אֶת זֹּאת מִזֶּה, שֶׁהִיא שְׁלוֹם הַבַּיִת, וְהֵם זִוּוּג אֶחָד.</p>\n<p>בָּא אַהֲרֹן הַקָּדוֹשׁ וּבָנָיו, וְעַל יְדֵיהֶם נִקְרָבִים שְׁנֵיהֶם וּמִזְדַּוְּגִים זֶה עִם זֹּאת. זֶהוּ שֶׁכָּתוּב, בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. זֶה קָרְבַּן אַהֲרֹן וּבָנָיו. וְהֵם מְזַוְּגִים אֶת הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן בַּגְּבִירָה, וְעַל יְדֵיהֶם מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְנִמְצָאוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, וְנִמְצָא הַכֹּל אֶחָד בְּלִי פֵרוּד.</p>\n<p>וְאִם תֹּאמַר, לָמָּה לֹא כָתוּב זֹּאת קָרְבָּן, לְקָרֵב זֹּאת לִמְקוֹמָהּ? לֹא כָּךְ, שֶׁהֲרֵי הַכֹּהֵן מִמַּעְלָה שׁוֹרֶה לְהָבִיא אֶת הַזִּוּוּג לִכְנֶסֶת יִשְׂרָאֵל, עַד שֶׁמַּגִּיעַ לְזֶה הַזֶּה לְזַוְּגוֹ עִם זֹּאת וּלְקָרְבָם כְּאֶחָד, וְלָכֵן הַכֹּהֵן מַשְׁלִים אֶת הַקָּרְבָּן וּמְקָרֵב אֶת הַזִּוּוּג. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012005,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מֵאוּשָׁא לִטְבֶרְיָה. אָמַר רַבִּי חִיָּיא, כָּתוּב (תהלים קלב) כִּי בָחַר ה' בְּצִיּוֹן וְגוֹ'. זֹּאת מְנוּחָתִי וְגוֹ'. לִפְעָמִים קוֹרְאִים אֶת זֶה כָּל הַחֲבֵרִים זָכָר, מִשּׁוּם שֶׁהוּא (שציון הוא) רַחֲמִים, וְכָאן הַכָּתוּב קוֹרֵא אוֹתוֹ נְקֵבָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּךְ נִשְׁמָע לִי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה, (אבל) בְּשָׁעָה שֶׁהַזִּוּוּג מִזְדַּוֵּג כְּאֶחָד לְהַרְאוֹת שֶׁהַנְּקֵבָה נִכְלֶלֶת בּוֹ בִּכְלָל אֶחָד, הַנְּקֵבָה נִקְרֵאת בְּשֵׁם (הזכר), שֶׁהֲרֵי אָז נִמְצָאוֹת הַבְּרָכוֹת שֶׁל הַגְּבִירָה וְאֵין בָּהּ פְּרִישׁוּת כְּלָל, וְעַל כֵּן כָּתוּב לְמוֹשָׁב לוֹ. וְכָתוּב כִּי בָחַר ה' בְּצִיּוֹן, בְּצִיּוֹן בְּדִיּוּק, בְּאוֹתוֹ שֶׁיֵּשׁ בְּתוֹכוֹ שֶׁשּׁוֹרֶה בּוֹ, וְלֹא כָתוּב לְצִיּוֹן, וְהַכֹּל אֶחָד. בֵּין שֶׁקּוֹרֵא לָזֶה בְּשֵׁם שֶׁל זָכָר, וּבֵין שֶׁקּוֹרֵא לָזֶה בְּשֵׁם שֶׁל נְקֵבָה, הַכֹּל אֶחָד וְעוֹמְדִים בְּדַרְגָּה אַחַת.</p>\n<p>(פתח רבי יוסי ואמר,) וְעַל זֶה כָּתוּב, (שם פז) וּלְצִיּוֹן יֵאָמֵר אִישׁ וְאִישׁ יוּלַד בָּהּ. אֶחָד לְדִין, וְאֶחָד לְרַחֲמִים. כְּשֶׁמִּזְדַּוְּגִים כְּאֶחָד בְּזִוּוּג אֶחָד, אָז נִקְרָא צִיּוֹן, וְצִיּוֹן וִירוּשָׁלַיִם יְדוּעִים, וְנִמְצָא שֶׁזֶּה תָלוּי בָּזֶה.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, כָּתוּב (ויקרא ב) והתקדשתם והייתם קדשים. מי שמקדש את עצמו מלמטה, מקדשים אותו מלמעלה. ומי שמטמא את עצמו מלמטה, מטמאים אותו מלמעלה. מקדשים אותו מלמעלה - נאה, שהרי קדשת רבונו שורה עליו, אבל מטמאים אותו מאיזה מקום? ואם תאמר מלמעלה, וכי טמאה שורה מלמעלה?</p>"],[9522012006,"<p>אָמַר רַבִּי חִיָּיא, זֶה שֶׁשָּׁנִינוּ, בַּמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה. אִם הַמַּעֲשֶׂה שֶׁלְּמַטָּה בִּקְדֻשָּׁה, מִתְעוֹרֶרֶת קְדֻשָּׁה לְמַעְלָה, וּבָאָה וְשׁוֹרָה עָלָיו וּמִתְקַדֵּשׁ בָּהּ. וְאִם הוּא מִטַּמֵּא לְמַטָּה, מִתְעוֹרֶרֶת רוּחַ טֻמְאָה מִלְמַעְלָה, וּבָאָה וְשׁוֹרָה עָלָיו וְנִטְמָא בָּהּ, שֶׁהֲרֵי הַדָּבָר תָּלוּי בְּמַעֲשֶׂה.</p>\n<p>שֶׁהֲרֵי אֵין לְךְ טוֹב וָרָע, קְדֻשָּׁה וְטֻמְאָה, שֶׁאֵין לָהֶם עִקָּר וְשֹׁרֶשׁ לְמַעְלָה, וּבַמַּעֲשֶׂה שֶׁלְּמַטָּה מִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה. מַה שֶׁתָּלוּי בְּמַעֲשֶׂה, בְּמַעֲשֶׂה מִתְעוֹרֵר לְמַעְלָה וְנַעֲשֶׂה מַעֲשֶׂה. וּמַה שֶּׁתָּלוּי בִּדְבָרִים, בִּדְבָרִים. כְּשֶׁנִּגְזַר בַּדָּבָר, מִתְעוֹרֵר כָּךְ לְמַעְלָה.</p>\n<p>וְאִם תֹּאמַר, מָה הַדָּבָר מְעוֹרֵר? אֶלָּא כָּךְ כָּתוּב, (ישעיהנח) וְדַבֵּר דָּבָר. אוֹתוֹ הַדָּבָר מְעוֹרֵר דָּבָר אַחֵר לְמַעְלָה שֶׁנִּקְרָא דָבָר. (הושע א) דְּבַר ה' אֲשֶׁר הָיָה. (שמואל א ג) וּדְבַר ה' הָיָה יָקָר. (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. שֶׁהֲרֵי שָׁנִינוּ, אוֹתוֹ הַדָּבָר עוֹלֶה וּבוֹקֵעַ רְקִיעִים עַד שֶׁעוֹלֶה (שמתישב) בִּמְקוֹמוֹ וּמְעוֹרֵר אֶת מַה שֶּׁמְּעוֹרֵר, אִם טוֹב - טוֹב, וְאִם רַע - רַע. וְעַל זֶה כָּתוּב, (דברים כג) וְנִשְׁמַרְתָּ מִכֹּל דָּבָר רָע.</p>"],[9522012007,"<p>וְאַרְבָּעָה מִינִים בַּלּוּלָב, וְהֵם שִׁבְעָה. וְאִם תֹּאמַר שֶׁשִּׁבְעָה מִינִים הֵם - לֹא כָּךְ, אֶלָּא אַרְבָּעָה הֵם, וְהֵם נִפְרָדִים לִשְׁלֹשָׁה אֲחֵרִים, וּבַמַּעֲשֶׂה שֶׁלָּהֶם מִתְעוֹרְרִים שִׁבְעָה אֲחֵרִים לְמַעְלָה לְהֵיטִיב אֶת הָעוֹלָם בְּכַמָּה צְדָדִים.</p>\n<p>כְּנֶסֶת יִשְׂרָאֵל, אַף עַל גַּב שֶׁהִיא בִּכְלָל, מִתְבָּרֶכֶת מִכָּל הַשִּׁשָּׁה, (ולהתברך מאותם ששה) וּמֵהַנַּחַל הֶעָמֹק שֶׁל הַמַּעְיָן שֶׁשּׁוֹפֵעַ וְאֵינוֹ פוֹסֵק אֶת מֵימָיו לְעוֹלָמִים שֶׁמַּשְׁפִּיעַ (מלהשפיע) עֲלֵיהֶם, וּמֵינִיק לַבַּת. שֶׁמִשּׁוּם שֶׁהִיא בַּת לָעוֹלָם הָעֶלְיוֹן וְלַתַּחְתּוֹן, הִיא מִתְבָּרֶכֶת מֵהֶם בַּהִתְעוֹרְרוּת הַזּוֹ. שֶׁהֲרֵי בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת מֵהֶם, כָּל הָעוֹלָמוֹת מִתְבָּרְכִים, וְעַל כֵּן סוֹבְבִים אֶת הַמִּזְבֵּחַ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְעוד, בַּהִתְעורְרוּת הַזֹּאת מִתְבָּרְכִים כָּל הַשִּׁשָּׁה בְּמַיִם לֵהָנות בּוֹ, וְכֻלָּם שׁוֹאֲבִים מֵהַמַּעְיָן שֶׁל הַיַּיִן (של הים) (של המים) (של הנחל) הֶעָמֹק שֶׁל הַכֹּל לָרֶדֶת לָעוֹלָם. וּמִשּׁוּם כָּךְ צְרִיכִים כֻּלָּם לַחִים וְלֹא יְבֵשִׁים, לִמְשֹׁךְ בְּרָכוֹת לָעוֹלָם, מִשּׁוּם שֶׁהָאִילָנוֹת הַלָּלוּ כֻּלָּם לַחִים תָּמִיד, וְהֶעָלִים שֶׁלָּהֶם נִמְצָאִים תָּמִיד, וּזְמַן הַשִּׂמְחָה שֶׁלָּהֶם בַּזְּמַן הַזֶּה.</p>\n<p>וְשָׁנִינוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, שֶׁהֲרֵי אוֹתוֹ כֹּחַ שֶׁהֻפְקַד עַל הָאִילָנוֹת הַלָּלוּ, כָּל אֶחָד וְאֶחָד מֵאֵלּוּ לֹא נוֹטֵל בְּרָכוֹת שֶׁל שִׂמְחָה לְמַעְלָה, אֶלָּא בַּזְּמַן הַזֶּה. וְהַשִּׂמְחָה שֶׁלָּהֶם כֻּלָּם לְמַעְלָה, וְשִׂמְחַת הָאִילָנוֹת הַלָּלוּ לְמַטָּה, כֻּלָּם בַּזְּמַן הַזֶּה הוּא. וְהַהִתְעוֹרְרוּת שֶׁלָּהֶם בְּאוֹתָם קְדוֹשֵׁי הַמֶּלֶךְ תְּלוּיִים. וּכְשֶׁיִּשְׂרָאֵל נוֹטְלִים אוֹתָם, הַכֹּל מִתְעוֹרֵר בַּזְּמַן הַזֶּה, וְהָעוֹלָם מִתְבָּרֵךְ (לכנסת ישראל מתברכת) לְהוֹרִיק בְּרָכוֹת לָעוֹלָם.</p>\n<p>כָּתוּב, (תהלים כט) קוֹל ה' עַל הַמָּיִם אֵל הַכָּבוֹד. אָמַר רַבִּי יוֹסֵי, זֶה אַבְרָהָם. קוֹל ה' בַּכֹּחַ - זֶה יִצְחָק. קוֹל ה' בֶּהָדָר - זֶה יַעֲקֹב. קוֹל ה' שֹׁבֵר אֲרָזִים - זֶה נֵצַח. קוֹל ה' חֹצֵב לַהֲבוֹת אֵשׁ - זֶה הוֹד. קוֹל ה' יָחִיל מִדְבָּר - זֶה צַדִּיק. קוֹל ה' יְחוֹלֵל אַיָּלוֹת - זֶה צֶדֶק. וְכֻלָּם גְּדֵלִים עַל הַיָּם (המים) וְנִשְׁקִים בַּמַּיִם כְּדֵי לִגְדֹּל. זֶהוּ שֶׁכָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְכָל אֵלֶּה מְעוֹרְרִים בְּרָכוֹת לָעוֹלָם מֵאוֹתָהּ הַהַשְׁקָאָה שֶׁכֻּלָּם מֻשְׁקִים.</p>\n<p>בֹּא רְאֵה, שִׁבְעַת הַקּוֹלוֹת הַלָּלוּ תְּלוּיִים בְּדִבּוּר הַפֶּה בִּשְׁאָר יְמוֹת הַשָּׁנָה, וְעַכְשָׁו אֵין תְּלוּיִים אֶלָּא בְּמַעֲשֶׂה, וְאָנוּ צְרִיכִים מַעֲשֶׂה, וְלֹא דִבּוּר, מִשּׁוּם שֶׁבַּזְּמַן הַזֶּה מְבָרֵךְ אֶת כָּל הַשָּׁנָה.</p>\n<p>בַּיּוֹם הַשְּׁבִיעִי שֶׁל הֶחָג, הוּא סִיּוּם הַדִּין שֶׁל הָעוֹלָם, וְהַפְּתָקִים יוֹצְאִים מִבֵּית הַמֶּלֶךְ, וְהַגְּבוּרוֹת מִתְעוֹרְרוֹת וּמִסְתַּיְּמוֹת בַּיּוֹם הַזֶּה, וְעַרְבֵי נַחַל (תלויים) בָּהֶם. וּצְרִיכִים לְעוֹרֵר גְּבוּרוֹת לַמַּיִם, וּלְהַקִּיף שֶׁבַע פְּעָמִים כְּדֵי לְרַוּוֹת אֶת הַמִּזְבֵּחַ הַזֶּה מֵהַמַּיִם שֶׁל יִצְחָק, מִשּׁוּם שֶׁהַבְּאֵר הַזּוֹ שֶׁל יִצְחָק מִתְמַלֵּאת מַיִם, וּכְשֶׁמִּתְמַלֵּאת, כָּל הָעוֹלָם מִתְבָּרֵךְ בְּמַיִם.</p>\n<p>וּבַיּוֹם הַזֶּה צְרִיכִים גְּבוּרוֹת לַמַּיִם, וּלְסַיֵּם אוֹתָהּ אַחַר כָּךְ, שֶׁהֲרֵי בַּיּוֹם הַזֶּה מִסְתַּיֵּם הַדִּין, וּמִשּׁוּם כָּךְ צְרִיכִים לַחְבֹּט אוֹתָם בַּקַּרְקַע שֶׁלֹּא יִמָּצְאוּ, שֶׁהֲרֵי זֶהוּ יוֹם שֶׁל הִתְעוֹרְרוּת וְסִיּוּם. וְלָכֵן הִתְעוֹרְרוּת וְסִיּוּם הוּא שֶׁעוֹשִׂים בְּעַרְבֵי נַחַל.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, וְיָפֶה. וְעַרְבֵי נָחַל, מֵהַצַּד שֶׁל נַחַל יוֹצְאוֹת גְּבוּרוֹת. וּבַיּוֹם הַזֶּה מִתְעוֹרְרִים וּמְסַיְּמִים. בַּיּוֹם הַזֶּה כָּתוּב, (בראשית כו) וַיָּשָׁב יִצְחָק וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם. בְּאֵרֹת כָּתוּב חָסֵר. וַיָּשָׁב, מַה זֶּה וַיָּשָׁב? אֶלָּא הַיּוֹם הָרִאשׁוֹן שֶׁל הַחֹדֶשׁ, רֵאשִׁית הַדִּין הָיָה בְּכָל הָעוֹלָם, וְיִצְחָק עוֹמֵד לַכִּסֵּא לָדוּן אֶת הָעוֹלָם. בַּיּוֹם הַזֶּה, וַיָּשָׁב יִצְחָק, לְעוֹרֵר דִּינִים וּלְסַיֵּם דִּינִים. וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם, לְהָרִיק גְּבוּרוֹת לִכְנֶסֶת יִשְׂרָאֵל לְעוֹרֵר אֶת הַמַּיִם, שֶׁהֲרֵי מַיִם יוֹרְדִים לָעוֹלָם בִּגְבוּרוֹת.</p>\n<p>וּמִשּׁוּם שֶׁהַגְּבוּרוֹת הַלָּלוּ אֵין יוֹרְדוֹת אֶלָּא בַּעֲנָנִים, וְיוֹם הַמְעֻנָּן לֹא נָחָה רוּחָם שֶׁל עַמּוּדֵי הָעוֹלָם, רַק מִשּׁוּם שֶׁהָעוֹלָם צָרִיךְ אוֹתָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהָעוֹלָם נִבְרָא בְּדִין, וְהַכֹּל כָּךְ צָרִיךְ. מִשּׁוּם כָּךְ הַכֹּל תָּלוּי בְּמַעֲשֶׂה. וְעַל כֵּן הַכֹּהֵן בַּמַּעֲשֶׂה וּבַתִּקּוּן שֶׁהוּא עוֹשֶׂה לְמַטָּה, מִתְעוֹרְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים לְתַקֵּן אוֹתָם, וְהֵם מִתְתַּקְּנִים עַל יָדוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הֲרֵי שָׁנִינוּ, הָעֲרָבָה שֶׁדּוֹמֶה לַשְּׂפָתַיִם בַּיּוֹם הַזֶּה, וּמַה הִיא? אָמַר רַבִּי חִיָּיא, אַף עַל גַּב שֶׁלִּדְרָשׁ הוּא בָּא, כָּךְ זֶה וַדַּאי. שֶׁהֲרֵי בַּיּוֹם הַזֶּה זֶה תָלוּי בַּשְּׂפָתַיִם, בַּיּוֹם הַזֶּה מְצַוֶּה הַמֶּלֶךְ לָתֵת פְּתָקִים לַמְמֻנֶּה, וְהַדִּינִים מִסְתַּיְּמִים, וְנִסְתָּם לָשׁוֹן הָרָע מֵהָעוֹלָם. בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחֹדֶשׁ הוּא רֵאשִׁית הַדִּין, וְהַסִּיּוּם הוּא בַּיּוֹם הַזֶּה, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בַּיּוֹם הַזֶּה הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה מַשְׁלִימִים וּמְסַיְּמִים אֶת הַבְּרָכוֹת שֶׁלָּהֶם וְשׁוֹרִים בְּדִין, וְיִשְׂרָאֵל בַּיּוֹם הַזֶּה מְסַיְּמִים אֶת הַדִּינִים שֶׁלָּהֶם וְשׁוֹרִים בִּבְרָכוֹת, שֶׁהֲרֵי לְיוֹם אַחֵר עֲתִידִים לְהִשְׁתַּעֲשֵׁעַ עִם הַמֶּלֶךְ, לִטֹּל מִמֶּנּוּ בְּרָכוֹת לְכָל הַשָּׁנָה, וּבְאוֹתָהּ שִׂמְחָה לֹא נִמְצָאִים עִם הַמֶּלֶךְ, רַק יִשְׂרָאֵל לְבַדָּם. וּמִי שֶׁיּוֹשֵׁב עִם הַמֶּלֶךְ וְנוֹטֵל אוֹתוֹ לְבַדּוֹ, כָּל מַה שֶּׁרוֹצֶה שׁוֹאֵל, וְנוֹתֵן לוֹ. וְעַל כֵּן יִשְׂרָאֵל מַתְחִילִים, וְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה מְסַיְּמִים. וְעַל כֵּן כָּתוּב, (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה' וְגוֹ'.</p>\n<p>אָמַר לוֹ, הֲרֵי אֲנִי רוֹאֶה אֶת עֵשָׂו בְּשַׁלְוָה, בְּמַלְכוּת, בִּכְרַכִּים עֶלְיוֹנִים, וְשׁוֹלֵט עַל הָעוֹלָם, וְאַתָּה אָמַרְתָּ וָאָשִׂים אֶת הָרָיו שְׁמָמָה?! אָמַר לוֹ, בְּכָל מָקוֹם זֶה כָּךְ, כֵּיוָן שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ גָּזַר גְּזֵרָה וְשָׂם אוֹתָהּ גְּזֵרָה בַּפֶּתֶק שֶׁלּוֹ, הַכָּתוּב מֵעִיד כְּמוֹ שֶׁנַּעֲשָׂה. וְעַל כֵּן וָאָשִׂים אֶת הָרָיו שְׁמָמָה, שֶׁהֲרֵי שַׂמְתִּי אֶת זֶה בַּפֶּתֶק שֶׁלִּי, וְכֵן כָּל אוֹתָן טוֹבוֹת שֶׁגָּזַר עַל יִשְׂרָאֵל, שֶׁכָּתוּב (יחזקאל יז) אֲנִי ה' דִּבַּרְתִּי וְעָשִׂיתִי.</p>\n<p>וְזֹאת תּוֹרַת הָאָשָׁם וְזֹּאת תּוֹרַת הַמִּנְחָה וְזֹּאת תּוֹרַת זֶבַח הַשְּׁלָמִים זֹּאת תּוֹרַת הַחַטָּאת. רַבִּי יִצְחָק אָמַר, הֲרֵי פֵּרְשׁוּהָ, אִם לְמַטָּה - זוֹ בַּכֹּל, וְאִם לְמַעְלָה - זוֹ בַּכֹּל. וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, נוֹטֵל אוֹתָהּ לְחֶלְקוֹ בַּכֹּל וְנֶאֱחָז בְּכָל הַצְּדָדִים, וְלֹא צָרִיךְ לְהַקְרִיב קָרְבָּן עַל נַפִשׁוֹ, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012008,"<p>רַבִּי יִצְחָק פָּתַח, (ירמיה ב) הַכֹּהֲנִים לֹא אָמְרוּ אַיֵּה ה' וְתֹפְשֵׂי הַתּוֹרָה לֹא יְדָעוּנִי וְהָרֹעִים פָּשְׁעוּ בִי. הַכֹּהֲנִים - אֵלּוּ הַכֹּהֲנִים שֶׁמְּשַׁמְּשִׁים בִּכְהֻנָּה גְּדוֹלָה, וּמַקְרִיבִים דְּבָרִים קְדוֹשִׁים לִמְקוֹמָם, וּמְיַחֲדִים הַיִּחוּד כָּל אֶחָד וְאֶחָד כָּרָאוּי. וְתֹפְשֵׂי הַתּוֹרָה, מִי הֵם תֹּפְשֵׂי הַתּוֹרָה? וְכִי כֹהֲנִים אֵינָם תּוֹפְשֵׂי הַתּוֹרָה? אֶלָּא אֵלּוּ הֵם הַלְוִיִּם שֶׁתּוֹפְשִׂים אֶת הַכִּנּוֹרוֹת, שֶׁבָּאִים מִצַּד שֶׁל הַתּוֹרָה, וְהַתּוֹרָה נִתְּנָה מֵהַצַּד שֶׁלָּהֶם, וְהֵם מְמֻנִּים עַל הַשֶּׁבַח שֶׁל תִּשְׁבַּחְתּוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ לְיַחֵד אוֹתוֹ יִחוּד שָׁלֵם כָּרָאוּי. וְהָרֹעִים פָּשְׁעוּ בִי - אֵלֶּה הֵם גְּדוֹלֵי הָעַמִּים, שֶׁהֲרֵי רוֹעִים אֶת הָעָם כְּמוֹ רוֹעֶה שֶׁמַּנְהִיג אֶת צֹאנוֹ.</p>\n<p>וְאֵלֶּה הֵם שָׁלֹשׁ דְּרָגוֹת שֶׁצְּרִיכוֹת תָּמִיד לְהִמָּצֵא עַל הַקָּרְבָּן לִמְצֹא רָצוֹן לְמַעְלָה וּלְמַטָּה וְשֶׁיִּמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת. הַכֹּהֵן מַקְרִיב קָרְבָּן, וּמִתְכַּוֵּן לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי וּלְעוֹרֵר אֶת הַצַּד שֶׁלּוֹ, וְהַלְוִיִּם מִתְכַּוְּנִים בַּשִּׁיר לְעוֹרֵר אֶת הַצַּד שֶׁלָּהֶם וּלְהִכָּלֵל בְּצִדּוֹ שֶׁל הַכֹּהֵן, וְיִשְׂרָאֵל מְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לִתְשׁוּבָה שְׁלֵמָה וְנִכְנָע לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְזֶה נוֹטֵל הַכֹּל וּמִתְכַּפֵּר חֶטְאוֹ, וְנִמְצֵאת שִׂמְחָה בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים.</p>"],[9522012009,"<p>רַבִּי יְהוּדָה פָּתַח, (תהלים קד) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'. כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הוֹצִיא אוֹתוֹ מִתּוֹךְ מַיִם, וְסִדֵּר אוֹתוֹ עַל הַמַּיִם. מֶה עָשָׂה? חִלֵּק אֶת הַמַּיִם לִשְׁנַיִם, מַחֲצִית לְמַטָּה וּמַחֲצִית לְמַעְלָה, וְעָשָׂה מֵהֶם מַעֲשִׂים. מֵהַמַּחֲצִית הַתַּחְתּוֹנָה עָשָׂה וְתִקֵּן אֶת הָעוֹלָם הַזֶּה וְסִדֵּר אוֹתוֹ עַל הַמַּחֲצִית הַזֹּאת, וְתִקֵּן אוֹתוֹ לְמַעְלָה עֲלֵיהֶם, זֶהוּ שֶׁכָּתוּב (שם כד) כִּי הוּא עַל יַמִּים יְסָדָהּ. וְאֶת הַמַּחֲצִית הָאַחֶרֶת הֶעֱלָה לְמַעְלָה וְסִדֵּר בּוֹ אֶת הַתִּקְרוֹת הָעֶלְיוֹנוֹת, זֶהוּ שֶׁכָּתוּב הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'.</p>\n<p>וְעָשָׂה רָקִיעַ בֵּין שְׁנֵי הַחֲצָאִים הַלָּלוּ, זֶהוּ שֶׁכָּתוּב (בראשית א) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. וַעֲלֵיהֶם תִּקֵּן וְסִדֵּר עֶלְיוֹנִים קְדוֹשִׁים מִתּוֹךְ טִפּוֹת טִפּוֹת בְּרוּחַ שֶׁנִּגְזְרָה בְּתֹאַר (במאור) (וסדר מלאכים עליונים קדושים מתוך רוח שנגזרה מפיו), שֶׁכָּתוּב וּבְרוּחַ פִּיו כָּל צְבָאָם.</p>\n<p>וּבְאֵלּוּ תִּקֵּן וְסִדֵּר הַמְזַמְּרִים אֶת תִּשְׁבַּחְתּוֹ בַּיּוֹם, וְהִתְעָרְבוּ בְשַׁלְהֲבוֹת אֵשׁ. וְאוֹתָם גְּדוּדֵי הַצְּבָאוֹת אוֹמְרִים שִׁירָה בַּיּוֹם, תִּשְׁבָּחוֹת בַּבֹּקֶר וּזְמִירוֹת בָּעֶרֶב. כְּשֶׁמַּגִּיעַ הַלַּיְלָה, כֻּלָּם מַפְסִיקִים אֶת הַשִּׁירָה. מֵעֲלֵיהֶם גְּדוּדֵי אֵשׁ בְּשַׁלְהֶבֶת חֲזָקָה עוֹמְדִים וּמְרִיחִים אֵשׁ אוֹכֶלֶת, וְחוֹזְרִים לִמְקוֹמָם.</p>\n<p>וְיִשִׁ בַּצַּד הָאַחֵר שֶׁתְּהוֹמוֹת עוֹלִים אֵלּוּ עַל אֵלּוּ, וְיֵשׁ תְּהוֹם עֶלְיוֹן וּתְהוֹם תַּחְתּוֹן, וּבְכֻלָּם שׁוֹרִים בַּעֲלֵי הַדִּינִים מִצַּד שֶׁל הַדִּין הַקָּשֶׁה. וְיֵשׁ בְּתוֹךְ צַד הַתְּהוֹם הַתַּחְתּוֹן שַׁלְהָבוֹת שֶׁשּׂוֹרְפוֹת זִיקִים שֶׁל אֵשׁ הַמְמֻנִּים עַל דִּינֵי הָעוֹלָם, לִשְׂרֹף אֶת הָרְשָׁעִים בְּאֵשׁ שֶׁיּוֹצֵאת מֵאוֹתוֹ נְהַר דִּינוּר. וְכֻלָּם אֵשׁ, וּמַרְאֵיהֶם אֵשׁ לוֹהֶטֶת, וְעוֹמְדִים בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וּכְשֶׁעוֹלֶה עֲשַׁן הַמִּזְבֵּחַ, עוֹבְרִים וְעוֹלִים מֵאוֹתָהּ דַּרְגָּה, שֶׁעוֹמְדִים לְכַלּוֹת וּלְהַאֲבִיד, וְאוֹתוֹ זֶרֶם שֶׁל שֶׁל אֵשׁ חֲזָרָה שֶׁל נְהַר דִּינוּר, שֶׁהוּא תַקִּיף וְעֶלְיוֹן, חוֹזֵר לִמְקוֹמוֹ, וְכֻלָּם נֶהֱנִים מֵעֲשַׁן הַמִּזְבֵּחַ, מִשּׁוּם שֶׁנִּתְתַּקֵּן כְּנֶגֶד (המזבח) הַמֶּלֶךְ הָעֶלְיון, וּמִשּׁוּם כָּךְ הֵם נֶהֱנִים מִמֶּנּוּ, וְהֵם קְרֵבִים לְכָאן. וְעָשָׁן אַחֵר עוֹלֶה, וַהֲרֵי בֵּאַרְנוּ, לְכָל אֶחָד וְאֶחָד, הָרָצוֹן שֶׁל הַכֹּל שֶׁעוֹלֶה לְמַעְלָה, שֶׁהוּא נַחַת רוּחַ לַמֶּלֶךְ הַקָּדוֹשׁ.</p>"],[9522012010,"<p>הֲרֵי נִתְבָּאֵר שֶׁבַּמִּזְבֵּחַ עוֹלֶה וְנִרְאֶה אוּרִיאֵ\"ל, כְּמוֹ מַרְאֶה שֶׁל אַרְיֵה חָזָק רוֹבֵץ עַל טַרְפּוֹ, וְהָיוּ הַכֹּהֲנִים וְיִשְׂרְאֵלִים רוֹאִים וּשְׂמֵחִים, שֶׁהָיוּ יוֹדְעִים שֶׁהִתְקַבֵּל בְּרָצוֹן לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְאֵשׁ אַחֶרֶת עֶלְיוֹנָה קְדוֹשָׁה יוֹרֶדֶת כְּנֶגֶד הָאֵשׁ הַתַּחְתּוֹנָה, וְאָז אָדָם הוֹלֵךְ (ירא) וּמִזְדַּעֲזֵעַ לִפְנֵי אֲדוֹנוֹ וִשָׁב בִּתְשׁוּבָה שְׁלֵמָה.</p>\n<p>לְמֶלֶךָֹ שֶׁשָּׁלְחוּ לוֹ דּוֹרוֹן, וְהָיָה מְקֻבָּל לְפָנָיו. אָמַר לְעַבְדּוֹ, לֵךְ וְטֹל אֶת הַדּוֹרוֹן הַזֶּה שֶׁהֵבִיאוּ לִי. כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוּרִיאֵל, לֵךְ וְקַבֵּל אֶת הַדּוֹרוֹן שֶׁבָּנַי מַקְרִיבִים לְפָנַי. כַּמָּה שִׂמְחָה נִמְצֵאת בַּכֹּל, כַּמָּה הִתְבַּשְּׂמוּת נִמְצֵאת בַּכֹּל, כְּשֶׁהַכֹּהֵן וְהַלֵּוִי וְאוֹתוֹ שֶׁמַּקְרִיב קָרְבָּן מְכַוְּנִים לְהַקְרִיב קָרְבָּן כָּרָאוּי בְּיִחוּד שָׁלֵם.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעֹלָה וְגוֹ'. זֶה אוּרִיאֵ\"ל, שֶׁיּוֹרֵד בְּמַרְאֶה שֶׁל אֵשׁ בְּשַׁלְהֶבֶת, עַד שֶׁיּוֹרֵד לַמִּזְבֵּחַ לְקַבֵּל אֶת הַדּוֹרוֹן, וְנִרְאֶה כְּמוֹ אַרְיֵה גָּדוֹל רוֹבֵץ עַל הַקָּרְבָּן.</p>\n<p>וּכְשֶׁיִּשְׂרָאֵל לֹא נִמְצְאוּ צַדִּיקִים, אוֹ שֶׁאוֹתוֹ מַקְרִיב הַקָּרְבָּן לֹא הִקְרִיב כָּרָאוּי וְלֹא הִתְקַבֵּל קָרְבָּנוֹ, הָיוּ רוֹאִים שֶׁהֶעָשָׁן לֹא עוֹלֶה בְדֶרֶךְ יְשָׁרָה, וְהָיְתָה עוֹמֶדֶת רוּחַ אַחַת מִנֶּקֶב הַצָּפוֹן וְנִכְנֶסֶת לַמִּזְבֵּחַ, וְהָיוּ רוֹאִים דְּיוֹקָן שֶׁל כֶּלֶב אֶחָד חָצוּף רוֹבֵץ עַל הַקָּרְבָּן, וְאָז הָיוּ יוֹדְעִים שֶׁלֹּא הִתְקַבֵּל בְּרָצוֹן אוֹתוֹ הַקָּרְבָּן.</p>\n<p>לְמֶלֶךְ שֶׁשָּׁלְחוּ לוֹ דּוֹרוֹן, רָאָה אוֹתוֹ הַמֶּלֶךְ שֶׁאֵינוֹ כְדַאי לְקָרְבוֹ לְפָנָיו. אָמַר הַמֶּלֶךְ, סַלְּקוּ אֶת אוֹתוֹ הַדּוֹרוֹן וּתְנוּ אוֹתוֹ לַכֶּלֶב, שֶׁאֵינוֹ כְדַאי לְהִכָּנֵס לְפָנַי. כָּךְ בְּשָׁעָה שֶׁנִּקְרַב הַקָּרְבָּן וְלֹא הִתְקַבֵּל בְּרָצוֹן, הַדּוֹרוֹן נִמְסַר לַכֶּלֶב, וּמִשּׁוּם כָּךְ הָיוּ רוֹאִים אֶת דְּיוֹקַן הַכֶּלֶב עַל גַּבֵּי הַמִּזְבֵּחַ.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל עַל הַמִּזְבֵּחַ אֶת הָעֹלָה. אָמַר רַבִּי יְהוּדָּה, זֶה אוּרִיאֵ\"ל, שֶׁנִּרְאָה בְּשַׁלְהֶבֶת אֵשׁ עַל הַמִּזְבֵּחַ, כְּמוֹ שֶׁנֶּאֱמַר רוֹבֵץ עַל הַקָּרְבָּן. וְאָז הָיְתָה שִׂמְחָה בַּכֹּל, שֶׁהֲרֵי הִתְקַבֵּל בְּרָצוֹן, כְּמוֹ שֶׁכָּתוּב וַיֵּרָא כְבוֹד ה' אֶל כָּל הָעָם. וְאִם לֹא הָיְתָה הָעִרְבּוּבְיָא שֶׁל בְּנֵי אַהֲרֹן מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא נִמְצָא רָצוֹן כָּךְ לְמַעְלָה וּלְמַטָּה.</p>"],[9522012011,"<p>מִצְוָה זוֹ לִשְׂרֹף קָדָשִׁים בָּאֵשׁ, וְאַחֲרֶיהָ - וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף. תַּנָּאִים וְאָמוֹרָאִים, בְּסִתְרֵי תוֹרָה יֵשׁ קֹדֶשׁ, וְיֵשׁ קָדָשִׁים, וְיֵשׁ קֹדֶשׁ קָדָשִׁים. מַה הֲנָאָה יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא בַּקְּדָשִׁים שֶׁנִּשְׂרְפוּ? אִם תֹּאמַר בִּשְׁבִיל יִצְחָק, שֶׁבְּשָׁעָה שֶׁיִּשְׂרָאֵל בְּצָרָה, עוֹלֶה אֶפְרוֹ שֶׁל יִצְחָק לְפָנָיו, שֶׁאִם חַיָּבִים שְׂרֵפָה יִנָּצְלוּ בִגְלָלוֹ - זֶהוּ לִדְרָשׁ. וְאִם תֹּאמְרוּ מִשּׁוּם (הצדיקים) (ואם משום) בְּנֵי אַהֲרֹן שֶׁהָיוּ שְׂרֵפַת קָדָשִׁים, שֶׁכָּתוּב בָּהֶם וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם וַיָּמֻתוּ, וּמִיתָתָם כַּפָּרָה לְיִשְׂרָאֵל כְּמוֹ שְׂרֵפַת קָדָשִׁים - אַף זֶה לִדְרָשׁ בָּא.</p>\n<p>אֶלָּא שְׁלֹשָׁה אִשִּׁים בְּנֵר: אֵשׁ לְבָנָה, וְאֵשׁ שְׁחֹרָה, וְאֵשׁ תְּכֻלָּה, כְּנֶגֶד תּוֹרָה נְבִיאִים וּכְתוּבִים, כְּנֶגֶד כֹּהֵן לֵוִי וְיִשְׂרָאֵל. וּתְכֵלֶת הִיא שְׁכִינָה, קְרוֹבָה לָנוּ, וְהִיא אֲחוּזָה בְּאוֹתָן פְּתִילוֹת, בְּכַנְפֵי מִצְוָה, שֶׁנֶּאֱמַר בָּהֶם וְעָשׂוּ לָהֶם צִיצִית. וְהַתְּכֵלֶת הַזּוֹ שֶׁהִיא שְׁכִינָה, הִיא דִין שֶׁאוֹכֶלֶת קָרְבָּנוֹת וְעוֹלוֹת.</p>\n<p>אִם מוֹצֵאת בְּנֵי אָדָם שֶׁהֵם עֵצִים יְבֵשִׁים כְּמוֹ אוֹתָן פְּתִילוֹת יְבֵשׁוֹת, בְּלִי שֶׁמֶן, שֶׁהִיא תּוֹרָה וְרַחֲמִים, הִיא לָהֶם (שידונו) שְׂרֵפָה, וְשׂוֹרֶפֶת אוֹתָם. וּמִשּׁוּם שֶׁעַמֵּי הָאָרֶץ הֵם בְּהֵמוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁהֵם שֶׁקֶץ. תְּכֵלֶת, שֶׁהִיא אֲדנָי, שׂוֹרֶפֶת אוֹתָם, מִשּׁוּם שֶׁקְּרֵבִים אֵלֶיהָ עִם שֶׁרֶץ, שֶׁהוּא יֵצֶר הָרָע זָר. זֶהוּ שֶׁכָּתוּב וְהַזָּר הַקָּרֵב יוּמָת.</p>\n<p>וְאִם בְּמִיתָתָם חוֹזְרִים בִּתְשׁוּבָה, (כששוחט אותם מלאך המות, מיכאל) הַמַּלְאָךְ מִיכָאֵל שֶׁהוּא כֹּהֵן גָּדוֹל, הָאַרְיֵה שֶׁאוֹכֵל קָרְבָּנוֹת יוֹרֵד עֲלֵיהֶם לְהַקְרִיבָם קָרְבָּן לִפְנֵי ה'.</p>\n<p>וְלִפְנֵי שֶׁתֵּצֵא נִשְׁמָתוֹ מִתְוַדֶּה בְּכַמָּה וִדּוּיִים, וּכְשֶׁיּוֹצֵאת נִשְׁמָתוֹ הוּא הָיָה מִתְכַּוֵּן לִגְמֹר אֶת הַשֵּׁם, שְׁמַע יִשְׂרָאֵל וּבָרוּךְ שֵׁם, לְהַקְרִיב אֶת נִשְׁמָתוֹ כְּלִי (קרבן) לְשֵׁם יְהֹוָ\"ה, וְצָרִיךְ לְהִתְוַדּוֹת אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַבֵּל וּלְקָרֵב ה' שֶׁבִּשְׁמוֹ שֶׁאוֹכֶלֶת וּמְכַלָּה, וּלְהַחֲזִיר בִּתְשׁוּבָה לְיה\"ו אֶהְיֶ\"ה כְּחֶשְׁבּוֹן מ\"ב. שֶׁל אֲדנָ\"י קוֹרְאִים דִּין שֶׁל מַלְכוּת דִּין.</p>\n<p>וִיכַוֵּן בַּשֵּׁם הַמְפֹרָשׁ, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, בְּלֵב אֶחָד, וּבוֹ תֵּצֵא רוּחוֹ. בַּנֶּפֶשׁ שֶׁלּוֹ מְקַבֵּל עָלָיו מִיתָה וְיִסּוּרִים, וּבַנְּשָׁמָה מוֹדֶה בְּכַמָּה וִדּוּיִים וּמִתְחָרֵט.</p>\n<p>בַּנֶּפֶשׁ מְקַבֵּל עָלָיו מִיתָה, שְׁחִיטָה, שְׂרֵפָה. וְאִם צָרִיךְ אַרְבַּע מִיתוֹת בֵּית דִּין, שֶׁהֵם סְקִילָה שְׂרֵפָה הֶרֶג וְחֶנֶק, מְקַבֵּל אוֹתָם מֵאֲדנָ\"י בַּנֶּפֶשׁ שֶׁלּוֹ. וּבְנִשְׁמָתוֹ מוֹדֶה בְּכַמָּה וִדּוּיִים, וְחוֹזֵר בִּתְשׁוּבָה אֶל אֶהְיֶ\"ה, שֶׁאָחוּז בִּשְׁנֵי שֵׁמוֹת - יְהֹוָ\"ה יְהֹוָ\"ה.</p>\n<p>בְּמַחֲשַׁבְתּוֹ יְכַוֵּן לְהוֹצִיא וִדּוּי וְקַבָּלַת מִיתָה עָלָיו בְּלֵב אֶחָד, שֶׁהוּא שֵׁם הַמְפֹרָשׁ, כְּמוֹ זֶה: יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, (כבוד) שֶׁבּו הַכֹּהֲנִים כּורְעִים וּמִשְׁתַּחֲוִים עַל פְּנֵיהֶם וְאוֹמְרִים: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּבוֹד הוּא ל\"ב בְּחֶשְׁבּוֹן, וּבוֹ הָיָה מִתְכַּוֵּן לִגְמֹר אֶת הַשֵּׁם. (וא\"ו הוא אחד בלב).</p>\n<p>וְתַנָּאִים וְאָמוֹרָאִים, אִם תֹּאמְרוּ, וְכִי עַם הָאָרֶץ מִנַּיִן יוֹדֵעַ אֶת זֶה? אֶלָּא וַדַּאי עַם הָאָרֶץ הוּא כְּמוֹ שׁוֹר אוֹ שֶׂה אוֹ עֵז אוֹ (פר) תוֹר אוֹ יוֹנָה. מַה בְּהֵמוֹת אֵין יוֹדְעוֹת תּוֹרָה, שֶׁהִיא שֵׁם יְהֹוָ\"ה, כָּךְ עַם הָאָרֶץ לֹא יוֹדֵעַ. אֶלָּא מִיכָאֵל כֹּהֵן גָּדוֹל הוּא עוֹשֶׂה אוֹתוֹ עוֹלָה וְקָרְבָּן לִפְנֵי ה', וְהוּא מְכַוֵּן בַּשֵּׁם הַמְפֹרָשׁ בַּעֲלִיַּת רוּחוֹ שֶׁתֵּצֵא בְּלֵב אֶחָד, כְּמוֹ שֶׁכְּשֶׁיּוֹצֵאת רוּחַ הָאָדָם בְּכָל לַיְלָה.</p>\n<p>וּמִשּׁוּם זֶה פֵּרְשׁוּהָ הַחֲכָמִים, שׁוּב יוֹם אֶחָד לִפְנֵי מִיתָתְךְ. שֶׁבְּכָל יוֹם וָיוֹם צָרִיךְ אָדָם לַחֲזֹר בִּתְשׁוּבָה וְלִמְסֹר אֶת רוּחוֹ אֵלָיו שֶׁיֵּצֵא בְאֶחָד. זֶהוּ שֶׁכָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי.</p>\n<p>וְאִם הוּא תַּלְמִיד חָכָם, עָלָיו נֶאֱמַר (משלי יב) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ, שֶׁאֵין חָכָם כְּמוֹ הַכֹּהֵן, כְּמוֹ שֶׁבֵּאֲרוּהָ הָרוֹצֶה לְהַחְכִּים יַדְרִים. וְאִם תַּלְמִיד חָכָם הוּא, צָרִיךְ שֶׁיִּהְיֶה בּוֹ חֶסֶד, וְעִם י' שֶׁהִיא חָכְמָה - חָסִיד. וּמִי שֶׁאֵין בּוֹ חָכְמָה, אֵינוֹ חָסִיד. וּמִשּׁוּם כָּךְ פֵּרְשׁוּהָ, וְלֹא עַם הָאָרֶץ חָסִיד. וְאִם יֵשׁ בּוֹ ה', חֲמִשָּׁה חֻמְשֵׁי תוֹרָה שֶׁנִּתְּנוּ מִשְּׂמֹאל, נִקְרָא גִבּוֹר בַּתּוֹרָה וִירֵא חֵטְא. וְאִם הוּא בּוּר, נֶאֱמַר בּוֹ אֵין בּוּר יְרֵא חֵטְא.</p>\n<p>וּמִי שֶׁזּוֹכֶה לְתִפְאֶרֶת, שֶׁהוּא ו', וְהוּא חָכָם מֵבִין בַּתּוֹרָה וִירֵא חֵטְא, הוּא יוֹרֵשׁ אֶת מַלְכוּתוֹ, שֶׁהִיא הֵ\"א, מִצְוַת הַמֶּלֶךְ, אִם עוֹשֶׂה אֶת מִצְווֹת הַמֶּלֶךְ. כֵּיוָן שֶׁזּוֹכֶה לְשֵׁם יְהֹוָ\"ה, זוֹכֶה לַשֵּׁם הַמְפֹרָשׁ שֶׁנִּקְרָא אָדָם, וְזֶה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. בְּאוֹתוֹ זְמַן שׁוֹלֵט עַל גּוּפוֹ, שֶׁהוּא שֻׁתָּפוּת שֶׁל נֶפֶשׁ הַבַּהֲמִית, וְרוּחַ הַבַּהֲמִית שֶׁבַּנֶּפֶשׁ הַבַּהֲמִית עֲשִׂיַּת הַבְלֵי הָעוֹלָם, רוּחַ שֶׁמְּדַבֶּרֶת בְּהַבְלֵי הָעוֹלָם, (נשמה שבה כל ההרהורים והמחשבות של הבלי העולם), וְתַלְמִיד חָכָם שׁוֹלֵט עֲלֵיהֶם.</p>\n<p>זְהִוּ שֶׁכָּתוּב, (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ. מַה זֶּה וּבְכָל הָאָרֶץ? זֶה הַגּוּף, עוֹלָם קָטָן, וּפוֹחֲדִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (שם ט) וּמוֹרַאֲכֶם וְחִתְּכֶם. מִצַּד הַיָּמִין שׁוֹלֵט עֲלֵיהֶם, בּוֹ וְיִרְדּוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עב) וְיֵרְדְּ מִיָּם עַד יָם. מִצַּד הַשְּׂמֹאל פּוֹחֲדִים מִמֶּנּוּ, זֶהוּ שֶׁכָּתוּב וּמוֹרַאֲכֶם וְחִתְּכֶם, וְעָלָיו נֶאֱמַר יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ.</p>\n<p>אַחַר שֶׁהוּא צַדִּיק, לֹא נוֹתֵן לוֹ שְׂכַר מִצְווֹת, אֵין לוֹ שָׂכָר בָּעוֹלָם הַזֶּה וְלֹא מָזוֹן לַבְּהֵמוֹת, שֶׁעָנִי חָשׁוּב כְּמוֹ מֵת. הוּא עִם הַשְּׁכִינָה בִּקְבִיעוּת שֶׁלָּהּ עִמָּהּ עַל הַכֹּל.</p>\n<p>כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא (דברים ד). הָאֵשׁ הַזּוֹ הוּא צָרִיךְ לִהְיוֹת תָּמִיד עִמָּהּ, שֶׁאֵין לָהּ כְּבִיָּה, שֶׁהוּא אוֹכֵל כָּל הַקָּרְבָּנוֹת שֶׁל הַתְּפִלּוֹת וְדִבְרֵי תוֹרָה. שֶׁהִיא הַשְּׁכִינָה הִיא פַּרְנָסָתוֹ, וּבַמֶּה? בִּתְפִלָּה, זֶהוּ שֶׁכָּתוּב (שיר ה) פִּתְחִי לִי. פִּתְחִי לִי, בִּתְפִלָּה, שֶׁנֶּאֱמַר בָּהּ (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח, שֶׁהִיא אֲחֹתִי רַעְיָתִי, וְאֵין רַעְיָתִי אֶלָּא פַּרְנָסָתִי, שֶׁבָּהּ מְתַקְּנִים מַאֲכָלִים שֶׁל קָרְבָּנוֹת שֶׁל הַמֶּלֶךְ הַבָּנִים הַקְּדוֹשִׁים, בְּכַמָּה מִינֵי מַאֲכָלִים, בַּלֶּחֶם שֶׁל הַתּוֹרָה.</p>\n<p>שֶׁנֶּאֱמַר בָּהּ (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי, מִיָּמִין. וּבְיַיִן, שֶׁהוּא יֵין הַתּוֹרָה, מִשְּׂמֹאל. בְּנִסּוּךְ הַמַּיִם, וְיֵין הַתּוֹרָה שֶׁבִּכְתָב וּבְעַל פֶּה, מֵהָעַמּוּד הָאֶמְצָעִי שֶׁכּוֹלֵל אֶת שְׁנֵיהֶם. בְּבָשָׂר, שֶׁהוּא בְּשַׂר הַקֹּדֶשׁ, בְּכַמָּה קָרְבָּנוֹת, שֶׁעָלֶיהָ פֵּרְשׁוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁעוֹסְקִים בְּבָשָׂר הַיּוֹרֵד מִן הַשָּׁמַיִם. מַה זֶּה מִן הַשָּׁמַיִם? זֶה הָעַמּוּד הָאֶמְצָעִי, שֶׁעָלָיו נֶאֱמַר וּבָשָׂר מִבְּשָׂרִי.</p>\n<p>וְזְהִ בְּשַׂר הַקֹּדֶשׁ, שֶׁדּוֹלֶקֶת בְּכַמָּה שַׁלְהָבוֹת מִצַּד הַגְּבוּרָה בְּאַהֲבַת בַּעְלָהּ, נִשְׂרֶפֶת בְּאַהֲבָה שֶׁל אַהֲבָה בִּקְרִיאַת שְׁמַע, בְּאַהֲבַת הַיִּחוּד, שֶׁלַּיְלָה וָיוֹם לֹא תִכְבֶּה. וְהַחֲבֵרִים, בְּחַיֵּיכֶם, אַל תִּתְּנוּ דֳמִי לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא יִהְיֶה בְּשַׁלְהָבוֹת שֶׁל אַהֲבָה שֶׁל יִחוּדוּ בַּקְּרִיאַת שְׁמַע, לְקַיֵּם בּוֹ אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. (ע\"כ רעיא מהימנא).</p>"],[9522012012,"<p>בֹּא רְאֵה, אַף עַל גַּב שֶׁבְּנֵי אַהֲרֹן מֵתוּ בְּאוֹתָהּ שָׁעָה, זֶה הָיָה מַתְאִים בְּכַמָּה גְוָנִים. אֶחָד - שֶׁלֹּא הָיְתָה זוֹ שְׁעַת הַקְּטֹרֶת, שֶׁהֲרֵי קְטֹרֶת אֵינָהּ עוֹלָה אֶלָּא בִּזְמַנִּים יְדוּעִים, שֶׁכָּתוּב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר. וּמָתַי? בְּהֵיטִיבוֹ אֶת הַנֵּרֹת וְגוֹ', לְהִמָּצֵא שֶׁמֶן וּקְטֹרֶת כְּאֶחָד. וְכָתוּב, וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה וְגוֹ'.</p>\n<p>וּבַזְּמַנִּים הַלָּלוּ נִקְרֶבֶת, וְלֹא בִזְמַן אַחֵר, פְּרָט לִזְמַן שֶׁהַמָּוֶת שָׁרוּי בָּעוֹלָם, כְּמוֹ שֶׁקָּרָה, שֶׁכָּתוּב (במדבר יז) וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ וְגוֹ'. וּבְנֵי אַהֲרֹן לֹא הִקְרִיבוּ בְשָׁעָה שֶׁשֶּׁמֶן וּקְטֹרֶת נִמְצָאִים כְּאֶחָד.</p>\n<p>וְעוֹד, שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם, וְעוֹד שֶׁלֹּא הָיוּ נְשׂוּאִים, וְהָיוּ פְגוּמִים. שֶׁמִּי שֶׁלֹּא נִשָּׂא הוּא פָּגוּם, וְאֵינוֹ כְדַאי שֶׁיִּמָּצְאוּ בְרָכוֹת עַל יָדוֹ בָּעוֹלָם. עָלָיו הֵן לֹא שׁוֹרוֹת, כָּל שֶׁכֵּן עַל יְדֵי אֲחֵרִים. וְעוֹד, שֶׁהֲרֵי שָׁנִינוּ שֶׁהָיוּ שְׁתוּיֵי יַיִן, וּמִשּׁוּם כָּךְ וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אֹתָם וְגוֹ'. שֶׁהֲרֵי הַקְּטֹרֶת הִיא חֲבִיבָה מִן הַכֹּל, וְהִיא שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְכָתוּב שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.</p>"],[9522012013,"<p>רעיָּא מְהֵיּמְנָא אֵין מְצֹרָע אֶלָּא אוֹתוֹ שֶׁנַּעֲשֶׂה בְזִיבָה. שֶׁחֲמִשָּׁה דָמִים הֵם שֶׁל דַּם נִדָּה שֶׁמְּטַמְּאִים, שֶׁכֻּלָּם הֵם דָּם טָמֵא, וַחֲמִשָּׁה דָמִים טְהוֹרִים. וּמִי שֶׁעוֹבֵר עֲלֵיהֶם כְּאִלּוּ עָבַר עַל עֲשֶׂרֶת הַדִּבְּרוֹת, שֶׁהֵם כְּלָל שֶׁל תַּרְיַ\"ג מִצְווֹת.</p>\n<p>וְשִׁפְחָה, יֵצֶר הָרָע, הִיא מְלֵאָה בְּמוּמִים, וּמִשּׁוּם כָּךְ (ויקרא כא) כָּל אֲשֶׁר בּוֹ מוּם לֹא יִקְרָב. וּמִשּׁוּם זֶה הַכֹּהֵן לֹא הָיָה צָרִיךְ לִקְרַב אֶל מִי שֶׁיֵּשׁ בּוֹ מוּם מִכָּל הַמּוּמִים שֶׁבָּעוֹלָם, מִשּׁוּם שֶׁנֶּאֱמַר בַּגְּבִירָה, (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ, כָּךְ לֹא צָרִיךְ לִקְרַב אֵלֶיהָ מִי שֶׁיֵּשׁ בּוֹ מוּם, וְאַף כָּךְ לֹא צָרִיךְ לִקְרַב אֵלֶיהָ זָר, (במדבר ג) וְהַזָּר הַקָּרֵב יוּמָת, וְהַיְנוּ מַמְזֵ\"ר, מוּ\"ם זָר. מוּם נְקֵבָה, זָר זָכָר. וּמִשּׁוּם כָּךְ צִוָּה, (ויקרא יח) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב. וְעַל אוֹתָם שֶׁקְּרֵבִים אֵלֶיהָ כָּתוּב בָּהֶם, וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה אֲשֶׁר לֹא צִוָּה אֹתָם וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם וַיָּמֻתוּ.</p>\n<p>וְקָרְבָּן שֶׁל אוֹתִיּוֹת הֵם, י' בָּאִישׁ, ה' בָּאִשָּׁה, ו' בַּבֵּן חָתָן, ה' בַּכַּלָּה. אַשְׁרֵי מִי שֶׁמַּקְרִיב אוֹתִיּוֹת יְהֹוָ\"ה בּוֹ וּבְאִשְׁתּוֹ וּבִבְנוֹ וּבְבִתּוֹ בִּקְדֻשָּׁה וּבִבְרָכָה, בִּנְקִיּוּת, בַּעֲנָוָה וּבְבֹשֶׁת פָּנִים, בְּכָל מִדּוֹת טוֹבוֹת שֶׁכְּתוּבוֹת עַל בַּעֲלֵי הַמִּשְׁנָה.</p>\n<p>וּמִתְחַמְּמִים בְּאִשִּׁים קְדוֹשִׁים, שֶׁאִישׁ וְאִשָּׁה שֶׁהֵם אֵשׁ, עוֹלֶה וְיוֹרֵד, אֵשׁ קֹדֶשׁ שֶׁל עֲצֵי הַמַּעֲרָכָה, שֶׁהֵם עֲצֵי הַקֹּדֶשׁ אֵיבָרִים קְדוֹשִׁים, וְאֵשׁ שֶׁל גָּבוֹהַּ יוֹרֵד, שֶׁהִיא קֹדֶשׁ הַקְּדָשִׁים, וּבִשְׁבִיל שְׁנֵי הָאִשִּׁים הַלָּלוּ אָמַר הַנָּבִיא (ישעיה כד) בָּאוּרִים כַּבְּדוּ ה', שֶׁהֵם הָאִשִּׁים שֶׁל הַשְּׁכִינָה, שֶׁבָּהּ כָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא.</p>\n<p>וְהֵם אֵשׁ עֶלְיוֹן, כִּסֵּא רַחֲמִים. אֵשׁ תַּחְתּוֹנָה, כִּסֵּא דִין. וְהֵם בִּינָה וּמַלְכוּת. מַלְכוּת - אֵשׁ עוֹלֶה. בִּינָה - אֵשׁ יוֹרֵד. יְהֹוָה, עַמּוּד הָאֶמְצָעִי, אוֹחֵז בִּשְׁנֵיהֶם. בִּינָה יה\"ו, ה' מַלְכוּת.</p>\n<p>כַּאֲשֶׁר הַתִּפְאֶרֶת אוֹחֶזֶת אוֹתָם, שׁוֹרָה עָלָיו חָכְמָה, שֶׁבָּהּ כֹּ\"חַ מָ\"ה. מָ\"ה - הוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַכֹּחַ שֶׁלּוֹ - יוֹ\"ד וָא\"ו דָּלֶ\"ת. הֵ\"א אָלֶ\"ף. וָא\"ו אָלֶ\"ף וָא\"ו. הֵ\"א אָלֶ\"ף. וְכֻלָּן אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת נִמְצָאוֹת בָּאָדָם וּבְאִשְׁתּוֹ וּבְבָנָיו, וּמִשּׁוּם כָּךְ אֵין אָדָם שָׁלֵם אֶלָּא בְּבֵן וּבַת.</p>\n<p>וּמִי שֶׁאֵין לוֹ בֵּן, שֶׁהוּא ו', מִסְתַּלֶּקֶת מִמֶּנּוּ י'. וּמִי שֶׁאֵין לוֹ בַּת, שֶׁהִיא ה', מִסְתַּלֶּקֶת ה' הָעֶלְיוֹנָה, שֶׁהִיא אֵם, מִבַּת זוּגוֹ. שֶׁהָאוֹתִיּוֹת לֹא שׁוֹרוֹת זוֹ בְּלִי זוֹ, וּמִשּׁוּם כָּךְ בְּאִישׁ וְאִשָּׁה, בֵּן וּבַת שֶׁנַּעֲשׂוּ כָרָאוּי, שׁוֹרֶה עֲלֵיהֶם יְהֹוָ\"ה, וְנִקְרָאִים (בנים לקדוש ברוך הוא. זהו שכתוב) (שם יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. (ע\"כ רעיא מהימנא).</p>"],[9522012014,"<p>זֹאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. רַבִּי יוֹסֵי אָמַר, זֹּאת וַדַּאי מְשִׁיחַת אַהֲרֹן, שֶׁהֲרֵי אַהֲרֹן נִמְשַׁח, וּבָא מִשֶּׁמֶן מִשְׁחָה עָלָיו מִלְמַעְלָה, וּמַשְׁפִּיעַ אוֹתוֹ לְמַטָּה. וְעַל יְדֵי שֶׁאַהֲרֹן נִמְשַׁח מִמְּשִׁיחָה קְדוֹשָׁה לְהִתְבָּרֵךְ, וְעַל זֶה זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו וַדַּאי.</p>\n<p>רַבִּי יְהוּדָה פָּתַח, (מלכים בד) וַיֹּאמֶר אֵלֶיהָ אֱלִישָׁע מָה אֶעֱשֶׂה לָּךְ הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. מִכָּאן לָמַדְנוּ, שֶׁאֵין הַבְּרָכָה שׁוֹרָה בְשֻׁלְחָן רֵיק וְעַל דָּבָר רֵיקָנִי. וַתֹּאמֶר אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. אָמַר לָהּ, וַדַּאי זֶהוּ סִיּוּעַ שֶׁל נֵס, שֶׁהֲרֵי וַדַּאי אַחֲרָיו הוּא, וּמִשָּׁם בְּרָכוֹת יוֹצְאוֹת וְשׁוֹרוֹת. מַה כָּתוּב? הֵם מַגִּישִׁים אֵלֶיהָ וְהִיא מוֹצָקֶת. וְהִיא מוֹצָקֶת סְתָם.</p>\n<p>רַבִּי יוֹסֵי אָמַר, וַיַּעֲמֹד הַשָּׁמֶן, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (ישעיה ה) בְּקֶרֶן בֶּן שָׁמֶן. וְכָתוּב (שיר א) שֶׁמֶן תּוּרַק שְׁמֶךְ, לְהַרְאוֹת שֶׁהֲרֵי מֵהַשֶּׁמֶן הַזֶּה שׁוֹפְעוֹת בְּרָכוֹת עַל יַד הַכֹּהֵן, וְהַכֹּהֵן מַשְׁפִּיעַ אוֹתָן לְמַטָּה וּמוֹשֵׁחַ (ונמשך) לַזֹּאת הַזּוֹ. זֶהוּ שֶׁכָּתוּב זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו, וְכָתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012015,"<p>קַח אֶת אַהֲרֹן וְאֶת בָּנָיו אִתּוֹ וְאֶת הַבְּגָדִים. רַבִּי חִיָּיא פָּתַח, כִּי עִמְּךְ מְקוֹר חַיִּים בְּאוֹרְךְ נִרְאֶה אוֹר. כִּי עִמְּךְ מְקוֹר חַיִּים - זֶה הַשֶּׁמֶן הָעֶלְיוֹן שֶׁשּׁוֹפֵעַ וְאֵינוֹ פוֹסֵק לְעוֹלָמִים, שֶׁשָּׁרוּי בְּתוֹךְ הַחָכְמָה הָעֶלְיוֹנָה שֶׁל הַכֹּל. זֶהוּ שֶׁכָּתוּב כִּי עִמְּךְ, עִמְּךְ שָׁרוּי, וְלֹא נִפְרָד מִמְּךְ לְעוֹלָמִים, בַּחֲבִיבוּת שֶׁל הַכֹּל. מְקוֹר חַיִּים, מִשּׁוּם שֶׁהִיא מְקוֹר וּמַעְיַן הַחַיִּים, לְהוֹצִיא חַיִּים לָעֵץ הָעֶלְיוֹן וּלְהַדְלִיק אֶת הַנֵּרוֹת. וְעַל זֶה אוֹתוֹ הָעֵץ נִקְרָא עֵץ חַיִּים, הָאִילָן שֶׁנָּטוּעַ וְנִשְׁרָשׁ מִשּׁוּם אוֹתוֹ מְקוֹר הַחַיִּים.</p>\n<p>וְעַל זֶה בְּאוֹרְךְ נִרְאֶה אוֹר. בְּאוֹרְךְ - זֶה הָאוֹר שֶׁגָּנוּז לַצַּדִּיקִים לֶעָתִיד לָבֹא, שֶׁכָּתוּב (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וּמֵאוֹתוֹ אוֹר עֲתִידִים יִשְׂרָאֵל לְהָאִיר בָּעוֹלָם הַבָּא.</p>\n<p>דָּבָר אַחֵר כִּי עִמְּךְ מְקוֹר חַיִּים וְגוֹ' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא עֵץ עֶלְיוֹן בְּאֶמְצַע הַגָּן שֶׁאוֹחֵז אֶת כָּל הַצְּדָדִים. מָה הַטַּעַם? מִשּׁוּם שֶׁאָחוּז בּוֹ אוֹתוֹ (באותו) מְקוֹר חַיִּים, וּמְעַטֵּר אוֹתוֹ בַּעֲטָרוֹת עֶלְיוֹנוֹת סְבִיב הַגָּן כְּמוֹ אֵם שֶׁמְּעַטֶּרֶת אֶת בְּנָהּ עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן וְגוֹ'. וּמִשּׁוּם כָּךְ כִּי עִמְּךְ מְקוֹר חַיִּים, וְעַל זֶה בְּאוֹרְךְ נִרְאֶה אוֹר.</p>\n<p>רַבִּי יִצְחָק אָמַר, כִּי עִמְּךְ מְקוֹר חַיִּים - זֶה הַכֹּהֵן הַגָּדוֹל לְמַעְלָה, כְּנֶגְדּוֹ כֹּהֵן גָּדוֹל לְמַטָּה. מִשּׁוּם כָּךְ מַשְׁפִּיעַ הַכֹּהֵן שֶׁמֶן מִשְׁחַת קֹדֶשׁ עֶלְיוֹן לְמַטָּה וּמַדְלִיק מְנוֹרוֹת לְמַעְלָה. שֶׁהַכֹּהֵן הַגָּדוֹל שָׁלֵם בִּשְׁלֵמוּת שֶׁל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, וּלְהִתְעַטֵּר עַל הַכֹּל.</p>\n<p>כְּנֶגֶד זֶה שִׁבְעָה יְמֵי מִלּוּאִים לַכֹּהֵן שֶׁלְּמַטָּה, שֶׁיִּמָּצֵא הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה יְמֵי הַמִּלּוּאִים נִקְרְאוּ יְמֵי הַהַשְׁלָמָה, כְּדֵי שֶׁיִּשְׁתַּלֵּם הַכֹּהֵן בִּשְׁאָר הַיָּמִים הָאֲחֵרִים לְהַשְׁלִים שִׁבְעָה כְאֶחָד. וְאֵלֶּה נִקְרָאִים יְמֵי מִלּוּאִים, מִשּׁוּם שֶׁאוֹחֲזִים בּוֹ שְׁאָר הָאֲחֵרִים. מַה זֶּה אוֹמֵר? שֶׁכְּשֶׁהַכֹּהֵן מִתְעוֹרֵר, כָּל שְׁאָר הָאֲחֵרִים מִתְעוֹרְרִים עִמּוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ כָּתוּב, וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', עַד יוֹם מְלֹאת וְגוֹ'. שִׁבְעָה יָמִים וַדַּאי, וְאָז מִתְעַטֵּר הַכֹּהֵן לְמַטָּה בַּכֹּל כְּמוֹ שֶׁלְּמַעְלָה. מִשּׁוּם שֶׁבְּשָׁעָה שֶׁמִּתְעוֹרֵר הַכֹּהֵן שֶׁלְּמַטָּה, הַכֹּל יִתְעוֹרְרוּ עַל יָדוֹ לְמַעְלָה, וְיִמָּצְאוּ בְרָכוֹת לְמַעְלָה וּלְמַטָּה.</p>\n<p>רַבִּי אַבָּא אָמַר, מַה שּׁוֹנֶה שֶׁמָּשַׁח מֹשֶׁה אֶת אַהֲרֹן? אֶלָּא מִשּׁוּם שֶׁהוּא הַבֵּן שֶׁל אוֹתוֹ (אחוז באותו) מָקוֹם מְקוֹר הַחַיִּים, וְכָתוּב (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּמֹשֶׁה שִׁמֵּשׁ כָּל אוֹתָם יְמֵי מִלּוּאִים, לְהַשְׁרוֹת הַכֹּל עִם אַהֲרֹן.</p>\n<p>רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי אֶלְעָזָר. אָמַר לוֹ, כַּמָּה אוֹרוֹת נִבְרְאוּ טֶרֶם שֶׁנִּבְרָא הָעוֹלָם? אָמַר לוֹ, שִׁבְעָה. וְאֵלּוּ הֵם: אוֹר תּוֹרָה, אוֹר גֵּיהִנֹּם, אוֹר גַּן עֵדֶן, אוֹר כִּסֵּא הַכָּבוֹד, אוֹר בֵּית הַמִּקְדָּשׁ, אוֹר תְּשׁוּבָה, אוֹרוֹ שֶׁל מָשִׁיחַ. וְאֵלֶּה נִבְרְאוּ בְּטֶרֶם שֶׁנִּבְרָא הָעוֹלָם. שִׁבְעָה אוֹרוֹת וּמְאוֹרוֹת שֶׁנֶּאֶחְזוּ בְאַהֲרֹן, וְהוּא מַדְלִיק מְנוֹרוֹת מִמַּעְלָה לְמַטָּה.</p>"],[9522012016,"<p>רַבִּי אֶלְעָזָר פָּתַח, (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הֲרֵי שָׁנִינוּ, הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַלְגַּל חַמָּה. מִי הֶעָפָר? אוֹתוֹ שֶׁשָּׁרוּי תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ.</p>\n<p>בְּסִפְרוֹ שֶׁל רַב יֵיסָא סָבָא, הַכֹּל הָיָה מִן הֶעָפָר - מָקוֹם שֶׁכּוֹנֵס אֶת הַכֹּל. מְלַמֵּד שֶׁיָּצְאוּ שְׁבִילִים לַצַּד הַזֶּה וְלַצַּד הַזֶּה, וְהִתְכַּנְּסוּ לְהָאִיר כְּמוֹ הֶעָפָר הַזֶּה שֶׁזּוֹרְקִים אוֹתוֹ לְכָל עֵבֶר. וְעַל זֶה, הַכֹּל הָיָה מִן הֶעָפָר, וְהַכֹּל שָׁב אֶל הֶעָפָר וַדַּאי.</p>\n<p>אֶלָּא מִן הֶעָפָר - שֶׁל בֵּית הַמִּקְדָּשׁ הַקָּדוֹשׁ. וְהֶעָפָר הַזֶּה מֵהֶעָפָר הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר (איוב כח) וְעַפְרוֹת זָהָב לוֹ. כְּמוֹ שֶׁנִּמְצָא מַעֲשֶׂה לְמַטָּה, כָּךְ הוּא לְמַעְלָה כְּמוֹ זֶה. וּבֵאַרְנוּ עָפָר, עָפָר שֶׁל בֵּית הַמִּקְדָּשׁ, שֶׁהָעוֹלָם הַזֶּה נִבְרָא בְהֵ\"א. וְעַל זֶה - אֲפִלּוּ גַּלְגַּל חַמָּה, כְּמוֹ שֶׁנֶּאֱמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם - בְּה' בְּרָאָם. וּמִשּׁוּם כָּךְ, הַכֹּל הָיָה מִן הֶעָפָר. אֵיזֶה עָפָר? אוֹתוֹ שֶׁשָּׁרוּי תַּחַת כִּסֵּא הַכָּבוֹד הַקָּדוֹשׁ.</p>\n<p>כָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. כֻּלָּךְ יָפָה רַעְיָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּמוּם אֵין בָּךְ - אֵלּוּ סַנְהֶדְרִין, שֶׁהֵם כְּנֶגֶד שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת. שִׁבְעִים נֶפֶשׁ שֶׁיָּרְדוּ עִם יַעֲקֹב, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עַל כֻּלָּם. וְעַל זֶה אֵין בּוֹדְקִין מִן הַסַּנְהֶדְרִין וּלְמַעְלָה.</p>\n<p>שָׁנִינוּ, כָּתוּב (שמות יט) וְאַתֶּם תִּהְיוּ לִי מַמְלֶכֶת כֹּהֲנִים וְגוֹי קָדוֹשׁ. מִי זוֹ מַמְלֶכֶת כֹּהֲנִים? כְּמוֹ שֶׁנֶּאֱמַר, זֹּאת מִשְׁחַת אַהֲרֹן וּמִשְׁחַת בָּנָיו. שֶׁכְּשֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל עַל יַד הַכֹּהֲנִים, אָז נִקְרֵאת עַל שְׁמָם, זֶהוּ שֶׁכָּתוּב מַמְלֶכֶת כֹּהֲנִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה, מַלְכוּת כֹּהֲנִים לֹא נִקְרֵאת, אֶלָּא מַמְלֶכֶת, שֶׁהִמְלִיכוּ אוֹתָהּ הַכֹּהֲנִים וְעָשׂוּ אוֹתָהּ גְּבִירָה עַל הַכֹּל. אֲבָל מַלְכוּת כֹּהֲנִים לֹא נִקְרֵאת, שֶׁהֲרֵי מִן הַשָּׁמַיִם נִקְרֵאת מַלְכוּת, מַלְכוּת שָׁמַיִם וַדַּאי. וְכָאן מַמְלֶכֶת, כְּמוֹ שֶׁנֶּאֱמַר שֶׁכֹּהֲנִים הִמְלִיכוּ אוֹתָהּ, וּמְחַבְּרִים אוֹתָהּ עִם הַמֶּלֶךְ, וְאָז הִיא מַמְלֶכֶת עַל כָּל גִּנְזֵי הַמֶּלֶךְ. מַמְלֶכֶת עַל כָּל כְּלֵי זֵינוֹ שֶׁל הַמֶּלֶךְ. מַמְלֶכֶת בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים. מַמְלֶכֶת עַל כָּל הָעוֹלָם.</p>"],[9522012017,"<p>רַבִּי יוֹסֵי אָמַר, כָּתוּב (עמוס ט) וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ. וַאֲגֻדָּתוֹ - כְּשֶׁמִּזְדַּוֵּג הַמֶּלֶךְ כְּנֶגְדָּהּ בְּכָל אוֹתָן הָעֲטָרוֹת הַקְּדוֹשׁוֹת בְּכִנּוּס אֶחָד, אֲזַי וַאֲגֻדָּתוֹ כָּתוּב.</p>\n<p>רַבִּי יִצְחָק אָמַר, וַאֲגֻדָּתוֹ - כְּמוֹ שֶׁנֶּאֱמַר וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב. מַה זֶּה אוֹמֵר? שֶׁכְּשֶׁמִּתְחַבְּרִים כְּאֶחָד וּמִתְבָּרֶכֶת מֵהֶם, אֲזַי שׁוֹלֶטֶת עַל הַכֹּל וּמְאִירָה לְמַעְלָה וּלְמַטָּה, וְהַכֹּל בְּשָׁעָה שֶׁהַכֹּהֵן עוֹבֵד אֶת הָעֲבוֹדָה וּמַקְרִיב קָרְבָּן וּמַקְטִיר קְטֹרֶת וּמְכַוֵּן דְּבָרִים לְקָרֵב הַכֹּל כְּאֶחָד. אֲזַי כָּתוּב, וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כְּשֶׁנּוֹסֵעַ אַהֲרֹן, הַכֹּל נוֹסְעִים עִמּוֹ, עַד שֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, אֲזַי כָּתוּב (תהלים קלה) בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם הַלְלוּיָהּ. (שם עב) וּבָרוּךְ שֵׁם כְּבוֹדוֹ וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָרֶץ אָמֵן וְאָמֵן.</p>"],[9522012018,"<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ מִקַּפּוֹטְקִיָּא לְלוֹד, וְהָיוּ עִמּוֹ רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיה נא) וָאָשִׂם דְּבָרַי בְּפִיךְ וּבְצֵל יָדִי כִּסִּיתִיךְ וְגוֹ'. שָׁנִינוּ, כָּל אָדָם שֶׁמִּשְׁתַּדֵּל בְּדִבְרֵי תוֹרָה וְשִׂפְתוֹתָיו מְרַחֲשׁוֹת תּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַסֶּה עָלָיו, וּשְׁכִינָה פּוֹרֶשֶׂת כְּנָפֶיהָ עָלָיו. זֶהוּ שֶׁכָּתוּב וָאָשִׂם דְּבָרַי בְּפִיךְ וּבְצֵל יָדִי כִּסִּיתִיךְ. וְלֹא עוֹד, אֶלָּא שֶׁהוּא מְקַיֵּם אֶת הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ עִמּוֹ כְּאִלּוּ אוֹתוֹ יוֹם נָטַע שָׁמַיִם וָאָרֶץ. זֶהוּ שֶׁכָּתוּב (שם) לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה.</p>\n<p>מִכָּאן לָמַדְנוּ שֶׁיִּשְׂרָאֵל נִקְרְאוּ בַשֵּׁם שֶׁל צִיּוֹן, שֶׁכָּתוּב וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה. וְרָאִיתִי שֶׁכְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת בַּשֵּׁם שֶׁל צִיּוֹן, שֶׁכָּתוּב (שם א) צִיּוֹן בְּמִשְׁפָּט תִּפָּדֶה וְשָׁבֶיהָ בִּצְדָקָה.</p>\n<p>עוֹד פָּתַח וְאָמַר, (שם ח) צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמֻּדָי. צוֹר תְּעוּדָה - זוֹ עֵדוּת שֶׁל דָּוִד, שֶׁכָּתוּב (תהלים קלב) וְעֵדוֹתִי זוֹ אֲלַמְּדֵם. צוֹר - הִיא קִשּׁוּר, כְּמוֹ שֶׁקּוֹשֵׁר קֶשֶׁר בְּמָקוֹם אֶחָד. חֲתוֹם תּוֹרָה בְּלִמֻּדָי. חֲתוֹם תוֹרָה - חֲתִימָה שֶׁל הַתּוֹרָה, וְכָל שֶׁפַע וּמִשְׁחַת שֶׁמֶן שֶׁשּׁוֹפְעִים מִלְמַעְלָה, בְּאֵיזוֹ (בין) חֲתִימָה שֶׁלּוֹ? בְּלִמֻּדָי. מִשּׁוּם שֶׁשָּׁם מִתְכַּנֵּס שֶׁמֶן מִשְׁחָה בֵּין שְׁנֵי עַמּוּדִים שֶׁשָּׁם שׁוֹרִים, מְקוֹם הַכִּנּוּס שֶׁל כָּל שֶׁמֶן מִשְׁחָה שֶׁשּׁוֹפֵעַ מִמַּעַל, לִשְׁפֹּךְ אוֹתוֹ לְפִי הָאַמָּה וּלְהָרִיק אוֹתוֹ בַּתְּעוּדָה הַזֹּאת, וְאָז נִקְשָׁר הַכֹּל קֶשֶׁר אֶחָד נֶאֱמָן.</p>"],[9522012019,"<p>בֹּא וּרְאֵה מַה בֵּין אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִנְבִיאִים נֶאֱמָנִים. אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עֲדִיפִים מִנְּבִיאִים בְּכָל פַּעַם. מָה הַטַּעַם? שֶׁהֵם עוֹמְדִים בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר מִבַּנְּבִיאִים, אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עוֹמְדִים לְמַעְלָה, בְּמָקוֹם שֶׁנִּקְרָא תוֹרָה, (תפארת) שֶׁהוּא קִיּוּמָהּ שֶׁל כָּל הָאֱמוּנָה, וּנְבִיאִים עוֹמְדִים לְמַטָּה בְּמָקוֹם שֶׁנִּקְרְאוּ נֵצַח וְהוֹד. וְעַל כֵּן (נקראו) אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה עֲדִיפִים מִנְּבִיאִים, וְעֶלְיוֹנִים יוֹתֵר מֵהֶם. שֶׁאֵלּוּ עוֹמְדִים לְמַעְלָה, וְאֵלּוּ עוֹמְדִים לְמַטָּה. וְאוֹתָם שֶׁאוֹמְרִים דְּבָרִים בְּרוּחַ הַקֹּדֶשׁ, עוֹמְדִים לְמַטָּה מִכֻּלָּם.</p>\n<p>אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁהֵם בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה עַל הַכֹּל. מִי שֶׁעוֹסֵק בַּתּוֹרָה, לֹא צָרִיךְ לֹא לְקָרְבָּנוֹת וְלֹא לְעוֹלוֹת, שֶׁהֲרֵי הַתּוֹרָה עֲדִיפָה מֵהַכֹּל, וְקֶשֶׁר שֶׁל הָאֱמוּנָה שֶׁל הַכֹּל. וְעַל זֶה כָּתוּב, דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבֹתֶיהָ שָׁלוֹם. וְכָתוּב, (תהלים קיט) שָׁלוֹם רָב לְאֹהֲבֵי תוֹרָתֶךְ וְאֵין לָמוֹ מִכְשׁוֹל.</p>"],[9522012020,"<p>עַד שֶׁהָיוּ הוֹלְכִים, מָצְאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא וּשְׁלֹשָׁה עַנְפֵי הֲדַס בְּיָדוֹ. קָרְבוּ אֵלָיו, אָמְרוּ לוֹ, לָמָּה לְךְ אֶת אֵלֶּה? אָמַר, לְהַרְוִיחַ אֲבֵדָה. אָמַר רַבִּי אֶלְעָזָר, יָפֶה אָמַרְתָּ, אֲבָל שְׁלֹשָׁה אֵלֶּה לְשֵׁם מָה? אָמַר לוֹ, אֶחָד לְאַבְרָהָם, אֶחָד לְיִצְחָק, וְאֶחָד לְיַעֲקֹב, וְקָשַׁרְתִּי אוֹתָם יַחַד וְהֵרַחְתִּי בָהֶם, מִשּׁוּם שֶׁכָּתוּב (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךְ. מִשּׁוּם שֶׁבָּרֵיחַ הַזֶּה עוֹמֶדֶת חֻלְשַׁת הַנֶּפֶשׁ, וּבָאֱמוּנָה הַזּוֹ מִתְקַיֶּמֶת, וְשׁוֹפְעוֹת בְּרָכוֹת מִמַּעְלָה וּמַטָּה. אָמַר רַבִּי אֶלְעָזָר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, אֵין הָעוֹלָם (הנפש) מִתְקַיֵּם אֶלָּא עַל רֵיחַ, וּמֵהָרֵיחַ הַזֶּה נוֹדָע רֵיחַ אַחֵר. שֶׁהֲרֵי בְּשָׁעָה שֶׁיּוֹצֵאת שַׁבָּת (נתפרדה החבילה) וְעוֹלָה הַנֶּפֶשׁ הַיְתֵרָה, וְנִשְׁאֲרוּ הַנֶּפֶשׁ וְהָרוּחַ נִפְרָדוֹת עֲצוּבוֹת, בָּא הָרֵיחַ הַזֶּה, וּמִתְקָרְבִים זֶה לָזֶה וּשְׂמֵחִים.</p>\n<p>וְעַל זֶה צָרִיךְ רוּחַ אַחַר רוּחַ, לְקַבֵּל רֵיחַ. כֵּיוָן שֶׁמִּתְקַבֵּל רֵיחַ, מִתְקָרְבִים כְּאֶחָד וּשְׂמֵחִים. כְּגוֹן זֶה רֵיחַ שֶׁל הַקָּרְבָּנוֹת, בְּרֵיחַ זֶה מִתְקָרְבִים כֻּלָּם כְּאֶחָד, וְנִדְלָקִים הַנֵּרוֹת וּשְׂמֵחִים.</p>\n<p>בֹּא רְאֵה, שְׁנֵי מְאוֹרוֹת, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, אִם מַלְהִיט אָדָם הַמָּאוֹר שֶׁלְּמַטָּה הַזֶּה וּמְכַבֶּה אוֹתוֹ (את אותו שלמעלה), אוֹתוֹ עָשָׁן שֶׁעוֹלֶה (מהמאור התחתון), מַלְהִיט אוֹתוֹ הַמָּאוֹר הָעֶלְיוֹן. כָּךְ עֲשַׁן הַקָּרְבָּנוֹת, הֶעָשָׁן הַזֶּה שֶׁעוֹלֶה, מַלְהִיט הַמְּאוֹרוֹת הָעֶלְיוֹנִים וּמִתְלַהֲטִים בְּאֶחָד, וְכֻלָּם מִתְקָרְבִים כְּאֶחָד בָּרֵיחַ הַזֶּה. וּמִשּׁוּם כָּךְ, רֵיחַ נִיחֹחַ לַה', (אשה) וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְעַל כֵּן רֵיחַ הַקָּרְבָּן הוּא קִיּוּם שֶׁל הַכֹּל וְקִיּוּם הָעוֹלָם. וְהַקָּרְבָּן עַל יַד הַכֹּהֵן שֶׁמַּקְרִיב הַכֹּל, וּמִשּׁוּם כָּךְ שִׁבְעָה יְמֵי הַשְׁלָמָה נִשְׁתַּלְּמוּ בוֹ, כְּדֵי שֶׁכֻּלָּם יִתְבָּרְכוּ בַעֲבוֹדָתוֹ, וְיִמָּצְאוּ שְׂמָחוֹת וּבְרָכוֹת לְמַעְלָה וּלְמַטָּה.</p>"],[9522012021,"<p>כָּתוּב, (ישעיה כה) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךְ וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, ה' אֱלֹהַי אַתָּה, שֶׁצָּרִיךְ אָדָם לְהוֹדוֹת לַשֵּׁם הַקָּדוֹשׁ וּלְשַׁבֵּחַ אוֹתוֹ עַל הַכֹּל. וּמֵאֵיזֶה מָקוֹם הַשֶּׁבַח שֶׁלּוֹ? כְּמוֹ שֶׁבֵּאֲרוּהָ. וְכָאן מֵהָעֹמֶק שֶׁל הַכֹּל, שֶׁכָּתוּב כִּי עָשִׂיתָ פֶּלֶא. פֶּלֶא - כְּמוֹ שֶׁכָּתוּב (שם ט) וַיִּקְרָא שְׁמוֹ פֶּלֶא, וַהֲרֵי נֶאֱמַר. עֵצוֹת מֵרָחֹק, עֵצוֹת - כְּמוֹ שֶׁנֶּאֱמַר יוֹעֵץ. מֵרָחֹק - שֶׁכָּתוּב (ירמיהלא) מֵרָחוֹק ה' נִרְאָה לִי. וְכָתוּב (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ.</p>\n<p>אֱמוּנָה אֹמֶן - כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) אֵל אֱמוּנָה וְאֵין עָוֶל. וּפֵרְשׁוּהָ אֱמוּנָה בַּלַּיְלָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים צב) וֶאֱמוּנָתְךְ בַּלֵּילוֹת. וְכָתוּב (איכה ג) חֲדָשִׁים לַבְּקָרִים רַבָּה אֱמוּנָתֶךְ. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת יִשְׂרָאֵל מֵחֲטָאֵיהֶם, כְּמוֹ שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אִתכִם, בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן</p>"],[9522012022,"<p>וַיְהִי בַּיּוֹם הַשְּׁמִינִי וְגוֹ'. רַבִּי יִצְחָק פָּתַח, (איוב לח) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה, שִׂמְחַת הַכֹּל, שִׂמְחָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַשַּׁעֲשׁוּעַ שֶׁלּוֹ, שֶׁכָּתוּב (משלי ח) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְכָל הַתּוֹרָה הִיא שֵׁם אֶחָד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבַתּוֹרָה נִבְרָא הָעוֹלָם, שֶׁכָּתוּב וָאֶהְיֶה אֶצְלוֹ אָמוֹן, אַל תִּקְרֵי אָמוֹן אֶלָּא אֻמָּן.</p>\n<p>וּבַתּוֹרָה נִבְרָא אָדָם, זֶהוּ שֶׁכָּתוּב (בראשיתא) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַתּוֹרָה: אֲנִי רוֹצֶה לִבְרֹא אָדָם. אָמְרָה לְפָנָיו: הָאָדָם הַזֶּה עָתִיד לַחֲטֹא וּלְהַרְגִּיז לְפָנֶיךְ, אִם לֹא תַאֲרִיךְ רָגְזְךְ עָלָיו, אֵיךְ יַעֲמֹד בָּעוֹלָם?! אָמַר לָהּ: אֲנִי וְאַתְּ נַעֲמִיד אוֹתוֹ בָּעוֹלָם, שֶׁהֲרֵי לֹא לְחִנָּם נִקְרֵאתִי אֶרֶךְ אַפַּיִם. (שהרי כל זמן שישתדלו בתורה, יתקימו בעולם).</p>\n<p>רַבִּי חִיָּיא אָמַר, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה הֶעֱמִידוּ אֶת הָאָדָם בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. רַבִּי יוֹסֵי אָמַר מִכָּאן, (קהלת ב) אֵת אֲשֶׁר כְּבָר עָשׂוּהוּ, עָשׂוּהוּ וַדַּאי. וְזֶהוּ צֶלֶם וּדְמוּת. צֶלֶם - בְּזָכָר. דְּמוּת - בִּנְקֵבָה. וְעַל זֶה הַתְחָלַת הַתּוֹרָה בְּב', וּפֵרְשׁוּהָ.</p>\n<p>רַבִּי יִצְחָק אָמַר, מִפְּנֵי מָה ב' פְּתוּחָה וּסְתוּמָה? אֶלָּא בְּשָׁעָה שֶׁאָדָם בָּא לְהִתְחַבֵּר עִם הַתּוֹרָה, הֲרֵי הִיא פְּתוּחָה לְקַבֵּל אוֹתוֹ וּלְהִשְׁתַּתֵּף עִמּוֹ. וּבְשָׁעָה שֶׁאָדָם סוֹתֵם עֵינָיו מִמֶּנָּה וְהוֹלֵךְ לְדֶרֶךְ אַחֶרֶת, הֲרֵי הִיא סְתוּמָה מֵהַצַּד הָאַחֵר, כְּמוֹ שֶׁנֶּאֱמַר, אִם יוֹם תַּעַזְבֵנִי - יוֹמַיִם אֶעֶזְבֶךָּ. וְלֹא יִמְצָא פֶתַח עַד שֶׁיָּשׁוּב לְהִתְחַבֵּר עִם הַתּוֹרָה פָּנִים בְּפָנִים, וְלֹא יִשְׁכַּח מִמֶּנָּה. וְלָכֵן הַתּוֹרָה פּוֹתַחַת לִפְנֵי בְּנֵי אָדָם וּמַכְרִיזָה וְקוֹרֵאת לָהֶם, (משלי ח) אֲלֵיכֶם אִישִׁים אֶקְרָא וְגוֹ', וְכָתוּב (שם א) בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בָּעִיר אֲמָרֶיהָ תֹאמֵר.</p>\n<p>רַבִּי יְהוּדָה אָמַר, ב' שְׁנֵי גַגּוֹת, וְאֶחָד שֶׁאוֹחֵז אוֹתָם. מַה זֶּה אוֹמֵר? אֶלָּא אֶחָד לַשָּׁמַיִם וְאֶחָד לָאָרֶץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹחֵז וּמְקַבֵּל אוֹתָם.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, שְׁלֹשָׁה אוֹרוֹת (צדדים אלו) אֵלּוּ עֶלְיוֹנִים קְדוֹשִׁים שֶׁאֲחוּזִים כְּאֶחָד, וְהֵם הַכְּלָל שֶׁל הַתּוֹרָה, וְאֵלּוּ פּוֹתְחִים פֶּתַח לַכֹּל. פּוֹתְחִים פֶּתַח לָאֱמוּנָה, וְאֵלֶּה הַבַּיִת שֶׁל הַכֹּל, וְעַל זֶה נִקְרְאוּ בַיִת, שֶׁאֵלֶּה הֵם הַבַּיִת. מִשּׁוּם כָּךְ הַתְחָלַת הַתּוֹרָה ב', שֶׁהֲרֵי הַתּוֹרָה (פרותיה הם הרפואה) הִיא רְפוּאַת הָעוֹלָם.</p>\n<p>וּמִשּׁוּם כָּךְ, מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כְּאִלּוּ הִשְׁתַּדֵּל בַּשֵּׁם הַקָּדוֹשׁ. וַהֲרֵי נִתְבָּאֵר שֶׁכָּל הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ אֶחָד עֶלְיוֹן, וּמִשּׁוּם שֶׁהִיא שֵׁם קָדוֹשׁ, הִיא פּוֹתַחַת בְּבֵית, שֶׁהִיא הַכְּלָל שֶׁל הַשֵּׁם הַקָּדוֹשׁ בִּשְׁלֹשֶׁת קִשְׁרֵי הָאֱמוּנָה.</p>\n<p>בֹּא רְאֵה, כָּל אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, נִדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, וּמִתְעַטְּרִים בְּעַטְרוֹת הַתּוֹרָה, וַאֲהוּבִים לְמַעְלָה וּלְמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשִׁיט לָהֶם אֶת יְמִינוֹ (והקדוש ברוך הוא רושם אותם). כָּל שֶׁכֵּן אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה גַּם בַּלַּיְלָה, וַהֲרֵי פֵּרְשׁוּהָ שֶׁהֵם מִשְׁתַּתְּפִים עִם הַשְּׁכִינָה (בכנסת ישראל) וּמִתְחַבְּרִים כְּאֶחָד. וּכְשֶׁבָּא הַבֹּקֶר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַטֵּר אוֹתָם בְּחוּט אֶחָד שֶׁל חֶסֶד, לְהִוָּדַע בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְכָל אוֹתָם כּוֹכְבֵי בֹקֶר, בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל וְכָל אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה בָּאִים לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ, כֻּלָּם מְזַמְּרִים כְּאֶחָד. זֶהוּ שֶׁכָּתוּב בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מַה זֶּה וַיָּרִיעוּ? כְּמוֹ שֶׁנֶּאֱמַר (ישעיהכד) רֹעָה הִתְרֹעֲעָה הָאָרֶץ. שֶׁאוֹתָם דִּינִים מִשְׁתַּבְּרִים, וְכֻלָּם נִשְׁבָּרִים מִלִּפְנֵי הַבֹּקֶר, כְּשֶׁמִּתְעוֹרֵר בֹּקֶר בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. וְעַל כֵּן - וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>"],[9522012023,"<p>רַבִּי אֶלְעָזָר הָיָה הוֹלֵךְ בַּדֶּרֶךְ. מָצָא אֶת רַבִּי פִּנְחָס בֶּן יָאִיר שֶׁהָיָה בָּא. גָּעָה חֲמוֹרוֹ. אָמַר רַבִּי פִּנְחָס, וַדַּאי בְּמִשְׁקַל (בקול) שִׂמְחַת הַחֲמוֹר אֲנִי רוֹאֶה שֶׁפָּנִים חֲדָשׁוֹת יִמָּצְאוּ פֹה. כֵּיוָן שֶׁיָּצָא מֵאַחַר עַנְפֵי הָהָר, רָאָה אֶת רַבִּי אֶלְעָזָר שֶׁהָיָה בָּא. אָמַר, וַדַּאי מִשְׁקַל (קול) הַשִּׂמְחָה נִשְׁלָם. יָרַד רַבִּי אֶלְעָזָר אֵלָיו וְנָשַׁק לוֹ. אָמַר לוֹ, אִם צוּרַת הַדֶּרֶךְ הָאַחַת אֵלֶיךְ, נֵלֵךְ וְנִתְחַבֵּר כְּאֶחָד. וְאִם לֹא, קַח אֶת דַּרְכְּךְ וָלֵךְ. אָמַר לוֹ, וַדַּי שֶׁכְּנֶגְדְּךְ אֲנִי הוֹלֵךְ, כֵּיוָן שֶׁמָּצָאתִי אוֹתְךְ, אֵלֵךְ אַחֲרֶיךְ וְנִתְחַבֵּר כְּאֶחָד.</p>\n<p>פָּתַח רַבִּי פִּנְחָס וְאָמַר, (תהלים קכח) יְבָרֶכְךְ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב וְגוֹ'. יְבָרֶכְךְ ה' מִצִּיּוֹן, מָה הַטַּעַם מִצִּיּוֹן? מִשּׁוּם שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת בְּרָכוֹת לְהִשְׁתַּתֵּף (להמצא). זֶהוּ שֶׁכָּתוּב, כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וּמִשּׁוּם כָּךְ, יְבָרֶכְךְ ה' מִצִּיּוֹן, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת בְּרָכוֹת לַכֹּל. וּרְאֵה בְּטוּב יְרוּשָׁלם, שֶׁבִּגְלַל צִיּוֹן יְרוּשָׁלַיִם מִתְבָּרֶכֶת. שֶׁכֵּיוָן שֶׁצִּיּוֹן הִתְמַלֵּא בִּבְרָכוֹת, אָז יְרוּשָׁלַיִם מִתְבָּרֶכֶת, וְנִמְצָאִים בָּהּ רַחֲמִים. וּכְשֶׁיְּרוּשָׁלַיִם מִתְבָּרֶכֶת, כָּל הָעָם מִתְבָּרֵךְ.</p>\n<p>כֹּל יְמֵי חַיֶּיךְ, שֶׁלֹּא תֵרָאֶה קֶשֶׁת בְּיָמֶיךְ כְּמוֹ לְאָבִיךְ. וְעַל זֶה - וּרְאֵה בְּטוּב יְרוּשָׁלם כֹּל יְמֵי חַיֶּיךְ. וּרְאֵה בָנִים לְבָנֶיךְ, יִרְאֵי חֵטְא, חֲסִידִים, קְדוֹשִׁים. אָז - שָׁלוֹם עַל יִשְׂרָאֵל. מַה זֶּה שָׁלוֹם עַל יִשְׂרָאֵל? אֶלָּא כְּמִי שֶׁאוֹמֵר: שָׁלוֹם עַל רֹאשׁ הַמֶּלֶךְ, שֶׁלֹּא יֶחְסַר כֹּל. כָּךְ שָׁלוֹם עַל יִשְׂרָאֵל, בִּזְמַן שֶׁצַּדִּיקִים יִמָּצְאוּ בָעוֹלָם.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (משלי יז) עֲטֶרֶת זְקֵנִים בְּנֵי בָנִים וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. בָּנִים - הֲרֵי בֵּאַרְנוּ. בְּנֵי בָנִים - אֵלּוּ שְׁאָר כִּתְרֵי הַמֶּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יד) וְכָל בָּנַיִךְ לִמּוּדֵי ה'. וְכָתוּב (איכה ד) בְּנֵי צִיּוֹן הַיְקָרִים, כְּמוֹ שֶׁנֶּאֱמַר וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. אֵין מִתְעַטְּרִים הַבָּנִים אֶלָּא בָּאָבוֹת. מִכָּאן לָמַדְנוּ שֶׁבָּנִים לֹא מִתְעַטְּרִים וְלֹא מֻשְׁקִים מֵהַשְׁקָיַת הַנַּחַל, אֶלָּא בִּזְמַן שֶׁהָאָבוֹת מִתְעַטְּרִים וּמְבָרְכִים. זֶהוּ שֶׁכָּתוּב וְתִפְאֶרֶת בָּנִים אֲבוֹתָם.</p>"],[9522012024,"<p>עַד שֶׁהָיוּ הוֹלְכִים, הִגִּיעַ זְמַן תְּפִלָּה. יָרְדוּ וְהִתְפַּלְלוּ. בְּעוֹד שֶׁהָיוּ מִתְפַּלְלִים, נִכְרַךְ נָחָשׁ אֶחָד בְּרַגְלֵי חֲמוֹרוֹ שֶׁל רַבִּי פִּנְחָס. בָּעַט (נבהל) וְגָעָה פַּעֲמַיִם. אַחַר שֶׁסִּיְּמוּ אֶת הַתְּפִלָּה, אָמַר רַבִּי פִּנְחָס: וַדַּאי צַעַר הוּא לַבְּהֵמָה שֶׁלִּי, שֶׁהֲרֵי הַיּוֹם הַזֶּה הִקְדַּמְתִּי, וְהָיִיתִי מְרַחֵשׁ בַּתּוֹרָה, וְהֶעֱבִיר אוֹתִי בְּמָקוֹם שֶׁשּׁוֹרֶה לִכְלוּךְ, וְעַכְשָׁו מְצַעֲרִים אוֹתוֹ. קָמוּ וְרָאוּ נָחָשׁ אֶחָד קָשׁוּר עַל רַגְלָיו. אָמַר רַבִּי פִּנְחָס: נָחָשׁ נָחָשׁ, לֵךְ וְסוֹבֵב (וצדד) אֶת קִשְׁרְךְ בְּמִדְרוֹן הַחוֹר. בֵּינְתַיִם נָשַׁר הַנָּחָשׁ וְנָפַל חֲתִיכוֹת חֲתִיכוֹת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וּמַה כָּל כָּךְ מְדַקְדֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא בַּצַּדִּיקִים? אָמַר לוֹ, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים וְשׁוֹמֵר אוֹתָם, וְרוֹצֶה לְהוֹסִיף לָהֶם קְדֻשָּׁה עַל קְדֻשָּׁתָם, וְעַכְשָׁו הַחֲמוֹר הַזֶּה, שֶׁלֹּא שָׁמַר אֶת הַקְּדֻשָּׁה שֶׁלִּי, הוּא הִצְטַעֵר. וְהַנָּחָשׁ הַזֶּה הָיָה שָׁלִיחַ, וְכַמָּה שְׁלִיחִים יֵשׁ לַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכֻלָּם הוּא עוֹשֶׂה אֶת שְׁלִיחוּתוֹ, וַאֲפִלּוּ בְּחַיּוֹת הַשָּׂדֶה. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְהִשְׁלַחְתִּי בָכֶם אֶת חַיַּת הַשָּׂדֶה וְשִׁכְּלָה אֶתְכֶם. וַאֲפִלּוּ בְּיַד גּוֹי, זֶהוּ שֶׁכָּתוּב (דברים כח) יִשָּׂא ה' עָלֶיךְ גּוֹי מֵרָחֹק מִקְצֵה הָאָרֶץ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וּבְיַד יִשְׂרָאֵל עוֹשֶׂה שְׁלִיחוּת? אָמַר לוֹ, כֵּן, כְּמוֹ רָשָׁע בְּיַד צַדִּיק. אֲבָל רָשָׁע בְּיַד יִשְׂרָאֵל רָשָׁע אַחֵר, לֹא עוֹשֶׂה בּוֹ שְׁלִיחוּת, אֶלָּא בִּזְמַן שֶׁאֵינוֹ מְכַוֵּן בּוֹ. זֶהוּ שֶׁכָּתוּב (שמות כא) וַאֲשֶׁר לֹא צָדָה וְהָאֱלֹהִים אִנָּה לְיָדוֹ. וַאֲשֶׁר לֹא צָדָה דַּוְקָא, שֶׁלֹּא לַהֲרֹג אוֹתוֹ. זֶה וְהָאֱלֹהִים אִנָּה לְיָדוֹ, כְּדֵי לְהַעֲנִישׁ אֶת שְׁנֵיהֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אֵיךְ עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלִיחוּת בִּידֵי אֵלֶּה וּבְיַד גּוֹי? אָמַר לוֹ, וְאָבִיךְ לֹא אָמַר לְךְ? אָמַר לוֹ, טֶרֶם שָׁאַלְתִּי.</p>\n<p>פָּתַח וְאָמַר, (איוב לד) וְהוּא יַשְׁקִט וּמִי יַרְשִׁעַ וְגוֹ'. וְהוּא יַשְׁקִט - בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן שֶׁקֶט וְשַׁלְוָה לָאָדָם, מִי הוּא שֶׁרַשַּׁאי לְהַזִּיק לוֹ וְלַעֲשׂוֹת לוֹ קָטֵגוֹרְיָה? וְיַסְתֵּר פָּנִים וּמִי יְשׁוּרֶנּוּ - וּבִזְמַן שֶׁהוּא מַסְתִּיר אֶת עֵינוֹ מִלְּהַשְׁגִּיחַ עָלָיו, מִי הוּא שֶׁיַּשְׁגִּיחַ עָלָיו לִשְׁמֹר אוֹתוֹ וְלַעֲשׂוֹת לוֹ שְׁמִירָה? וְדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה עַל גּוֹי וְעַל אָדָם יַחַד. בֵּין לְכָל הָעוֹלָם, בֵּין לְעַם אֶחָד, בֵּין לְאֶחָד לְבַדּוֹ.</p>\n<p>בֹּא רְאֵה, בִּזְמַן שֶׁבְּנֵי אָדָם כְּשֵׁרִים מַעֲשֵׂיהֶם לְמַטָּה, מִתְעוֹרֵר עֲלֵיהֶם לְמַעְלָה יְמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. אָז מִתְעוֹרְרִים כַּמָּה אוֹהֲבִים, כַּמָּה שׁוֹמְרֵי הָעוֹלָם, כַּמָּה שׁוֹמְרֵי הָאָדָם, מִיָּמִין וּמִשְּׂמֹאל. וְאָז נִכְנָע הַשְּׂמֹאל וְלֹא יָכוֹל לִשְׁלֹט. וּבִזְמַן שֶׁבְּנֵי אָדָם אֵין כְּשֵׁרִים מַעֲשֵׂיהֶם לְמַטָּה, מִתְעוֹרֵר הַשְּׂמֹאל, וְכָל אֵלּוּ שֶׁבָּאוּ מִצַּד הַשְּׂמֹאל, כֻּלָּם מִתְעוֹרְרִים וְכֻלָּם נַעֲשִׂים שְׁלוּחִים לְהָרַע לִבְנֵי הָאָדָם. שֶׁהֲרֵי אוֹתָם שֶׁעָבְרוּ עַל דִּבְרֵי הַתּוֹרָה, כֻּלָּם רְשׁוּמִים בִּפְנֵיהֶם, וְנוֹדָעִים לְאוֹתָם שֶׁמְּעוֹרְרִים מִצַּד הַשְּׂמֹאל.</p>\n<p>וּמִשּׁוּם כָּךְ הַחַיּוֹת וְעוֹבְדֵי עֲבוֹדָה זָרָה, וְכָל אוֹתָם שֶׁבָּאִים מִצַּד הַשְּׂמֹאל, כֻּלָּם נִקְרָאִים (הם) שְׁלוּחִים לְאוֹתָם הָרִשּׁוּמִים שֶׁמִּתְעוֹרְרִים אוֹתָם. וְיִשְׂרָאֵל, אַף עַל גַּב שֶׁאֵין מַעֲשֵׂיהֶם כְּשֵׁרִים, כֻּלָּם בָּאִים מִצַּד הַיָּמִין. וּמִשּׁוּם שֶׁהַיָּמִין נִכְנָע מִמַּעֲשֵׂיהֶם שׁוֹלֵט עֲלֵיהֶם הַשְּׂמֹאל, וְכָל אוֹתָם שֶׁבָּאִים מִצַּד הַשְּׂמֹאל. וְלָכֵן הַשְּׁלִיחוּת בִּידֵי הַחַיּוֹת וְהַגּוֹי וְכָל שֶׁדּוֹמֶה לָהֶם, שֶׁהֵם מִצַּד הַשְּׂמֹאל, וְלֹא בַּיָּד שֶׁל יִשְׂרָאֵל. שֶׁאַף עַל גַּב שֶׁהוּא רָשָׁע, הוּא בָּא מִצַּד הַיָּמִין.</p>\n<p>וְיִשְׂרָאֵל רָשָׁע שֶׁנָּפַל בְּיַד יִשְׂרָאֵל רָשָׁע אַחֵר, בִּזְמַן שֶׁלֹּא הִתְכַּוֵּן בּוֹ - כְּדֵי שֶׁשְּׁנֵיהֶם יֵעָנְשׁוּ וִיקַבְּלוּ עֹנֶשׁ לְטַהֵר אוֹתָם. אָמַר רַבִּי אֶלְעָזָר, מִנַּיִן לָנוּ? אָמַר לוֹ, הֵם בְּיָמִין, וְלֹא נִדְבְּקוּ בַשְּׂמֹאל, וְלֹא הִתְעָרְבוּ עִמּוֹ לְעוֹלָמִים, וְלָכֵן לִזְמַן אַחֵר הֵם יַעַבְרוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מִנַּיִן לָנוּ? אָמַר לוֹ, בֹּא רְאֵה מִפִּילֶגֶשׁ בַּגִּבְעָה, שֶׁאַף עַל גַּב שֶׁהָיוּ רְשָׁעִים, לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְעוֹרְרוּ אֲלֵיהֶם רִשְׁעֵי יִשְׂרָאֵל אֲחֵרִים, וְלָכֵן מֵתוּ (מישראל) כָּל אוֹתָם פְּעָמִים שֶׁמֵּתוּ. עַד שֶׁכָּל הָרְשָׁעִים שֶׁהִתְעוֹרְרוּ עֲלֵיהֶם מֵתוּ וְנֶאֶבְדוּ, וְנִשְׁאֲרוּ אוֹתָם צַדִּיקִים יוֹתֵר שֶׁיַּעֲשׁוּ אֶת הַדָּבָר בְּדֶרֶךְ אֲמִתִּית. וְאַף עַל גַּב שֶׁהֵם צַדִּיקִים, לֹא נִתָּן הַדָּבָר, אֶלָּא לְאוֹתָם שֶׁנִּתָּן. כְּשֶׁשְּׁקוּלִים הָעוֹלָמוֹת כְּאֶחָד, הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ הָעוֹלָם הָעֶלְיוֹן, וְאוֹתוֹ הַזְּמַן לֹא נִמְצְאוּ הָעוֹלָמוֹת שְׁקוּלִים כְּאֶחָד.</p>\n<p>וְעַל כֵּן, רְשָׁעִים שֶׁל יִשְׂרָאֵל לְגַבֵּי רְשָׁעִים אֲחֵרִים אֵינָם שְׁלוּחֵי הַמֶּלֶךְ, שֶׁהֲרֵי אֵינָם בָּאִים מִצַּד הַשְּׂמֹאל. מָשָׁל לִבְנֵי אָדָם שֶׁחָטְאוּ לַמֶּלֶךְ. הִתְעוֹרֵר הַשּׁוֹטֵר אֲלֵיהֶם לִתְפֹּשׂ אוֹתָם וּלְהַעֲנִישׁ אוֹתָם, לְאוֹתָם שֶׁחָטְאוּ לַמֶּלֶךְ. קָם חָכָם אֶחָד מֵהֶם וְהִתְעָרֵב עִם בְּנֵי הַשּׁוֹטֵר. הֵרִים הַשּׁוֹטֵר אֶת עֵינָיו וְרָאָה אוֹתוֹ. אָמַר לוֹ, מִי נָתַן אוֹתְךְ בֵּינֵינוּ? וַהֲרֵי אֵינְךְ מֵאוֹתָם שֶׁחָטְאוּ לַמֶּלֶךְ. הֲרֵי אתָּה תֵּעָנֵשׁ בָּרִאשׁוֹנָה! לָקְחוּ אוֹתוֹ וְהָרְגוּ אוֹתוֹ.</p>\n<p>כָּךָ יִשְׂרָאֵל בָּאִים מִצַּד הַיָּמִין, וְלֹא נִדְבְּקוּ בַּשְּׂמֹאל, וְלֹא הִתְעָרְבוּ עִמּוֹ לְעוֹלָמִים. וּכְשֶׁהֵם גּוֹרְמִים בַּעֲווֹנוֹתֵיהֶם שֶׁנִּכְנָע הַיָּמִין, וְהַשְּׂמֹאל מִתְעוֹרֵר וְכָל אוֹתָם שֶׁבָּאִים מִצִּדּוֹ - אִם אֶחָד מִיִּשְׂרָאֵל עוֹמֵד לְהִתְעָרֵב עִמָּם, הֵם מַכִּירִים אוֹתוֹ וְאוֹמְרִים לוֹ: אֵינְךְ מֵאוֹתָם שֶׁבָּאִים מִצַּד הַיָּמִין, שֶׁנִּכְנָע מֵהָעֲווֹנוֹת שֶׁלָּהֶם, וְאֵינְךְ מֵאוֹתָם שֶׁחָטְאוּ לַמֶּלֶךְ, מִי נָתַן אוֹתְךְ אֶצְלֵנוּ? נִמְצָא שֶׁהוּא נֶעֱנָשׁ בָּרִאשׁוֹנָה. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ כְּנֶגְדָּם וְאוֹמֵר, (קהלת ח) עֵת אֲשֶׁר שָׁלַט הָאָדָם בְּאָדָם לְרַע לוֹ. לְרַע לוֹ וַדַּאי, מִכֵּיוָן שֶׁאֵינוֹ שְׁלִיחַ הַמֶּלֶךְ, וְלֹא בָא מֵאוֹתוֹ הַצַּד.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי שָׁנִינוּ שֶׁיֵּשׁ יָמִין וְיֵשׁ שְׂמֹאל, רַחֲמִים וְדִין. יִשְׂרָאֵל (לימין), וְעוֹבְדֵי עֲבוֹדָה זָרָה לִשְׂמֹאל. יִשְׂרָאֵל, אַף עַל גַּב שֶׁהם רְשָׁעִים וְנִכְנָעִים, הֵם בְּיָמִין וְלֹא נִדְבָּקִים לַשְּׂמֹאל, וְלֹא מִתְעָרְבִים עִמּוֹ לְעוֹלָמִים. וּמִשּׁוּם כָּךְ כָּתוּב, (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. שֶׁכַּאֲשֶׁר מִתְעַלֶּה הַיָּמִין, יִשְׂרָאֵל שֶׁנִּדְבָּקִים עִמּוֹ יִתְעַלּוּ וְיִתְעַטְּרוּ בוֹ. אָז נִכְנָע הַשְּׂמֹאל, וְכָל אוֹתָם שֶׁבָּאִים מִצִּדּוֹ. זֶהוּ שֶׁכָּתוּב (שמות טו) יְמִינְךְ ה' תִּרְעַץ אוֹיֵב.</p>"],[9522012025,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, וַיְהִי בַּיּוֹם הַשְּׁמִינִי קָרָא וְגוֹ'. וַיְהִי בַּיּוֹם הַשְּׁמִינִי, מַה זֶּה בַּיּוֹם הַשְּׁמִינִי? אֶלָּא כָּתוּב, וּמִפֶּתַח אֹהֶל מוֹעֵד וְגוֹ', כִּי שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם. כִּי שִׁבְעַת?! בְּשִׁבְעַת יָמִים הָיָה צָרִיךְ לִהְיוֹת, אוֹ שִׁבְעָה יָמִים יְמַלֵּא אֶת יֶדְכֶם. מַה זֶּה כִּי שִׁבְעַת יָמִים יְמַלֵּא?</p>\n<p>אֶלָּא אַשְׁרֵי הַכֹּהֲנִים שֶׁמִּתְעַטְּרִים בַּעֲטֶרֶת הַמֶּלֶךְ הַקָּדוֹשׁ וּמְשׁוּחִים בְּשֶׁמֶן מִשְׁחַת קֹדֶשׁ, מִשּׁוּם שֶׁמִּתְעוֹרֵר הַשֶּׁמֶן (האחר) הָעֶלְיוֹן שֶׁמַּשְׁקֶה אֶת כָּל הַשִּׁבְעָה, וְנִמְשָׁחִים מֵאוֹתוֹ מִשְׁחַת קֹדֶשׁ, וְנִדְלָקִים מִמֶּנּוּ כָּל אוֹתָם שִׁבְעָה מְנוֹרוֹת, וְשֶׁמֶן הַמִּשְׁחָה הַזֶּה הוּא הַכְּלָל שֶׁל כָּל הַשִּׁבְעָה, וְכֻלָּם נִכְלְלוּ בוֹ.</p>\n<p>וְשָׁנִינוּ שֶׁהֵם שִׁשָּׁה, וְכֻלָּם כְּלוּלִים בָּזֶה, וְזֶהוּ הַכְּלָל שֶׁל כֻּלָּם, וּמִשּׁוּם כָּךְ שִׁבְעַת יָמִים יְמַלֵּא, שֶׁהֲרֵי בָּזֶה הֵם תְּלוּיִים. וְעַל כֵּן נִקְרֵאת כְּנֶסֶת יִשְׂרָאֵל בַּת שֶׁבַע. מַה הִיא בַּת שֶׁבַע? שֶׁהִיא כְּלוּלָה מִשִּׁשָּׁה אֲחֵ רִים.</p>\n<p>כֵּיוָן שֶׁהַשִּׁבְעָה הַזֶּה מַשְׁלִים אֶת הַכֹּהֲנִים וּמְעַטֵּר אוֹתָם וּמוֹשֵׁחַ אוֹתָם בַּכֹּל, כְּשֶׁמַּגִּיעִים לִכְנֶסֶת יִשְׂרָאֵל, שֶׁהִיא הַשְּׁמִינִית, הִצְטַוָּה אַהֲרֹן לְהַקְרִיב עֵגֶל, מִשּׁוּם שֶׁהוּא בְּנָהּ שֶׁל הַפָּרָה, לְכַפֵּר עַל אוֹתוֹ חֵטְא הָעֵגֶל הָאַחֵר שֶׁעָשָׂה אַהֲרֹן, וְחָטָא אֶל הַפָּרָה, שֶׁהִיא שְׁמִינִית, שְׁלֵמוּתָם שֶׁל מְמֻנֵּי (של אמוני) יִשְׂרָאֵל. וְנִמְצָא הַכֹּהֵן שָׁלֵם בַּכֹּל, בִּשְׁמוֹנָה מִינֵי לְבוּשֵׁי כָבוֹד, שָׁלֵם בְּכָל הַכְּתָרִים, שָׁלֵם לְמַעְלָה, שָׁלֵם לְמַטָּה.</p>\n<p>וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה. וְלָכֵן נַעֲשָׂה בְּאַהֲרֹן הַמַּעֲשֶׂה לְמַטָּה, כְּדֵי שֶׁיִּתְעוֹרֵר כָּךְ לְמַעְלָה וְהַכֹּל יִמָּצֵא בְּגָוֶן אֶחָד, וְאָז כָּל הָעוֹלָמוֹת מִתְבָּרְכִים, וְנִמְצָאוֹת בְּרָכוֹת עַל יְדֵי הַכֹּהֵן. וְכָאן מִשְׁתַּלֵּם הַכֹּהֵן בַּכֹּל כָּרָאוּי.</p>\n<p>לָמָּה עֵגֶל, שֶׁכָּתוּב עֵגֶל בֶּן בָּקָר לְחַטָּאת? מִשּׁוּם אוֹתָהּ הַחַטָּאת שֶׁעָשָׂה בָרִאשׁוֹנָה. וְאַיִל לְעֹלָה, מָה הַטַּעַם אַיִל? מִשּׁוּם אֵילוֹ שֶׁל יִצְחָק, שֶׁהָיָה עוֹלָה תְמִימָה, וְאֶת זֶה רָאוּי לְהַקְרִיב, כְּדֵי לְהַשְׁלִים אֶת הַכֹּל. וְהַמָּקוֹם הַזֶּה נִשְׁאָב מִצִּדּוֹ שֶׁל יִצְחָק. וְהָאַיִל הַזֶּה, בִּשְׁבִיל הָאַיִל שֶׁל יִצְחָק נִקְרָב עוֹלָה, (משום שהיא עולה) שֶׁהֲרֵי עוֹלָה לְמַעְלָה עוֹלָה, וּכְדֵי לְעַטֵּר אוֹתָהּ בִּשְׁלֵמוּת. עֵגֶל וְאַיִל. עֵגֶל בִּשְׁבִילָהּ כְּמוֹ שֶׁאָמַרְנוּ. אַיִל - לְהַשְׁלִים אוֹתָהּ בִּשְׁלֵמוּת שֶׁל יִצְחָק כָּרָאוּי.</p>\n<p>וְיִשְׂרָאֵל שֶׁחָטְאוּ עִם הַכֹּהֵן בָּזֶה, מַקְרִיב כְּגוֹן זֶה, שֶׁכָּתוּב וְשׁוֹר וְאַיִל לִשְׁלָמִים לִזְבּחַ לִפְנֵי ה'. שׁוֹר - עַל מַה שֶּׁחָטְאוּ. וְאַיִל - לְהַשְׁלִים אֶת הַמָּקוֹם הַזֶּה בִּשְׁלֵמוּתוֹ שֶׁל יִצְחָק.</p>\n<p>מַה שּׁוֹנֶה בְּכֹהֵן שֶׁכָּתוּב בּוֹ עֵגֶל לְחַטָּאת, וְלֹא כָתוּב בְּיִשְׂרָאֵל שׁוֹר לְחַטָּאת? אֶלָּא יִשְׂרָאֵל הֲרֵי קִבְּלוּ עֹנֶשׁ בָּרִאשׁוֹנָה, וּמִשּׁוּם שֶׁקִּבְּלוּ עֹנֶשׁ בְּכַמָּה מְקוֹמוֹת, עַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רָצָה לְהַזְכִּיר לָהֶם אֶת חֲטָאֵיהֶם כְּבָרִאשׁוֹנָה, וְעַל כֵּן לֹא כָתוּב כָּאן לְחַטָּאת, אֶלָּא לִשְׁלָמִים, כְּדֵי לְהַרְאוֹת שָׁלוֹם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשָׁלוֹם עִם יִשְׂרָאֵל עַל זֶה.</p>\n<p>אֲבָל אַהֲרֹן, שֶׁהֲרֵי לֹא קִבֵּל עֹנֶשׁ מִתְּפִלָּתוֹ שֶׁל מֹשֶׁה, שֶׁכָּתוּב (דברים ט) וּבְאַהֲרֹן הִתְאַנַּף ה' וְגוֹ', וְכָתוּב וָאֶתְפַּלֵּל גַּם בְּעַד אַהֲרֹן בָּעֵת הַהִיא, וְעַד עַכְשָׁו הַחֵטְא הָיָה תָלוּי, כָּתוּב וְעֵגֶל בֶּן בָּקָר לְחַטָּאת, לְחַטָּאת וַדַּאי, (ואיל לעלה) כְּדֵי שֶׁיְּכַפֵּר אֶת חֶטְאוֹ, וְיִטְהַר וְיִשְׁתַּלֵּם בַּכֹּל.</p>\n<p>וּבְאוֹתוֹ הַיּוֹם נִשְׁלְמוּ הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְנִמְצָא שָׁלוֹם בַּכֹּל, בְּשִׂמְחָה שֶׁלְּמַטָּה וּמַטָּה, וְאִלְמָלֵא שֶׁנִּמְצֵאת הָעִרְבּוּבְיָה שֶׁל בְּנֵי אַהֲרֹן בְּאוֹתוֹ הַיּוֹם - מִיּוֹם שֶׁעָלוּ יִשְׂרָאֵל מִן הַיָּם לֹא נִמְצְאָה שִׂמְחָה בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים כִּבְאוֹתוֹ הַיּוֹם. בְּאוֹתוֹ הַיּוֹם הָעֳבַר אוֹתוֹ הַחֵטְא מִן הָעוֹלָם, וְנִמְצְאוּ כֹהֵן וְיִשְׂרָאֵל מְטֹהָרִים מִמֶּנּוּ. (כל) אוֹתוֹ הַיּוֹם הָעָבְרוּ כָּל אוֹתָם הַמְקַטְרְגִים שֶׁלְּמַעְלָה, וְהָיוּ הוֹלְכִים וּמְשׁוֹטְטִים סְבִיבָם שֶׁל יִשְׂרָאֵל, וְלֹא נִמְצְאוּ בְּאוֹתוֹ זְמַן.</p>\n<p>עַד שֶׁגָּרְמָה הַשָּׁעָה, וְקָמוּ נָדָב וַאֲבִיהוּא וְעִכְּבוּ (וערבבו) אֶת שִׂמְחַת הַכֹּל, וְנִמְצָא רֹגֶז בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיֵּרָא כְבוֹד ה' אֶל כָּל הָעָם. מִיָּד - וַיִּקְחוּ (שני) בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא אִישׁ מַחְתָּתוֹ וְגוֹ'.</p>\n<p>שָׁנִינוּ, בְּאוֹתוֹ הַיּוֹם הָיְתָה שִׂמְחָתָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל לְהִקָּשֵׁר בְּקֶשֶׁר הָאֱמוּנָה בְּכָל הַקְּשָׁרִים הַקְּדוֹשִׁים, שֶׁהֲרֵי קְטֹרֶת קוֹשֶׁרֶת הַכֹּל כְּאֶחָד, וּמִשּׁוּם כָּךְ נִקְרֵאת קְטֹרֶת. וְהֵם בָּאוּ וְקָשְׁרוּ אֶת כָּל אוֹתָם הָאֲחֵרִים כְּאֶחָד, וְהִשְׁאִירוּ אוֹתָהּ בַּחוּץ, שֶׁלֹּא קָשְׁרוּ אוֹתָהּ עִמָּם. וְקָשְׁרוּ דָּבָר אַחֵר. וּמִשּׁוּם כָּךְ הִזְהִיר אַחַר כָּךְ אֶת הַכֹּהֲנִים, שֶׁכָּתוּב (ויקרא טז) בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ.</p>\n<p>וּבְכַמָּה גְוָנִים עִרְבְּבוּ אֶת שִׂמְחָתָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל, אֶחָד - שֶׁלֹּא נִשְּׂאוּ, וְלֹא רְאוּיִים הָיוּ לְהַקְרִיב, וְשֶׁיִּתְבָּרְכוּ הָעוֹלָמוֹת עַל יָדָם. וְאֶחָד - שֶׁלֹּא הָיְתָה הַשָּׁעָה כָּרָאוּי. וְאֶחָד - שֶׁדָּחֲקוּ אֶת הַשָּׁעָה. וְאֶחָד - שֶׁהֲרֵי מִקֹּדֶם לָכֵן יָצָא גְזַר דִּינָם, וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה וְגוֹ'. וַדַּאי שֶׁדָּבָר אַחֵר קָשְׁרוּ בַּקֶּשֶׁר הַזֶּה, וְהִשְׁאִירוּ אֶת כְּנֶסֶת יִשְׂרָאֵל בַּחוּץ. אָמַר לוֹ רַבִּי פִּנְחָס, אַל תֹּאמַר שֶׁהֵם הִשְׁאִירוּ אוֹתָהּ בַּחוּץ, אֶלָּא שֶׁכְּנֶסֶת יִשְׂרָאֵל לֹא נִקְשְׁרָה עַל יְדֵיהֶם. שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁאֵין נִמְצָא זָכָר וּנְקֵבָה, כְּנֶסֶת לֹא שׁוֹרָה בֵינֵיהֶם כְּלָל. מִשּׁוּם כָּךְ הִזְהִיר אֶת הַכֹּהֲנִים, שֶׁכָּתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. וְעַל כֵּן לֹא יִכָּנֵס הַכֹּהֵן לַקֹּדֶשׁ עַד שֶׁיִּנָּשֵׂא, כְּדֵי שֶׁיִּשְׁתַּתֵּף עִם הַקֶּשֶׁר שֶׁל כְּנֶסֶת יִשְׂרָאֵל. שֶׁמִּי שֶׁלֹּא נִשָּׂא, מַשְׁרֶה אֶת כְּנֶסֶת יִשְׂרָאֵל בַּחוּץ, וְהִיא לֹא מִשְׁתַּתֶּפֶת עִמּוֹ, וְעַל כֵּן נִמְצְאָה אֶצְלָם בְּאוֹתוֹ יוֹם עִרְבּוּבְיָה. וַיְהִי בַּיּוֹם הַשְּׁמִינִי. רַבִּי יוֹסֵי פָּתַח וְאָמַר, (שיר ב) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים כֵּן רַעְיָתִי בֵּין הַבָּנוֹת. כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים - זוֹ כְּנֶסֶת יִשְׂרָאֵל, וַהֲרֵי פֵּרְשׁוּהָ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל, וַחֲבִיבוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּנֶגְדָּהּ לְהִדָּבֵק בָּהּ.</p>\n<p>וְעַל כֵּן, מִי שֶׁנּוֹשֵׂא, צָרִיךְ לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי שָׁנִינוּ, בַּכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה, כְּמוֹ שֶׁאָדָם נִדְבָּק עִם בַּת זוּגוֹ וַחֲבִיבוּתוֹ כְּנֶגְדָּהּ, כְּשֶׁבָּא לַעֲבֹד לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, הוּא מְעוֹרֵר זִוּוּג אַחֵר, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, חֲבִיבוּתוֹ לְהִדָּבֵק בִּכְנֶסֶת יִשְׂרָאֵל, וּמִי שֶׁמְּעוֹרֵר הַדָּבָר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אוֹתוֹ, וּכְנֶסֶת יִשְׂרָאֵל מְבָרֶכֶת אוֹתוֹ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>וְעַל כֵּן הַשֶּׁבַח שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל - כְּשׁוֹשַׁנָּה שֶׁהִיא בֵּין הַחוֹחִים, שֶׁהִיא מְעֻלָּה וְעוֹלָה עַל הַכֹּל. כָּךְ כְּנֶסֶת יִשְׂרָאֵל בֵּין שְׁאָר הָאוּכְלוּסִים, מִשּׁוּם שֶׁהִיא עוֹלָה וּמִתְעַטֶּרֶת עַל הַכֹּל. וְזוֹ שׁוֹשַׁנָּה בֵּין הַחוֹחִים, וְאֶתְרוֹג בֵּין הַחוֹחִים, לְהַרְאוֹת אֶת שִׁבְחָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל עַל הַכֹּל.</p>\n<p>בֹּא רְאֵה, כְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת עַל יְדֵי הַכֹּהֵן, וְיִשְׂרָאֵל מִתְבָּרְכִים עַל יְדֵי הַכֹּהֵן, וְהַכֹּהֵן מִתְבָּרֵךְ עַל יְדֵי הַכֹּהֵן הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב (במדבר ו) וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרֲכֵם.</p>\n<p>כָּתוּב (תהלים כה) זְכֹר רַחֲמֶיךְ ה' וַחֲסָדֶיךְ כִּי מֵעוֹלָם הֵמָּה. זְכֹר רַחֲמֶיךְ - זֶה יַעֲקֹב. וַחֲסָדֶיךְ - זֶה אַבְרָהָם. כִּי מֵעוֹלָם הֵמָּה, וּמֵעוֹלָם נָטַל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְהֶעֱלָה אוֹתָם לְמַעְלָה, וְעָשָׂה מֵהֶם מֶרְכָּבָה קְדוֹשָׁה לְהָגֵן עַל הָעוֹלָם. וּמִשּׁוּם שֶׁהָיוּ מֵעוֹלָם, הוּא זוֹכֵר אוֹתָם לְהָגֵן וּלְרַחֵם עַל הָעוֹלָם. כְּמוֹ כֵן נוֹטֵל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַצַּדִּיקִים מִן הָעוֹלָם וּמַעֲלֶה אוֹתָם לְמַעְלָה, כְּדֵי לְהָגֵן עַל הָעוֹלָם.</p>\n<p>וְאִם תֹּאמַר, לָמָּה לֹא נִזְכַּר כָּאן יִצְחָק? אֶלָּא נִשְׁאָר לְהִפָּרַע מֵאוֹתָם שֶׁמְּצִיקִים לְבָנָיו. זֶהוּ שֶׁכָּתוּב (שם פ) עוֹרְרָה אֶת גְּבוּרָתֶךְ. וְכָתוּב (ישעיה מב) ה' כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה וְגוֹ'. וְזֶהוּ יִצְחָק שֶׁהִסְתַּלֵּק מִכָּאן. רַבִּי חִיָּיא אוֹמֵר, זְכֹר רַחֲמֶיךְ ה' וַחֲסָדֶיךְ - אֵלּוּ הֵם יַעֲקֹב וְאַבְרָהָם, שֶׁצְּרִיכִים אוֹתָם לְהָגֵן עָלֵינוּ. אֲבָל יִצְחָק עוֹמֵד כְּדֵי לַעֲשׂוֹת קְרָבוֹת, וּמִשּׁוּם כָּךְ לֹא צְרִיכִים אוֹתוֹ עִמָּם.</p>\n<p>דָּבָר אַחֵר כִּי מֵעוֹלָם הֵמָּה, שֶׁכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, נָטַל אֶת יִצְחָק וְקִיֵּם בּוֹ אֶת הָעוֹלָם. רָאָה שֶׁלֹּא יָכוֹל לַעֲמֹד לְבַדּוֹ, נָטַל אֶת אַבְרָהָם וְהֶעֱמִיד בּוֹ אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (בראשית מב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, אַל תִּקְרֵי בְּהִבָּרְאָם אֶלָּא בְּאַבְרָהָם. רָאָה שֶׁצְּרִיכִים יוֹתֵר קִיּוּם, לָקַח אֶת יַעֲקֹב וְשִׁתֵּף אוֹתוֹ עִם יִצְחָק, וְקִיֵּם אֶת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמַיִם. וְעַל זֶה בְּאַבְרָהָם וְיַעֲקֹב הִתְקַיֵּם הָעוֹלָם. וּמִשּׁוּם כָּךְ - כִּי מֵעוֹלָם הֵמָּה.</p>\n<p>רַבִּי יְהוּדָה פָּתַח, וַיְהִי בַּיּוֹם הַשְּׁמִינִי, אַחַר שֶׁהִשְׁתַּלֵּם אַהֲרֹן בְּאוֹתָם שִׁבְעָה יָמִים וְהִתְעַטֵּר בָּהֶם, (באותו שמן משחת קדש עליון) הַיּוֹם הַשְּׁמִינִי צָרִיךְ לְהִשְׁתַּלֵּם מִן שִׁבְעָה, שֶׁהַהַשְׁלָמָה עַל יְדֵי הַכֹּהֵן, וְעַל זֶה הָעֲבוֹדָה בַּשְּׁמִינִי, לְהִתְעַטֵּר מִן שִׁבְעָה, וְשֶׁהַכֹּהֵן יִתְתַּקֵּן עַל אוֹתוֹ (חטא) שֶׁחָטָא (שקבל) בָּרִאשׁוֹנָה.</p>\n<p>זְהִוּ שֶׁכָּתוּב, וַיֹּאמֶר אֶל אַהֲרֹן קַח לְךְ עֵגֶל, הֲרֵי פֵּרְשׁוּהָ עֵגֶל וַדָּאי, לְכַפֵּר עַל אוֹתוֹ עֵגֶל, שֶׁכָּתוּב (שמות לב) וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה. בֶּן בָּקָר, מָה הַטַּעַם בֶּן בָּקָר וְלֹא בֶּן פָּרָה? אֶלָּא שֶׁהוּא צָרִיךְ לְהִתְתַּקֵּן אֵצֶל הַפָּרָה, לֹא רָאוּי לְהַקְרִיב מִמֶּנָּה אֵלֶיהָ. מִי שֶׁשָּׁלַח דּוֹרוֹן לַמֶּלֶךְ, רְאִיתֶם שֶׁיִּקַּח מִבֵּית הַמֶּלֶךְ וְיִתֵּן לַמֶּלֶךְ?! אֶלָּא דוֹרוֹן לִשְׁלֹחַ לַמֶּלֶךְ צָרִיךְ מִבַּיִת אַחֵר, וְלֹא מִבֵּית הַמֶּלֶךְ. רַבִּי יוֹסֵי אָמַר, מִשֶּׁלּוֹ לְשֶׁלּוֹ לֹא רָאוּי. אָמַר רַבִּי יְהוּדָה, מִשּׁוּם כָּךְ בֶּן בָּקָר וַדַּאי, וְלֹא בֶּן פָּרָה.</p>\n<p>לְחַטָאת - לְטַהֵר עַל אוֹתוֹ הַחֵטְא שֶׁחָטָא בּוֹ. וְאַיִל לְעֹלָה תְּמִימִם. תְּמִימִם?! תָּמִים הָיָה צָרִיךְ לִהְיוֹת! אִם תֹּאמַר שֶׁאָמַר עַל עַיִל וְעֵגֶל - לֹא כָּךְ, שֶׁהֲרֵי שְׁנֵיהֶם לֹא עוֹלִים לְעוֹלָה, שֶׁהֲרֵי כָּתוּב לְעֹלָה תְּמִימִם, וְעֵגֶל עוֹלֶה לְחַטָּאת. מַה זֶּה תְּמִימִם, וְכָתוּב אַיִל?</p>\n<p>אֶלָּא אֵילוֹ שֶׁל יִצְחָק לְהַקְרִיב אֶל פָּרָה, שֶׁנִּזְכָּר פַּעֲמַיִם בַּכָּתוּב. אֶחָד שֶׁכָּתוּב, (בראשית כב) וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל, הֲרֵי אֶחָד. וְאֶחָד, וַיֵּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל, הֲרֵי שְׁנַיִם, וַיַּעֲלֵהוּ לְעֹלָה. וְעַל כֵּן אַיִל לְעֹלָה תְּמִימִם, שְׁנֵי אַיִל, שֶׁהוּא שְׁנַיִם. וְעַל כֵּן שָׁנִינוּ גְּבוּרוֹת, וּמֵהֶם נִפְרָדִים לְכַמָּה אֲחֵרִים.</p>\n<p>וְאֶל בְּנֵי יִשְׂרָאֵל תְּדַבֵּר לֵאמֹר קְחוּ שְׂעִיר עִזִּים לְחַטָּאת. עֵגֶל לְחַטָּאת הָיָה צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁהַכֹּהֵן. אֶלָּא יִשְׂרָאֵל הֲרֵי קִבְּלוּ עֹנֶשׁ, וְעַל כֵּן לֹא כָתוּב בָּהֶם עֵגֶל לְחַטָּאת, אֶלָּא עֵגֶל לְעוֹלָה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל אֵלּוּ שֶׁחָטְאוּ בוֹ, קִבְּלוּ עֹנֶשׁ, בֵּין בְּדִבּוּר, בֵּין בְּמַעֲשֶׂה, בֵּין בַּעֲבוֹדָה. וַאֲפִלּוּ אֵלּוּ שֶׁלֹּא עָשׂוּ דָבָר, אֶלָּא שֶׁהֶעֱלוּהוּ בִּרְצוֹן לִבָּם לַעֲבֹד אוֹתוֹ, נֶעֶנְשׁוּ, כְּמוֹ שֶׁכָּתוּב (שמות לב) וַיַּשְׁק אֶת בְּנֵי יִשְׂרָאֵל. אֲבָל כָּל אֵלּוּ שֶׁהֶעֱלוּ אוֹתוֹ בְרָצוֹן שֶׁלֹּא לַעֲבֹד אוֹתוֹ, אֶלָּא שֶׁהֶעֱלוּ גָוֶן שֶׁל רָצוֹן מִמֶּנּוּ - כָּאן נִטְהָרִים, וּמַקְרִיבִים אוֹתוֹ לְעוֹלָה וְלֹא לְחַטָּאת.</p>\n<p>אֲבָל קְחוּ שְׂעִיר עִזִּים לְחַטָּאת, לָמָּה? אֶלָּא מִשּׁוּם שֶׁהָיוּ מַקְרִיבִים רִאשׁוֹנָה לַשְּׂעִירִים, שֶׁשּׁוֹלְטִים עַל הֶהָרִים הָרָמִים. וְזֶהוּ לְחַטָּאת. וּצְרִיכִים לְהִטָּהֵר מֵאוֹתוֹ הַחֵטְא, וְלֹא עוֹד, אֶלָּא שֶׁצָּרִיךְ לְחִדּוּשׁ הַלְּבָנָה.</p>\n<p>וְשׁוֹר וְאַיִל לִשְׁלָמִים, שׁוֹר וְלֹא פַּר, מִשּׁוּם שֶׁשּׁוֹר הוּא שָׁלֵם, לְהַרְאוֹת שָׁלוֹם, זֶהוּ שֶׁכָּתוּב לִשְׁלָמִים. רַבִּי יוֹסֵי אָמַר, שׁוֹר וְאַיִל מִצַּד הַשְּׂמֹאל הֵם בָּאִים. שׁוֹר מִצַּד הַשְּׂמֹאל, שֶׁכָּתוּב (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אַיִל, מִשּׁוּם אֵילוֹ שֶׁל יִצְחָק. וְעוֹלִים לִשְׁלָמִים, לְהַשְׁלִים אותָם לִכְנֶסֶת יִשְׂרָאֵל, וְעַל כֵּן שׁוֹר וְאַיִל לִשְׁלָמִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הַכֹּל מִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְעַטֶּרֶת וּמִתְבָּרֶכֶת עַל יְדֵי הַכֹּהֵן בִּשְׁלֵמוּת. וְהַיּוֹם הַזֶּה הָיָה שִׂמְחָתָם שֶׁל כֻּלָּם, שִׂמְחָתָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שִׂמְחַת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וּכְמוֹ שֶׁהִשְׁתַּלֵּם הַכֹּהֵן לְמַטָּה, כִּבְיָכוֹל נִשְׁתַּלֵּם הַכֹּהֵן לְמַעְלָה. רַק שֶׁנָּדָב וַאֲבִיהוּ שֶׁעוֹרְרוּ עִרְבּוּבְיָה בֵּין הַגְּבִירָה וְהַמֶּלֶךְ. וּמִשּׁוּם כָּךְ - וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אֹתָם וְגוֹ'.</p>\n<p>וַיֹּאמֶר מֹשֶׁה אֶל אֶלְעָזָר וְאֶל אִיתָמָר רָאשֵׁיכֶם אַל תִּפְרָעוּ וְגוֹ', כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם. רַבִּי אַבָּא אָמַר, הֲרֵי שָׁנִינוּ שֶׁבַּמַּעֲשִׂים שֶׁלְּמַטָּה מִתְעוֹרְרִים מַעֲשִׂים לְמַעְלָה, וְהַמַּעֲשֶׂה שֶׁלְּמַטָּה צָרִיךְ לְהֵרָאוֹת כְּמוֹ הַמַּעֲשֶׂה שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה, כָּל הַשִּׂמְחָה שֶׁלְּמַעְלָה תְּלוּיָה בְּאוֹתוֹ שֶׁמֶן קָדוֹשׁ, שֶׁמִּשָּׁם יוֹצְאוֹת שִׂמְחָה וּבְרָכוֹת לְכָל הַמְּאוֹרוֹת, וְהַכֹּהֵן הָעֶלְיוֹן (ממנו) מִתְעַטֵּר בְּשֶׁפַע שֶׁל שֶׁמֶן. וּמִשּׁוּם כָּךְ הַכֹּהֵן, שֶׁשֶּׁמֶן מִשְׁחָה שׁוֹפֵעַ עָלָיו כְּמוֹ שֶׁלְּמַעְלָה, צָרִיךְ לְהַרְאוֹת שִׂמְחָה וְהֶאָרַת פָּנִים (יותר מהכל), וְשֶׁלֹּא יֵרָאֶה חִסָּרוֹן בְּרֹאשׁוֹ וְלֹא בִלְבוּשׁוֹ, אֶלָּא לִהְיוֹת הַכֹּל שָׁלֵם כְּמוֹ שֶׁלְּמַעְלָה, וְאַל יֵרָאֶה בּוֹ פְּגָם כְּלָל, כְּדֵי שֶׁלֹּא יַעֲשֶׂה פְגָם בְּמָקוֹם אַחֵר.</p>\n<p>בֹּא רְאֵה, אִלְמָלֵא אֶלְעָזָר וְאִיתָמָר הֶרְאוּ פְגָם בְּאוֹתָהּ שָׁעָה בִּלְבוּשָׁם אוֹ בְרָאשֵׁיהֶם, לֹא נִצּוֹלוּ בְּאוֹתָהּ שָׁעָה, שֶׁהֲרֵי הַשָּׁעָה עָמְדָה לַעֲשׂוֹת דִּין. וְעַל כֵּן שָׁנִינוּ, בְּשָׁעָה שֶׁהַמַּגֵּפָה קוֹרֵאת בָּעוֹלָם, לֹא יְעוֹרֵר אָדָם אֶת עַצְמוֹ לְדָבָר בָּעוֹלָם, כְּדֵי שֶׁלֹּא יִתְעוֹרְרוּ עָלָיו. פְּרָט אִם עוֹרֵר אֶת עַצְמוֹ לְטוֹב, וְיָכוֹל לִדְחוֹת (לדחק) אֶת הַשָּׁעָה, שֶׁהֲרֵי בִּזְמַן וּבְשָׁעָה שֶׁהַדִּין עוֹמֵד בָּעוֹלָם, מִי שֶׁפּוֹגֵעַ בּוֹ, לוֹקְטִים אוֹתוֹ וּמִסְתַּלֵּק מִן הָעוֹלָם. וּמִשּׁוּם כָּךְ כָּתוּב וְלֹא תָמוּתוּ. וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה, מִשּׁוּם שֶׁהֵם לֹא בָאִים מִצַּד הַכֹּהֲנִים, וְלֹא יִנָּזְקוּ.</p>"],[9522012026,"<p>רַבִּי אֶלְעָזָר פָּתַח, (שמות ו) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עַמִּינָדָב אֲחוֹת נַחְשׁוֹן לוֹ לְאִשָּׁה. וַיִּקַּח אַהֲרֹן. הַכֹּל כְּמוֹ שֶׁצָּרִיךְ, הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. בֹּא וּרְאֵה, רְאוּיָה הָיְתָה בַּת שֶׁבַע לְדָוִד מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם. רְאוּיָה הָיְתָה אֱלִישֶׁבַע לְאַהֲרֹן מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא הַכֹּל אֶחָד. אֲבָל שָׁם לְדִין, וְכָאן לְרַחֲמִים. כְּשֶׁהִתְחַבְּרָה עִם דָּוִד - זֶה לְדִין, לַעֲרֹךְ קְרָבוֹת וְלִשְׁפֹּךְ דָּמִים. כָּאן בְּאַהֲרֹן - לְשָׁלוֹם, לְשִׂמְחָה, לְהֶאָרַת פָּנִים, לְהִתְבָּרֵךְ. וְעַל כֵּן נִקְרֵאת (כך) שָׁם בַּת שֶׁבַע, וְכָאן אֱלִישֶׁבַע. אֱלִישֶׁבַע - שֶׁהִתְחַבְּרָה עִם חֶסֶד. (בא ראה) בַּת שֶׁבַע לְדִין, לָרֶשֶׁת מַלְכוּת וּלְהִתְגַּבֵּר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, זֶה שֶׁשָּׁנִינוּ שֶׁכָּתוּב קוֹל הַשּׁוֹפָר - יָפֶה הוּא, וְזֶהוּ יַעֲקֹב, שֶׁעָלָה בַמַּחֲשָׁבָה שֶׁל הָאָבוֹת, וְיָצְאוּ כְאֶחָד מִתּוֹךְ שׁוֹפָר, שֶׁהֲרֵי שׁוֹפָר מוֹצִיא מַיִם וְאֵשׁ וְרוּחַ כְּאֶחָד, וְנַעֲשֶׂה מֵהֶם קוֹל. כָּךְ הָאֵם הָעֶלְיוֹנָה מוֹצִיאָה אֶת הָאָבוֹת בְּקוֹל אֶחָד, וּמִתּוֹךְ מַחֲשָׁבָה הִתְעַלּוּ כְאֶחָד בְּקוֹל אֶחָד, וְאוֹתוֹ קוֹל נִקְרָא קוֹל הַשּׁוֹפָר, וְזֶה יַעֲקֹב שֶׁכּוֹלֵל אֶת הָאָבוֹת כְּאֶחָד, וְנִקְרָא קוֹל.</p>\n<p>וּשְׁנֵי קוֹלוֹת הֵם, שֶׁהֲרֵי מִתּוֹךְ קוֹל יוֹצֵא קוֹל. אֲבָל קוֹל אֶחָד שֶׁנִּקְרָא קוֹל הַשּׁוֹפָר, וּמִכָּאן יָצְאוּ שְׁאָר הַקּוֹלוֹת מִתּוֹךְ אוֹתוֹ הַשּׁוֹפָר בְּזִוּוּג שֶׁל הַמַּחֲשָׁבָה. וְשִׁבְעָה קוֹלוֹת הֵם שֶׁיּוֹצְאִים בְּזִוּוּג שֶׁל הַמַּחֲשָׁבָה עִם הַשּׁוֹפָר, וְהַשּׁוֹפָר הַזֶּה שֶׁמַּשְׁקֶה אוֹתָם וּמַרְוֶה אֶת הָאָבוֹת בָּרִאשׁוֹנָה, וְאַחַר כָּךְ אֶת הַבָּנִים, וַהֲרֵי בֵּאֲרוּ אֶת הַדָּבָר.</p>\n<p>בֹּא רְאֵה, וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע, לְבַסֵּם אוֹתָהּ, לְשַׂמֵּחַ אוֹתָהּ וּלְחַבֵּר אוֹתָהּ עִם הַמֶּלֶךְ בְּזִוּוּג שָׁלֵם, שֶׁיִּמָּצְאוּ בְרָכוֹת לְכָל הָעוֹלָמוֹת עַל יְדֵי אַהֲרֹן. מִשּׁוּם כָּךְ צָרִיךְ הַכֹּהֵן לְהִמָּצֵא בְּהֶאָרַת פָּנִים, בְּשִׂמְחָה, הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, שֶׁהֲרֵי עַל יָדוֹ בְּרָכוֹת וּשְׂמָחוֹת נִמְצָאוֹת. וְלָכֵן מְרֻחָקִים מִמֶּנּוּ דִּין וְרֹגֶז וְעֶצֶב, כְּדֵי שֶׁלֹּא יִפָּגֵם מֵאוֹתוֹ מָקוֹם שֶׁנִּקְשָׁר בּוֹ. וְעַל זֶה - וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה, וְלֹא הַכֹּהֵן. עֲלֵיהֶם כָּתוּב (דברים לג) בָּרֵךְ ה' חֵילוֹ וּפֹעַל יָדָיו תִּרְצֶה וְגוֹ'.</p>"],[9522012027,"<p>יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךְ אִתָּךְ וְגוֹ'. אָמַר רַבִּי יְהוּדָה, מִתּוֹךְ הַפָּרָשָׁה הַזּוֹ שׁוֹמְעִים, שֶׁנָּדָב וַאֲבִיהוּא הָיוּ שְׁתוּיֵי יַיִן, מִשֶּׁהִזְהִיר בָּזֶה אֶת הַכֹּהֲנִים. רַבִּי חִיָּיא פָּתַח, (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ וְגוֹ'. אִם צָרִיךְ הַכֹּהֵן לִשְׂמֹחַ וּלְהִמָּצֵא בְּהֶאָרַת פָּנִים יוֹתֵר מֵהַכֹּל, לָמָּה אָסוּר לוֹ יַיִן? שֶׁהֲרֵי שִׂמְחָה נִמְצֵאת בּוֹ, וְהֶאָרַת פָּנִים נִמְצֵאת בּוֹ?</p>\n<p>אֶלָּא רֵאשִׁיתוֹ שֶׁל יַיִן שִׂמְחָה, וְסוֹפוֹ עַצְבוּת. וְעוֹד, שֶׁיַּיִן בָּא מִצַּד הַלְוִיִּם, מֵהַמָּקוֹם שֶׁיַּיִן שׁוֹרֶה, שֶׁהֲרֵי תּוֹרָה וְיֵינָהּ שֶׁל תּוֹרָה הֵם מִצַּד הַגְּבוּרָה. (סופועצבות, והכהן תחלה וסיום צריך שמחה והארת פנים. יין בא מצד הלוים) וְצַד הַכֹּהֵן מַיִם צְלוּלִים מְאִירִים.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כָּל אֶחָד מַלְוֶה לַחֲבֵרוֹ, וְהַכֹּל כָּלוּל זֶה בָּזֶה. וּמִשּׁוּם כָּךְ יַיִן מַשְׁרֶה שִׂמְחָה, מִשּׁוּם שֶׁכָּלוּל מִתּוֹךְ מַיִם, וְאַחַר כָּךְ חוזֵר לִמְקומו, וְעָצוּב וְרוגֵז וְדָן דִּין. (והכהן תחלה וסיום צריך שמחה והארת פנים).</p>\n<p>רַבִּי אַבָּא אָמַר, מִמָּקוֹם אֶחָד יָצְאוּ - יַיִן וְשֶׁמֶן וּמַיִם (דבש וחלב). מַיִם וְשֶׁמֶן לְיָמִין, נוֹטְלִים הַכֹּהֲנִים וְיוֹרְשִׁים אוֹתָם, וְשֶׁמֶן יוֹתֵר מֵהַכֹּל, שֶׁהוּא שִׂמְחָה רֵאשִׁית וְסִיּוּם, שֶׁכָּתוּב (שם קלג) כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן זְקַן אַהֲרֹן. וְיַיִן לִשְׂמֹאל, יוֹרְשִׁים הַלְוִיִּם, לְהָרִים קוֹל וּלְזַמֵּר, וְלֹא לִשְׁתֹּק, שֶׁהֲרֵי יַיִן לֹא שׁוֹתֵק לְעוֹלָמִים, וְשֶׁמֶן הוּא תָּמִיד בַּחֲשַׁאי.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא שֶׁמֶן שֶׁהוּא בַּחֲשַׁאי, בְּלַחַשׁ תָּמִיד, בָּא מִצַּד הַמַּחֲשָׁבָה, שֶׁהִיא תָּמִיד בְּלַחַשׁ וְלֹא נִשְׁמַעַת, וְהוּא בַּחֲשַׁאי, וְעַל כֵּן הוּא מִיָּמִין. וְיַיִן שֶׁהוּא לְהָרִים קוֹל, וְלֹא שׁוֹתֵק לְעוֹלָמִים, בָּא מִצַּד הָאֵם, וְיוֹרְשִׁים הַלְוִיִּם לְצַד הַשְּׂמֹאל, וְעוֹמְדִים לְזַמֵּר לְהָרִים קוֹל, וְעוֹמְדִים בְּדִין. וּמִשּׁוּם כָּךְ כָּתוּב, (דברים כא) וְעַל פִּיהֶם יִהְיֶה כָּל רִיב וְכָל נָגַע.</p>\n<p>מִשּׁוּם כָּךְ, כְּשֶׁכֹּהֵן יִכָּנֵס לַמִּקְדָּשׁ כְּדֵי לַעֲבֹד אֶת הָעֲבוֹדָה, אָסוּר לוֹ לִשְׁתּוֹת יַיִן, שֶׁהֲרֵי מַעֲשָׂיו הֵם בַּחֲשַׁאי, וּבַחֲשַׁאי (נראה) הֵם בָּאִים, וּמִתְכַּוֵּן, (ובחשאי מתכון במה שמתכון) וּמְזַוֵּג אֶת מִי שֶׁמְּזַוֵּג, וּמַשְׁפִּיעַ בְּרָכוֹת לְכָל הָעוֹלָמוֹת, וְהַכֹּל בַּחֲשַׁאי, (ועוד) שֶׁכָּל מַעֲשָׂיו בְּסוֹד. וְיַיִן הוּא מְגַלֶּה רָזִים, שֶׁהֲרֵי כָּל מַעֲשָׂיו עוֹמְדִים כְּדֵי לְהָרִים קוֹל.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ מִבֵּית מֵרוֹן לְצִפּוֹרִי, וְהָיָה עֶלֶם אֶחָד מָצוּי בְּתוֹכָם (אצלם) עִם יַיִן רָקוּחַ בִּדְבַשׁ. אָמַר רַבִּי יְהוּדָה, נֹאמַר דְּבַר תּוֹרָה וְנֵלֵךְ.</p>\n<p>פָּתַח רַבִּי יִצְחָק וְאָמַר, (שירז) וְחִכֵּךְ כְּיֵין הַטּוֹב הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים וְגוֹ'. וְחִכֵּךְ כְּיֵין הַטּוֹב - זֶה יֵינָהּ שֶׁל תּוֹרָה, שֶׁהוּא טוֹב. שֶׁהֲרֵי יַיִן אַחֵר אֵינוֹ טוֹב, וְיֵינָהּ שֶׁל תּוֹרָה טוֹב לַכֹּל. טוֹב לָעוֹלָם הַזֶּה, וְטוֹב לָעוֹלָם הַבָּא. וְזֶהוּ הַיַּיִן שֶׁנּוֹחַ לוֹ לַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר מֵהַכֹּל, וּבִזְכוּת זֶה, מִי שֶׁנִּרְוֶה מִיֵּינָהּ שֶׁל הַתּוֹרָה, יִתְעוֹרֵר לָעוֹלָם הַבָּא, וְיִזְכֶּה לְהֵחָיוֹת כְּשֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַצַּדִּיקִים. אָמַר רַבִּי יְהוּדָה, דּוֹבֵב שִׂפְתֵי יְשֵׁנִים, הֲרֵי שָׁנִינוּ, שֶׁאֲפִלּוּ בְּאוֹתוֹ עוֹלָם יִזְכֶּה לַעֲסֹק בַּתּוֹרָה. זֶהוּ שֶׁכָּתוּב דּוֹבֵב שִׂפְתֵי יְשֵׁנִים.</p>\n<p>אָמַר אוֹתוֹ עֶלֶם, אִם כָּתוּב וְחִכֵּךְ מִיֵּין הַטּוֹב, הָיִינוּ אוֹמְרִים כָּךְ. אֲבָל כָּתוּב כְּיֵין הַטּוֹב, וְלֹא מִיֵּין. הִשְׁגִּיחוּ בוֹ. אָמַר רַבִּי יְהוּדָה, בְּנִי, אֱמֹר דְּבָרְךְ, שֶׁיָּפֶה אָמַרְתָּ.</p>\n<p>אָמַר, אֲנִי שָׁמַעְתִּי, שֶׁמִּי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְדָבֵק בָּהּ, וְאוֹתוֹ דְּבַר הַתּוֹרָה נִשְׁמָע בְּפִיו וְלֹא לוֹחֵשׁ אוֹתוֹ בְּלַחַשׁ, אֶלָּא מֵרִים בּוֹ אֶת קוֹלוֹ, שֶׁכָּךְ צְרִיכָה תּוֹרָה לַהֲרָמַת קוֹל, שֶׁכָּתוּב (משלי א) בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא, לְהָרִים אֶת רִנַּת הַתּוֹרָה, וְלֹא בְּלַחַשׁ. כְּיֵין הַטּוֹב, כְּמוֹ יַיִן טוֹב שֶׁלֹּא שׁוֹתֵק. וְהוּא עָתִיד לְהָרִים קוֹל, כְּשֶׁיֵּצֵא מִן הָעוֹלָם הַזֶּה. הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים, שֶׁלֹּא יִסְטֶה לְיָמִין וְלִשְׂמֹאל, לֹא יִמָּצֵא שֶׁיִּמְחֶה בְיָדוֹ. דּוֹבֵב שִׂפְתֵי יְשֵׁנִים, וַאֲפִלּוּ בְּאוֹתוֹ עוֹלָם שִׂפְתוֹתָיו מְרַחֲשׁוֹת בַּתּוֹרָה.</p>\n<p>עוֹד שָׁמַעְתִּי, וְחִכֵּךְ כְּיֵין הַטּוֹב - הַפָּסוּק הַזֶּה נֶאֱמַר לִכְנֶסֶת יִשְׂרָאֵל, וְנֶאֱמַר בְּתִשְׁבַּחַת. אִם כָּךְ, מִי הוּא שֶׁמְּשַׁבֵּחַ אוֹתָהּ בָּזֶה? אִם הַקָּדוֹשׁ בָּרוּךְ הוּא - מַה זֶּה הוֹלֵךְ לְדוֹדִי? הוֹלֵךְ אֵלַי הָיָה צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שֶׁהִיא מְשַׁבַּחַת אוֹתוֹ, שֶׁכָּתוּב חִכּוֹ מַמְתַּקִּים, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל. (שכתוב) וְחִכֵּךְ כְּיֵין הַטּוֹב. יֵין הַטּוֹב - שֶׁהוּא יַיִן הַמְשֻׁמָּר. הוֹלֵךְ לְדוֹדִי - זֶה יִצְחָק שֶׁנִּקְרָא יְדִיד מִבֶּטֶן. לְמֵישָׁרִים - כְּמוֹ שֶׁנֶּאֱמַר (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים, לְהַכְלִיל שְׂמֹאל בְּיָמִין. וְזֶהוּ מֵישָׁרִים, שֶׁבִּגְלַל הַשִּׂמְחָה שֶׁל אוֹתוֹ הַיַּיִן הַטּוֹב, נִכְלָל הַשְּׂמֹאל בַּיָּמִין, וְכֻלָּם שְׂמֵחִים. (דובב שפתי ישנים) שֶׁהֲרֵי הַכֹּל מִתְעוֹרְרִים בִּשְׂמָחוֹת וּבְרָכוֹת, וְכָל הָעוֹלָמוֹת נִמְצָאִים בְּשִׂמְחָה, וּמִתְעוֹרְרִים לְהָרִיק בְּרָכוֹת לְמַטָּה.</p>\n<p>בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְנָשְׁקוּ לוֹ אֶת רֹאשׁוֹ, וְשָׂמְחוּ עִמּוֹ. אָמְרוּ לוֹ, מַה שְּׁמֶךְ? אָמַר לוֹ, יֵיסָא. אָמְרוּ, רַבִּי יֵיסָא תִּהְיֶה. יוֹתֵר תִּהְיֶה מָצוּי בָּעוֹלָם מֵרַבִּי יֵיסָא חֲבֵרֵנוּ, שֶׁהִסְתַּלֵּק מִבֵּינֵינוּ. אָמְרוּ לוֹ, וּמִי אָבִיךְ? אָמַר לוֹ, נִפְטַר מִן הָעוֹלָם, וְהָיָה מְלַמֵּד אוֹתִי כָּל יוֹם שְׁלֹשָׁה דִּבְרֵי תוֹרָה, וּבַלַּיְלָה שְׁלֹשָׁה דִּבְרֵי חָכְמָה שֶׁל אַגָּדָה. וְהַדְּבָרִים הַלָּלוּ לָמַדְתִּי מֵאָבִי, וְכָעֵת אֲנִי גָּר עִם אָדָם אֶחָד שֶׁמּוֹנֵעַ אוֹתִי מִן הַתּוֹרָה, וַאֲנִי הוֹלֵךְ כָּל יוֹם לָעֲבוֹדָה, וּבְכָל יוֹם אֲנִי חוֹזֵר עַל אוֹתָם הַדְּבָרִים שֶׁלָּמַדְתִּי מֵאָבִי.</p>\n<p>אָמְרוּ לוֹ, אוֹתוֹ אָדָם יוֹדֵעַ בַּתּוֹרָה? אָמַר לָהֶם, לֹא, הוּא זָקֵן, וְלֹא יוֹדֵעַ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיֵשׁ לוֹ בָּנִים, וְלֹא שָׂם אוֹתָם בְּבֵית הָרַב. אָמַר רַבִּי יְהוּדָה, (אם לא כך היה) אִם לֹא הָיָה כָּךְ, הָיִיתִי נִכְנָס לַכְּפָר הַזֶּה לְדַבֵּר עָלֶיךְ. עַכְשָׁו אָסוּר לָנוּ לִרְאוֹת אֶת פָּנָיו, זְרֹק מִמְּךְ אֶת הַחֲמוֹר, וְאַתָּה לֵךְ אֵלֵינוּ. אָמְרוּ לוֹ, מִי אָבִיךְ? אָמַר, רַבִּי זְעֵירָא מִכְּפָר רָאמִין.</p>\n<p>שָׁמַע רַבִּי יְהוּדָה וּבָכָה. אָמַר, אֲנִי הָיִיתִי בְּבֵיתוֹ, וְלָמַדְתִּי מִמֶּנּוּ שְׁלֹשָׁה דְבָרִים בְּכוֹס שֶׁל בְּרָכָה, וְלָמַדְתִּי מִמֶּנּוּ שְׁנַיִם בְּמַעֲשֵׂה בְרֵאשִׁית. אָמַר רַבִּי יִצְחָק, וּמָה מֵהַיֶּלֶד הַזֶּה בְּנוֹ לָמַדְתִּי, מִמֶּנּוּ לֹא כָּל שֶׁכֵּן? הָלְכוּ וְאָחֲזוּ בְיָדוֹ. רָאוּ שָׂדֶה אֶחָד וְיָשְׁבוּ שָׁם. אָמְרוּ לוֹ, אֱמֹר דָּבָר אֶחָד מֵאוֹתָם שֶׁלִּמֵּד אוֹתְךְ אָבִיךְ בְּמַעֲשֵׂה בְרֵאשִׁית.</p>"],[9522012028,"<p>פָּתַח וְאָמַר, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים וְגוֹ'. וַיִּבְרָא אֱלֹהִים - כָּל מָקוֹם שֶׁל דִּין נִקְרָא אֱלֹהִים. וְאוֹתוֹ מָקוֹם עֶלְיוֹן, הַמָּקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ, כָּךְ קוֹרֵא לוֹ כָּאן. וְאַף עַל גַּב שֶׁהוּא רַחֲמִים, יוֹצְאִים מִמֶּנּוּ דִּינִים, וּבוֹ הֵם תְּלוּיִים.</p>\n<p>אֶת הַתַּנִּינִם הַגְּדלִים - אֵלּוּ הָאָבוֹת, שֶׁהֵם מֻשְׁקִים בָּרִאשׁוֹנָה וּמִשְׁתָּרְשִׁים עַל הַכֹּל. וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת. וְאֵת כָּל נֶפֶשׁ הַחַיָּה - זוֹ הַנֶּפֶשׁ, שֶׁאוֹתָהּ הָאָרֶץ הָעֶלְיוֹנָה הוֹצִיאָה מֵאוֹתָהּ חַיָּה עֶלְיוֹנָה עַל הַכֹּל, שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. וְזוֹהִי הַנֶּפֶשׁ שֶׁל אָדָם הָרִאשׁוֹן שֶׁמָּשַׁךְ בְּתוֹכוֹ. הָרֹמֶשֶׂת - זוֹהִי הָרוֹחֶשֶׁת בְּכָל הֶהָרִים (הצדדים) לְמַעְלָה וּלְמַטָּה. אֲשֶׁר שָׁרְצוּ הַמַּיִם, שֶׁאוֹתוֹ נָהָר עֶלְיוֹן שׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וּמַשְׁקֶה אֶת הָעֵץ הַזֶּה לְהִשְׁתָּרֵשׁ בְּשָׁרָשָׁיו עַל הַכֹּל, וְשֶׁיִּמָּצֵא בּוֹ מָזוֹן לַכֹּל.</p>\n<p>דָּבָר אַחֵר הַחַיָּה הָרֹמֶשֶׂת - זֶהוּ דָּוִד הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (תהלים קיח) לֹא אָמוּת כִּי אֶחְיֶה וְגוֹ'. וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ - אֵלּוּ כָּל אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁמְּצוּיִים לְקַדֵּשׁ אֶת שֵׁם אֲדוֹנָם בְּכָל יוֹם וָיוֹם, שֶׁכָּתוּב בָּהֶם שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד. וּמֵהֶם טָסִים בָּעוֹלָם לַעֲשׂוֹת רְצוֹן רִבּוֹנָם, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. אָמַר רַבִּי יְהוּדָה, וַדַּאי כָּל כָּךְ לַיֶּלֶד הַזֶּה לֹא רָאוּי, אֲבָל אֲנִי רוֹאֶה בּוֹ שֶׁיַּעֲלֶה לְמָקוֹם עֶלְיוֹן.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי הַחַיָּה (הרמשת) זוֹהִי הַחַיָּה הָעֶלְיוֹנָה עַל הַכֹּל, שֶׁהֲרֵי הָאַחֶרֶת, הַכָּתוּב קָרָא לָהּ אֶרֶץ. כָּאן שֶׁכָּתוּב וְהָעוֹף יִרֶב בָּאָרֶץ, בָּאָרֶץ וַדַּאי, וְלֹא בַמַּיִם. שֶׁהֲרֵי אוֹתוֹ נָהָר שׁוֹפֵעַ וְיוֹצֵא וּמַשְׁקֶה בְּלִי פֵרוּד, עַד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֶרֶץ, וּמִשָּׁם כָּתוּב וּמִשָּׁם יִפָּרֵד וְגוֹ'. וְהָעוֹף, וְאוֹתוֹ עוֹף, בָּאָרֶץ הַזּוֹ תְּלוּיִים וּמֻשְׁקִים, וְזֶהוּ שֶׁכָּתוּב וְהָעוֹף יִרֶב בָּאָרֶץ. קָמוּ וְהָלְכוּ. אָמַר רַבִּי יְהוּדָה, נְשַׁתֵּף אֶת הַיֶּלֶד הַזֶּה עִמָּנוּ, וְכָל אֶחָד וְאֶחָד יֹאמַר דְּבַר תּוֹרָה.</p>"],[9522012029,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, סַמְּכוּנִי בָּאֲשִׁישׁוֹת רַפְּדוּנִי בַּתַּפּוּחִים וְגוֹ'. הַפָּסוּק הַזֶּה הֲרֵי נִתְבָּאֵר, וְיָפֶה. אֲבָל כְּנֶסֶת יִשְׂרָאֵל אָמְרָה אֶת זֶה בַּגָּלוּת. סַמְּכוּנִי, מַה זֶּה סַמְּכוּנִי? אֶלָּא מִי שֶׁנּוֹפֵל צָרִיךְ לִסְמֹךְ אוֹתוֹ, זֶהוּ שֶׁכָּתוּב (תהלים קמה) סוֹמֵךְ ה' לְכָל הַנּוֹפְלִים וְגוֹ'. וּמִשּׁוּם כָּךְ, כְּנֶסֶת יִשְׂרָאֵל שֶׁנָּפְלָה, שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם, צְרִיכָה לִסְמִיכָה, וְהִיא אוֹמֶרֶת סַמְּכוּנִי. לְמִי הִיא אוֹמֶרֶת? לְיִשְׂרָאֵל בָּנֶיהָ, שֶׁהֵם עִמָּהּ בַּגָּלוּת.</p>\n<p>וּבַמֶּה, ? בָּאֲשִׁישׁוֹת. אֵלּוּ הֵם הָאָבוֹת שֶׁמִּתְמַלְּאִים בָּרִאשׁוֹנָה מֵאוֹתוֹ יַיִן טוֹב הַמְשֻׁמָּר. וּכְשֶׁהֵם מִתְמַלְּאִים, הֲרֵי הַבְּרָכוֹת מְצוּיוֹת אֵלֶיהָ עַל יְדֵי דַרְגָּה אַחַת שֶׁהִיא צַדִּיק. וּמִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, אַף עַל גַּב שֶׁבְּרָכוֹת לֹא מְצוּיוֹת בָּעוֹלָם, הוּא סוֹמֵךְ וְסוֹעֵד אֶת כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת.</p>\n<p>רַפְּדוּנִי בַּתַּפּוּחִים, הַכֹּל אֶחָד כְּמוֹ שֶׁאָמַרְנוּ. אֲבָל הַסּוֹד הַזֶּה, אֲשִׁישָׁה - מַכְנִיסָה יַיִן. תַּפּוּחַ - מוֹצִיא יַיִן, וּמְכַוֵּן רָצוֹן. וְעַל כֵּן אֲשִׁישׁוֹת וְתַפּוּחִים. אֲשִׁישׁוֹת, לִרְווֹת מִיַּיִן. תַּפּוּחִים, לְכַוֵּן אֶת הָרָצוֹן שֶׁהַיַּיִן לֹא יַזִּיק. וְכָל זֶה לָמָּה? כִּי חוֹלַת אַהֲבָה אָנִי, בַּגָּלוּת. וּמִי שֶׁמְּיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, צָרִיךְ לְיַחֵד דִּין עִם רַחֲמִים וּלְהַכְלִילָם כָּרָאוּי, שֶׁיִּתְבַּשֵּׂם וְיִתְתַּקֵּן הַכֹּל כָּרָאוּי, וְזֶה הַתּוֹמֵךְ אֶת כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת.</p>"],[9522012030,"<p>רַבִּי יִצְחָק פָּתַח, (דברים לב) אֲשֶׁר חֵלֶב זְבָחֵימוֹ יֹאכֵלוּ יִשְׁתּוּ יֵין נְסִיכָם. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהֵם קְדוֹשִׁים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְקַדֵּשׁ אוֹתָם. בֹּא רְאֵה, יִשְׂרָאֵל קְדוֹשִׁים, כָּל חַיֵּי עוֹלָם שֶׁיּוֹרְשִׁים, הַכֹּל תְּלוּיִים בְּאוֹתוֹ הָעוֹלָם הַבָּא, מִשּׁוּם שֶׁהוּא חַיִּים שֶׁל הַכֹּל, לְמַעְלָה וּלְמַטָּה, וְהוּא הַמָּקוֹם שֶׁהַיַּיִן הַמְשֻׁמָּר מַתְחִיל (ונקרא יין), וּמִשָּׁם יוֹצְאִים חַיִּים וּקְדֻשָּׁה לַכֹּל. וְיַיִן שֶׁל יִשְׂרָאֵל בִּשְׁבִיל יַיִן שֶׁל יִשְׂרָאֵל אַחֵר, וְזֶה תָּלוּי בָּזֶה. שֶׁהֲרֵי יִשְׂרָאֵל לְמַעְלָה, בּוֹ נוֹטֵל חַיִּים, וּמִשּׁוּם כָּךְ נִקְרָא עֵץ חַיִּים, עֵץ מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא חַיִּים, וְיוֹצְאִים מִשָּׁם חַיִּים, וְעַל כֵּן מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַיִן. וְיַיִן שֶׁל יִשְׂרָאֵל לְמַטָּה כְּמוֹ כֵן.</p>\n<p>עוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהוּא טָמֵא, וּמִי שֶׁקָּרֵב עִמּוֹ יִטְמָא כְּשֶׁיִּקְרַב לַיַּיִן שֶׁל יִשְׂרָאֵל, הֲרֵי נִטְמָא, וְאָסוּר. כָּל שֶׁכֵּן אוֹתוֹ הַיַּיִן שֶׁהוּא עוֹשֶׂה. וְלָכֵן אַל תֹּאמַר שֶׁזֶּה הוּא בִּלְבַדּוֹ, אֶלָּא כָּל מַה שֶּׁעוֹשִׂים יִשְׂרָאֵל לְמַטָּה, הַכֹּל הוּא כְּעֵין דֻּגְמָא שֶׁל מַעְלָה, כָּל שֶׁכֵּן יַיִן, שֶׁעוֹמֵד בְּמָקוֹם עֶלְיוֹן, דֻּגְמַת הַיַּיִן הַמְשֻׁמָּר.</p>\n<p>מִשּׁוּם כָּךְ יִשְׂרָאֵל שׁוֹתִים יַיִן שֶׁל יִשְׂרָאֵל שֶׁנַּעֲשָׂה כָּרָאוּי בִּקְדֻשָּׁה, כְּמוֹ שֶׁיִּשְׂרָאֵל לְמַעְלָה שֶׁשּׁוֹתֶה וְנִשְׁרָשׁ וּמִתְבָּרֵךְ בְּאוֹתוֹ יַיִן עֶלְיוֹן קָדוֹשׁ, וְלֹא שׁוֹתִים יַיִן שֶׁנַּעֲשָׂה בְטֻמְאָה וּמִצַּד הַטֻּמְאָה, שֶׁהֲרֵי בּוֹ שׁוֹרָה רוּחַ הַטֻּמְאָה (ואיננו מצד ישראל). וּמִי שֶׁשּׁוֹתֶה אוֹתוֹ (אתם), נִטְמֵאת רוּחוֹ, וְהוּא נִטְמָא, וְאֵינוֹ מִצַּד שֶׁל יִשְׂרָאֵל, וְאֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא, שֶׁהֲרֵי אוֹתוֹ עוֹלָם הַבָּא הוּא יַיִן הַמְשֻׁמָּר.</p>\n<p>וְעַל כֵּן יִשְׂרָאֵל קְדוֹשִׁים צְרִיכִים לִשְׁמֹר אֶת זֶה עַל הַכֹּל, מִשּׁוּם שֶׁנִּקְשָׁר בִּמְקוֹם הָעוֹלָם הַבָּא. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְבָּרֵךְ בְּיַיִן יוֹתֵר מֵאֲשֶׁר בַּכֹּל, מִשּׁוּם שֶׁהוּא מְשַׂמֵּחַ אֶת צַד הַשְּׂמֹאל, וּבְתוֹךְ שִׂמְחָתוֹ נִכְלָל בַּיָּמִין. וּכְשֶׁהַכֹּל נַעֲשֶׂה יָמִין, אָז הַשֵּׁם הַקָּדוֹשׁ בְּשִׂמְחָה, וּבְרָכוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת. וּבַמַּעֲשֶׂה שֶׁלְּמַטָּה יִתְעוֹרֵר מַעֲשֶׂה שֶׁלְּמַעְלָה, וְעַל כֵּן מַזְמִינִים יַיִן כְּנֶגֶד יַיִן.</p>\n<p>וּמִשּׁוּם שֶׁהוּא שָׁמוּר לְמַעְלָה, צָרִיךְ לִשְׁמֹר אוֹתוֹ לְמַטָּה, וְכָל שְׁמִירָתוֹ הִיא קְדֻשָּׁה לְיִשְׂרָאֵל, וּמִי שֶׁפּוֹגֵם אוֹתוֹ לְמַטָּה בְּצַד הַטֻּמְאָה, הוּא יִטְמָא בָּעוֹלָם הַזֶּה וְאֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא, הַמָּקוֹם שֶׁשּׁוֹרֶה אוֹתוֹ הַיַּיִן הַמְשֻׁמָּר. הוּא לֹא שָׁמַר אוֹתוֹ, הוּא לֹא יִשְׁתַּמֵּר לָעוֹלָם הַבָּא. הוּא טִמֵּא אוֹתוֹ, יְטַמְּאוּ אוֹתוֹ בְּאוֹתוֹ הָעוֹלָם, וְלֹא יִהְיֶה לוֹ חֵלֶק בְּאוֹתוֹ יַיִן שֶׁל הָעוֹלָם הַבָּא. אַשְׁרֵי יִשְׂרָאֵל שֶׁמְּקַדְּשִׁים אֶת נַפְשָׁם בִּקְדֻשָּׁה עֶלְיוֹנָה, וְשׁוֹמְרִים מַה שֶּׁצָּרִיךְ לִשְׁמֹר, וּמַקְדִּישִׁים אֶת הַמֶּלֶךְ בַּשְּׁמִירָה הָעֶלְיוֹנָה הַזּוֹ. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012031,"<p>פָּתַח אוֹתוֹ הַיֶּלֶד וְאָמַר, (משלי כט) מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ וְגוֹ'. מִי הַמֶּלֶךְ? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. בְּמִשְׁפָּט - זֶה יַעֲקֹב, שֶׁהוּא הַכְּלָל שֶׁל הָאָבוֹת. וְאִישׁ תְּרוּמוֹת, כָּתוּב תְּרוּמַת, כְּמוֹ שֶׁנֶּאֱמַר (שמות כה) וְזֹּאת הַתְּרוּמָה. וְאִישׁ תְּרוּמוֹת - זֶה עֵשָׂו, שֶׁשּׁוֹאֵל עַל תְּרוּמוֹת וּמַעַשְׂרוֹת כָּל יוֹם, וְלֹא עוֹשֶׂה דָבָר. וְאִישׁ תְּרוּמוֹת, שֶׁאֵינוֹ מִשְׁפָּט, שֶׁהֲרֵי תְּרוּמָה הִיא הִסְתַּלְּקוּת הָרַחֲמִים, מִשּׁוּם זֶה לֹא בָאָה בְּמִשְׁפָּט, כְּמוֹ שֶׁנֶּאֱמַר (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. וְעַל כֵּן, וְאִישׁ תְּרוּמוֹת יֶהֶרְסֶנָּה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי דָּוִד הַמֶּלֶךְ הָיָה אִישׁ תְּרוּמָה? אֶלָּא בְּרַחֲמִים. וְלֹא עוֹד, אֶלָּא (דוד המלך איש תרומה היה, והארץ התקימה בשבילו, כך הוא ודאי. אבל הכל ברחמים היה) שֶׁהֲרֵי כָּתוּב (ישעיה נה) חַסְדֵי דָוִד הַנֶּאֱמָנִים, כְּמוֹ שֶׁנִּדְבָּק בָּזֶה - נִדְבָּק בָּזֶה.</p>\n<p>בֹּא רְאֵה, כָּל יְמֵי דָוִד הַמֶּלֶךְ הָיָה מִשְׁתַּדֵּל (בשביל) שֶׁהַתְּרוּמָה הַזּוֹ תִּתְקַשֵּׁר לְמִשְׁפָּט וְיִזְדַּוְּגוּ כְּאֶחָד. (כדי שיתקים בארץ) בָּא שְׁלֹמֹה וְזִוֵּג אוֹתָם כְּאֶחָד, וְעָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת, וְעָמְדָה הָאָרֶץ בְּקִיּוּם. בָּא צִדְקִיָּהוּ וְהִפְרִיד אוֹתָם, וְנִשְׁאֲרָה הָאָרֶץ בְּלֹא מִשְׁפָּט, וְנִפְגְּמָה הַלְּבָנָה וְנֶחְרְבָה הָאָרֶץ, אָז וְאִישׁ תְּרוּמַת יֶהֶרְסֶנָּה.</p>"],[9522012032,"<p>וּבֹא רְאֵה, שֶׁמֶן לַכֹּהֲנִים, יַיִן לַלְוִיִּם, לֹא מִשּׁוּם שֶׁצְּרִיכִים יַיִן, אֶלָּא מִיַּיִן הַמְשֻׁמָּר שֶׁבָּא לַצַּד שֶׁלָּהֶם כְּדֵי לְחַבֵּר הַכֹּל כְּאֶחָד, וּלְשַׂמֵּחַ אֶת כָּל הָעוֹלָמוֹת שֶׁהַכֹּל יִמָּצֵא בָהֶם, יָמִין וּשְׂמֹאל כְּלוּלִים זֶה עִם זֶה, שֶׁיִּמָּצֵא בָהֶם חֲבִיבוּת לַכֹּל וְאַהֲבָה שֶׁל בְּנֵי הָאֱמוּנָה.</p>\n<p>מִי שֶׁרְצוֹנוֹ נִדְבָּק בָּזֶה, הוּא שָׁלֵם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְיִמָּצֵא כָּל יָמָיו שֶׁדָּבוּק בִּתְשׁוּבָה, הַמָּקוֹם שֶׁיַּיִן וְשֶׁמֶן מְצוּיִים. אָז לֹא יִדְבַּק אַחֲרֵי הָעוֹלָם הַזֶּה, לֹא לְעֹשֶׁר וְלֹא לַתְּשׁוּקָה שֶׁלּוֹ. וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ עַל כָּךְ וְאוֹמֵר, (משלי כא) אֹהֵב יַיִן וָשֶׁמֶן לֹא יַעֲשִׁיר, שֶׁהֲרֵי עֹשֶׁר אַחֵר יִזְדַּמֵּן לוֹ, שֶׁיִּהְיֶה לוֹ חֵלֶק בּוֹ וְלִהְיוֹת לוֹ חֵלֶק בָּעוֹלָם הַבָּא, הַמָּקוֹם שֶׁיַּיִן וְשֶׁמֶן שׁוֹרִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. מִי שֶׁאוֹהֵב אֶת הַמָּקוֹם הַזֶּה לֹא צָרִיךְ עֹשֶׁר וְלֹא רוֹדֵף אַחֲרָיו. אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בָּעֹשֶׁר הָעֶלְיוֹן כָּל יוֹם, שֶׁכָּתוּב (איוב כח) לֹא יַעַרְכֶנָּה זָהָב וּזְכוּכִית וּתְמוּרָתָהּ כְּלִי פָז. זֶה בָּעוֹלָם הַזֶּה. אַחַר כָּךְ, (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא.</p>"],[9522012033,"<p>עוֹד פָּתַח וְאָמַר, (שמות כד) וַיֹּאמֶר ה' אֶל מֹשֶׁה עֲלֵה אֵלַי הָהָרָה וְגוֹ'. וְהַתּוֹרָה - זוֹ תּוֹרָה שֶׁבִּכְתָב. וְהַמִּצְוָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. לְהוֹרֹתָם, כְּתִיב חָסֵר, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) וְאֶל חֶדֶר הוֹרָתִי. כָּאן יֵשׁ לְהִתְבּוֹנֵן, לְהוֹרֹתָם שֶׁל מִי? אִם תֹּאמַר הוֹרֹתָם שֶׁל יִשְׂרָאֵל - לֹא כָּךְ, שֶׁהֲרֵי יִשְׂרָאֵל לֹא נִזְכְּרוּ בַּכָּתוּב הַזֶּה. אֶלָּא הוֹרֹתָם שֶׁל תּוֹרָה וּמִצְווֹת, וּמַה הִיא? זֶהוּ (מקום) יַיִן הַמְשֻׁמָּר. מִשּׁוּם שֶׁכָּל כְּתִיבָה שֶׁל הַסֵּפֶר הָעֶלְיוֹן שָׁם שְׁרוּיָה, וּמִשָּׁם יָצְאָה תוֹרָה, וְעַל זֶה קוֹרְאִים תּוֹרָה שֶׁבִּכְתָב. וְזֶהוּ אֲשֶׁר כָּתַבְתִּי לְהוֹרֹתָם, לְהוֹרֹתָם וַדַּאי. (כמו שנאמר ואל חדר הורתי).</p>\n<p>תּוֹרָה שֶׁבְּעַל פֶּה, תּוֹרָה אַחֶרֶת שֶׁעוֹמֶדֶת עַל פֶּה. מַהוּ פֶּה? זֶהוּ דַעַת, שֶׁהִיא פֶּה שֶׁל סֵפֶר וּכְתִיבָה. וְתוֹרָה זוֹ הִיא תוֹרָה אַחֶרֶת, שֶׁנִּקְרֵאת תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהִיא עוֹמֶדֶת עַל אוֹתוֹ הַפֶּה שֶׁהוּא תוֹרָה שֶׁבִּכְתָב. מִשּׁוּם כָּךְ הִתְעַלָּה מֹשֶׁה בַּכֹּל, עַל כָּל הַנְּבִיאִים הַנֶּאֱמָנִים, שֶׁכָּתוּב וְאֶתְּנָה לְךְ, דַּוְקָא לְךְ.</p>"],[9522012034,"<p>כָּתוּב (משלי כה) הָגוֹ סִיגִים מִכָּסֶף וַיֵּצֵא לַצֹּרֵף כֶּלִי. הָגוֹ רָשָׁע לִפְנֵי מֶלֶךְ וְיִכּוֹן בַּחֶסֶד כִּסְאוֹ. בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, כִּסְאוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ נִתְקָן בְּדִין, וְנִטְמָא (ונשאב) (ועומד) בְּדִין, וְשַׁלְהֲבוֹתָיו שׂוֹרְפוֹת אֶת הָעוֹלָם. וּבְשָׁעָה שֶׁהָרְשָׁעִים עוֹבְרִים מִן הָעוֹלָם, אָז וְיִכּוֹן בַּחֶסֶד כִּסְאוֹ. בַּחֶסֶד וְלֹא בַדִּין. מַה מַּשְׁמָע?</p>\n<p>מַשְׁמִיעַ שֶׁהָעוֹלָם הַתַּחְתּוֹן תָּלוּי בָּעוֹלָם הָעֶלְיוֹן, וְהָעוֹלָם הָעֶלְיוֹן לְפִי דַרְכֵי הָעוֹלָם הַתַּחְתּוֹן. וְיִכּוֹן בַּחֶסֶד כִּסְאוֹ, מִי שֶׁרוֹצֶה לְבָרֵךְ אוֹתוֹ, לְהַתְקִין אֶת כִּסְאוֹ בְּחֶסֶד וְלֹא בְדִין. מַה מַּשְׁמָע? שֶׁכַּאֲשֶׁר נִכְנָס לְבֵית הַמִּקְדָּשׁ, שֶׁיִּכָּנֵס בְּחֶסֶד שֶׁהוּא מַיִם, וְלֹא יִכָּנֵס בַּיַּיִן שֶׁשּׁוֹתֶה, שֶׁהוּא גְבוּרָה. יִכָּנֵס בָּזֶה (דבר) בְּמַיִם, וְאַל יִכָּנֵס בְּיַיִן.</p>\n<p>בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְנָשְׁקוּ רֹאשׁוֹ, וּמֵאוֹתוֹ הַיּוֹם לֹא נִפְרָד מִבֵּית רַבִּי יְהוּדָה, וּכְשֶׁהָיָה נִכְנָס לְבֵית הַמִּדְרָשׁ, הָיָה עוֹמֵד רַבִּי יְהוּדָה לְפָנָיו. אָמַר, לָמַדְתִּי מִמֶּנּוּ דָבָר, וְרָאוּי לִנְהֹג בּוֹ כָּבוֹד. אַחַר כָּךְ הִתְעַלָּה בֵּין הַחֲבֵרִים, וְהָיוּ קוֹרְאִים לוֹ רַבִּי יֵיסָא, רֹאשׁ הַפַּטִּישׁ הַמְשַׁבֵּר סְלָעִים וּמוֹצִיא שַׁלְהָבוֹת לְכָל צַד. וְהָיָה רַבִּי אֶלְעָזָר קוֹרֵא עָלָיו, (ירמיה א) בְּטֶרֶם אֶצָּרְךְ בַּבֶּטֶן יְדַעְתִּיךְ.</p>"],[9522012035,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר אֲלֵיהֶם זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ וְגוֹ'. מַה שּׁוֹנֶה כָּאן אַהֲרֹן? אֶלָּא מִשּׁוּם שֶׁהוּא עוֹמֵד תָּמִיד לְהַפְרִיד בֵּין הַטָּמֵא וּבֵין הַטָּהוֹר, שֶׁכָּתוּב לְהַבְדִּיל בֵּין הַטָּמֵא וּבֵין הַטָּהוֹר.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים לד) מִי הָאִישׁ הֶחָפֵץ חַיִּים וְגוֹ', נְצֹר לְשׁוֹנְךְ מֵרָע וְגוֹ', סוּר מֵרָע וְגוֹ'. וְכָתוּב, (משלי כא) שֹׁמֵר פִּיו וּלְשׁוֹנוֹ וְגוֹ'. מִי הָאִישׁ הֶחָפֵץ חַיִּים, אֵיזֶה חַיִּים? אֶלָּא אֵלּוּ חַיִּים שֶׁנִּקְרָאִים הָעוֹלָם הַבָּא, וְהַחַיִּים שׁוֹרִים שָׁם. וְעַל כֵּן שָׁנִינוּ, עֵץ חַיִּים הוּא עֵץ מֵאוֹתָם הַחַיִּים, הָעֵץ שֶׁנָּטַע בְּאוֹתָם חַיִּים, וְעַל כֵּן כָּתוּב מִי הָאִישׁ הֶחָפֵץ חַיִּים.</p>\n<p>אוֹהֵב יָמִים לִרְאוֹת טוֹב, מִי הַיָּמִים? אֶלָּא זֶהוּ שְׁמוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁאוֹחֵז בְּאוֹתָם יָמִים עֶלְיוֹנִים, שֶׁנִּקְרְאוּ יְמֵי הַשָּׁמַיִם עַל הָאָרֶץ. יְמֵי הַשָּׁמַיִם וַדַּאי, עַל הָאָרֶץ וַדַּאי. מִי שֶׁרוֹצֶה חַיִּים שֶׁלְּמַעְלָה, שֶׁיִּהְיֶה לוֹ חֵלֶק בָּהֶם. וּמִי שֶׁרוֹצֶה יָמִים עֶלְיוֹנִים לְהִדָּבֵק בָּהֶם וְלֶאֱהֹב אוֹתָם - יִשְׁמֹר פִּיו מֵהַכֹּל, יִשְׁמֹר פִּיו וּלְשׁוֹנוֹ, וְיִשְׁמֹר פִּיו מִמַּאֲכָל וּמִשְׁתֶּה שֶׁמְּטַמְּאִים אֶת הַנֶּפֶשׁ וּמַרְחִיקִים אֶת הָאָדָם מֵאוֹתָם חַיִּים וּמֵאוֹתָם יָמִים, וְיִשְׁמֹר (פיו ולשונו) לְשׁוֹנוֹ מִדְּבָרִים רָעִים שֶׁלֹּא יִטָּמֵא בָהֶם, וְיִתְרַחֵק מֵהֶם, וְלֹא יִהְיֶה לוֹ חֵלֶק בָּהֶם.</p>\n<p>בֹּא רְאֵה, פֶּה וְלָשׁוֹן, כָּךְ נִקְרָא מָקוֹם (אחר) עֶלְיוֹן, וּמִשּׁוּם כָּךְ לֹא יִפְגֹּם אָדָם אֶת פִּיו וּלְשׁוֹנוֹ, וְכָל שֶׁכֵּן לְטַמֵּא אֶת נַפְשׁוֹ וְעַצְמוֹ, מִשּׁוּם שֶׁנִּטְמָא הוּא בָּעוֹלָם הָאַחֵר, וַהֲרֵי בֵּאַרְנוּ. זֹאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה וְגוֹ'. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ.</p>\n<p>זֹּאת הַחַיָּה, בַּהַתְחָלָה, וְאַחַר כָּךְ מִכָּל הַבְּהֵמָה? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּכָל זְמַן שֶׁיִּשְׂרָאֵל שׁוֹמְרִים עַל נַפְשָׁם וְאֶת עַצְמָם שֶׁלֹּא לְטַמֵּא אוֹתָם, וַדַּאי זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ, יִהְיוּ מְצוּיִים בִּקְדֻשָּׁה עֶלְיוֹנָה, לְהִדָּבֵק בִּשְׁמִי, בַּבְּחִירָה שֶׁל אוֹתָהּ בְּהֵמָה שֶׁבָּחַרְתִּי לָכֶם לֶאֱכֹל, אַל תִּטָּמְאוּ בָהֶם, וְתִהְיוּ דְבֵקִים בִּשְׁמִי.</p>\n<p>וְכָל זְמַן שֶׁאֵינָם שׁוֹמְרִים אֶת נַפְשָׁם וְאֶת עַצְמָם מִמַּאֲכָל וּמִשְׁתֶּה, הֵם יִדָּבְקוּ בְּמָקוֹם אַחֵר טָמֵא לְהִטָּמֵא בָהֶם. וּמִשּׁוּם כָּךְ כָּתוּב, זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל, מִכָּל וַדַּאי, שֶׁהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ לְהִדָּבֵק בּוֹ. מִכָּל הַבְּהֵמָה אֲשֶׁר עַל הָאָרֶץ, מִשּׁוּם שֶׁהָאֹכֶל שֶׁל הַבְּהֵמָה הַזּוֹ נִמְצָא טָהוֹר, וְלֹא יְטַמֵּא אֶתְכֶם, וְיִהְיֶה לָכֶם חֵלֶק בִּשְׁמִי לְהִדָּבֵק בּוֹ.</p>\n<p>וְעוֹד, זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ - בְּפַרְעֹה כָּתוּב (שמות ז) בְּזֹּאת תֵּדַע כִּי אֲנִי ה'. הֲרֵי זֹּאת כְּנֶגְדְּךְ, לְהִפָּרַע מִמְּךְ. אַף כָּאן זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה, הֲרֵי זֹּאת כְּנֶגְדְּכֶם לְהִפָּרַע מִכֶּם אִם תְּטַמְּאוּ אֶת נַפְשְׁכֶם. מָה הַטַּעַם? כִּי הַנְּפָשׁוֹת הֵן מִמֶּנָּה, וְאִם אַתֶּם תְּטַמְּאוּ אֶת אוֹתָהּ שֶׁלָּהּ, הֲרֵי זֹּאת כְּנֶגְדְּכֶם. אִם לְטוֹב - הִיא עוֹמֶדֶת אֲלֵיכֶם. וְאִם רַע - הִיא עוֹמֶדֶת אֲלֵיכֶם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, זֹּאת הַחַיָּה אֲשֶׁר תֹּאכְלוּ מִכָּל הַבְּהֵמָה, מִכָּל אוֹתָם הָאֲחוּזִים מֵהַצַּד הַזֶּה, מֻתָּר לָכֶם לֶאֱכֹל, וְכָל אוֹתָם שֶׁלֹּא בָאוֹת מִצַּד הַזֶּה, אָסוּר לָכֶם לֶאֱכֹל. מִשּׁוּם שֶׁיֵּשׁ בְּהֵמוֹת מִצַּד זֶה, וְיֵשׁ שֶׁבָּאוֹת מִצַּד אַחֵר הַטָּמֵא. וְהַסִּימָן שֶׁלָּהֶם - שֶׁכָּתוּב כֹּל מַפְרֶסֶת פַּרְסָה. וְלָמַדְנוּ שֶׁכֻּלָּם רְשׁוּמִים, וְאֶת כֻּלָּם רָשַׁם הַכָּתוּב. וּמִשּׁוּם כָּךְ, כָּל מִי שֶׁאוֹכֵל מֵאוֹתָם שֶׁבָּאִים מֵהַצַּד הַטָּמֵא הַזֶּה, הוּא נִטְמָא בָהֶם, וּמְטַמֵּא אֶת נַפְשׁוֹ שֶׁבָּאָה מִצַּד טָהוֹר.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כְּלָל שֶׁל הַכֹּל - כְּמוֹ שֶׁיֵּשׁ עֲשָׂרָה כְתָרִים שֶׁל אֱמוּנָה לְמַעְלָה, כָּךְ יֵשׁ עֲשָׂרָה כְתָרִים שֶׁל כְּשָׁפִים טְמֵאִים לְמַטָּה. וְכָל מַה שֶּׁבָּאָרֶץ, מֵהֶם אֲחוּזִים בַּצַּד הַזֶּה, וּמֵהֶם אֲחוּזִים בַּצַּד הַהוּא.</p>\n<p>וְאִם תֹּאמַר, וְהָעֵז הַזּוֹ, שֶׁשּׁוֹרָה עָלֶיהָ רוּחַ טֻמְאָה? לֹא כָּךְ. שֶׁאִם רוּחַ טֻמְאָה שׁוֹרָה בָּהּ, אָז אָסוּר לָנוּ לֶאֱכֹל. אֶלָּא שֶׁעוֹבְרִים בְּתוֹכָן וְנִרְאִים כְּנֶגְדָּן, וְלֹא שׁוֹרִים לָדוּר בָּהֶן, שֶׁכַּאֲשֶׁר הֵם שׁוֹרִים, רוּחַ אַחֶרֶת עוֹבֶרֶת עֲלֵיהֶן, וְנִפְרָדִים מֵעַצְמָן. וּמִשּׁוּם כָּךְ נִרְאוֹת כְּנֶגְדָּן וּמְקַטְרְגוֹת בְּתוֹכָן, וְלֹא שׁוֹלְטוֹת בְּעַצְמָן, וְלָכֵן מֻתָּר לָנוּ לֶאֱכֹל אוֹתָן.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁהֵן בָּאוֹת לִשְׁלֹט בָּהֶן, עוֹבֶרֶת רוּחַ אַחַת, זוֹקְפוֹת עֵינַיִם וְרוֹאוֹת אֶת רִשּׁוּמֵיהֶן וְנִפְרָדִים מֵהֶן, אֲבָל נִרְאִים כְּנֶגְדָּן, וְלֹא אֲסוּרִים לָנוּ לְמַאֲכָל.</p>\n<p>בֵּין בִּבְהֵמוֹת, בֵּין בְּחַיּוֹת, בֵּין בְּעוֹפוֹת, בֵּין דְּגֵי הַיָּם, בְּכֻלָּם נִרְאִים יָמִין וּשְׂמֹאל (רחמים ודין), וְאֶת כָּל מִי שֶׁבָּא מִצַּד הַיָּמִין (מצד הרחמים) מֻתָּר לָנוּ לְמַאֲכָל. וְכָל אוֹתָם שֶׁבָּאִים מִצַּד הַשְּׂמֹאל (מצד הדין), אֲסוּרִים כֻּלָּם לָנוּ לְמַאֲכָל, מִשּׁוּם שֶׁהַדַּרְגָּה (שעצם) שֶׁל כֻּלָּם טְמֵאָה, וְכֻלָּם טְמֵאִים, וְרוּחַ טֻמְאָה שְׁרוּיָה בְתוֹכָם וְגָרָה בָהֶם. וְלָכֵן רוּחַ הַקְּדוֹשָׁה שֶׁל יִשְׂרָאֵל לֹא תִתְעָרֵב בָּהֶם וְלֹא תִטָּמֵא בָהֶם, כְּדֵי שֶׁיִּמָּצְאוּ קְדוֹשִׁים וְיִוָּדְעוּ לְמַעְלָה וּלְמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ רוֹצֶה בָהֶם וְרוֹצֶה לְטַהֵר אוֹתָם וּלְקַדֵּשׁ אוֹתָם עַל הַכֹּל, מִשּׁוּם שֶׁהֵם אֲחוּזִים בּוֹ.</p>\n<p>בֹּא רְאֵה, כָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. אִם הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְפָּאֵר בְּיִשְׂרָאֵל, אֵיךְ בָּאִים לְהִטָּמֵא וּלְהִדָּבֵק בְּצַד הַטֻּמְאָה? וְעַל זֶה כָּתוּב וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אָנִי. וְלֹא (אל) תְשַׁקְּצוּ אֶת נַפְשּתֵיכֶם וְגוֹ'. מִי (שיושב) שֶׁהוּא בִּדְמוּת הַמֶּלֶךְ, לֹא צָרִיךְ לְהִפָּרֵד מִדַּרְכֵי הַמֶּלֶךְ, מִשּׁוּם כָּךְ רָשַׁם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל כָּל אוֹתָם שֶׁבָּאִים מִצַּד זֶה, וְכָל אוֹתָם שֶׁבָּאִים מִצַּד אַחֵר. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם (שם סא) כָּל רֹאֵיהֶם יַכִּירוּם כִּי הֵם זֶרַע בֵּרַךְ ה'. בֵּרַךְ ה' מַמָּשׁ, בֵּרַךְ ה' בַּכֹּל.</p>"],[9522012036,"<p>וּבֹא רְאֵה, כָּל מִי שֶׁאוֹכֵל מֵאוֹתָם מַאֲכָלִים אֲסוּרִים, נִדְבָּק בַּצַּד הָאַחֵר, וּמְתַעֵב נַפְשׁוֹ וְעַצְמוֹ, וְרוּחַ טְמֵאָה שׁוֹרָה עָלָיו, וּמַרְאֶה אֶת עַצְמוֹ שֶׁאֵין לוֹ חֵלֶק בָּאֱלוֹהַּ הָעֶלְיוֹן, וְלֹא בָא מֵהַצַּד שֶׁלּוֹ וְלֹא נִדְבַּק בּוֹ. וְאִם יָצָא כָּךְ מֵהָעוֹלָם הַזֶּה, אוֹחֲזִים בּוֹ כָּל אוֹתָם הָאֲחוּזִים בְּצַד (שבא מצד) הַטֻּמְאָה, וּמְטַמְּאִים אוֹתוֹ וְדָנִים אוֹתוֹ כְּאָדָם שֶׁהוּא נִתְעָב שֶׁל רִבּוֹנוֹ, נִתְעָב בָּעוֹלָם הַזֶּה וְנִתְעָב בָּעוֹלָם הַבָּא.</p>\n<p>וְעַל זֶה כָּתוּב וְנִטְמֵתֶם בָּם, בְּלִי א', שֶׁלֹּא נִמְצֵאת רְפוּאָה לְתוֹעַבְתּוֹ, וְלֹא יוֹצֵא מִטֻּמְאָתוֹ לְעוֹלָמִים. אוֹי לָהֶם! אוֹי לְנַפְשָׁם, שֶׁלֹּא יִדְבְּקוּ בִּצְרוֹר הַחַיִּים לְעוֹלָמִים, שֶׁהֲרֵי נִטְמְאוּ! אוֹי לְעַצְמָם! עֲלֵיהֶם כָּתוּב (ישעיה סו) כִּי תוֹלַעְתָּם לֹא תָמוּת וְגוֹ', וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַה זֶּה דֵּרָאוֹן? סִרְחוֹן. מִי גָרַם לוֹ? אוֹתוֹ הַצַּד שֶׁנִּדְבָּק בּוֹ.</p>\n<p>יִשְׂרָאֵל בָּאִים מִצַּד הַיָּמִין. אִם נִדְבָּקִים בְּצַד הַשְּׂמֹאל, הֲרֵי פּוֹגְמִים אֶת הַצַּד הַזֶּה, וּפוֹגְמִים אֶת עַצְמָם, וּפוֹגְמִים אֶת נַפְשָׁם, פְּגוּמִים בָּעוֹלָם הַזֶּה וּפְגוּמִים בָּעוֹלָם הַבָּא. כָּל שֶׁכֵּן מִי שֶׁנִּדְבָּק בְּצַד הַטֻּמְאָה, שֶׁהַכֹּל אָחוּז זֶה בָּזֶה, וְכָתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וְגוֹ'.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (קהלת ו) כָּל עֲמַל אָדָם לְפִיהוּ וְגוֹ'. הִסְתַּכַּלְתִּי בְּדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ, וְכֻלָּם אֲחוּזִים בְּחָכְמָה עֶלְיוֹנָה. כָּל עֲמַל אָדָם לְפִיהוּ, הַפָּסוּק הַזֶּה בְּשָׁעָה שֶׁדָּנִים אֶת הָאָדָם בְּאוֹתוֹ הָעוֹלָם כָּתוּב. כָּל אוֹתוֹ הַדִּין, וְכָל מַה שֶּׁסּוֹבֵל בְּאוֹתוֹ הָעוֹלָם וְנוֹקְמִים מִמֶּנּוּ נִקְמַת הָעוֹלָם - לְפִיהוּ, בִּשְׁבִיל פִּיהוּ שֶׁלֹּא שָׁמַר אוֹתוֹ וְטִמֵּא אוֹתוֹ אֶת נַפְשׁוֹ, וְלֹא נִדְבַּק לְצַד הַחַיִּים לְצַד הַיָּמִין. וְגַם הַנֶּפֶשׁ לֹא תִמָּלֵא, לֹא תִשְׁתַּלֵּם דִּינָהּ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. דָּבָר אַחֵר לֹא תִמָּלֵא, לֹא תִשְׁתַּלֵּם לַעֲלוֹת לִמְקוֹמָהּ לְעוֹלָמִים, מִשּׁוּם שֶׁהֲרֵי הִיא נִטְמְאָה וְנִדְבְּקָה לַצַּד הָאַחֵר.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּל מִי שֶׁנִּטְמָא בָהֶם, כְּאִלּוּ עָבַד לַעֲבוֹדָה זָרָה, שֶׁהִיא תּוֹעֲבַת ה', וְכָתוּב לֹא תֹאכַל כָּל תּוֹעֵבָה. מִי שֶׁעוֹבֵד לַעֲבוֹדָה זָרָה, יוֹצֵא מִצַּד הַחַיִּים, יוֹצֵא מֵרְשׁוּת הַקְּדֻשָּׁה וְנִכְנָס לְרָשׁוּת אַחֶרֶת. אַף מִי שֶׁנִּטְמָא בַּמַּאֲכָלוֹת הַלָּלוּ, יוֹצֵא מִצַּד הַחַיִּים, וְיוֹצֵא מֵרְשׁוּת הַקְּדֻשָּׁה וְנִכְנָס לְרָשׁוּת אַחֶרֶת. וְלֹא עוֹד, אֶלָּא שֶׁנִּטְמָא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְלָכֵן כָּתוּב וְנִטְמֵתֶם בָּם בְּלִי א'.</p>\n<p>וְכָתוּב (ויקרא כ) וְלֹא תְשַׁקְּצוּ אֶת נַפְשּתֵיכֶם בַּבְּהֵמָה וּבָעוֹף וּבְכֹל אֲשֶׁר תִּרְמֹשׂ הָאֲדָמָה אֲשֶׁר הִבְדַּלְתִּי לָכֶם לְטַמֵּא. מַה זֶּה לְטַמֵּא? לְטַמֵּא אֶת הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁהֲרֵי הֵם טְמֵאִים, וְהֵם בָּאִים מִצַּד הַטֻּמְאָה, וְכָל צַד נִדְבָּק בִּמְקוֹמוֹ.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, זֶה שֶׁשָּׁנִינוּ עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת יִשְׂרָאֵל, בַּמֶּה? אָמַר לוֹ, בְּמַה שֶּׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם וְגוֹ'. כֵּיוָן שֶׁנִּטְהָרִים מִתְקַדְּשִׁים, וְיִשְׂרָאֵל שֶׁנִּדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא נִקְרְאוּ קֹדֶשׁ, שֶׁכָּתוּב (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, וְכָתוּב (שמות כו) וְאַנְשֵׁי קֹדֶשׁ תִּהְיוּן לִי. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר עֲלֵיהֶם, (ויקרא כו) וִהְיִיתֶם לִי קְדשִׁים כִּי קָדוֹשׁ אֲנִי ה', מִשּׁוּם שֶׁכָּתוּב וּבוֹ תִדְבָּק, וְכָתוּב (תהלים קמז) לֹא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם הַלְלוּיָהּ.</p>"],[9522012037,"<p>דָּגִים וַחֲגָבִים אֵינָם טְעוּנִים שְׁחִיטָה, אֶלָּא אֲסִיפָתָם הִיא הַמַּתֶּרֶת אוֹתָם. כָּךְ מוֹרֵי הַיְשִׁיבָה, אֵין צְרִיכִים שְׁחִיטָה, אֶלָּא שֶׁנֶּאֱמַר בָּהֶם (בראשית מט) וַיִּגְוַע וַיֵּאָסֵף אֶל עַמָּיו. מַה דְּגֵי הַיָּם חִיּוּתָם בַּיָּם, אַף תַּלְמִידֵי חֲכָמִים בַּעֲלֵי הַמִּשְׁנָה חִיּוּתָם בַּתּוֹרָה, וְאִם נִפְרָדִים מִמֶּנָּה, מִיָּד מֵתִים. (תנאי) תַּנִּינֵי הַמִּשְׁנָה, שֶׁבָּהּ הִתְרַבּוּ כִּדְגֵי הַיָּם, וְאִם אֵלּוּ שֶׁבַּיַּבָּשָׁה יַעֲלוּ לַמַּיִם וְלֹא יוֹדְעִים לָשׁוּט, הֵם מֵתִים. אֲבָל אָדָם (שהם בעלי קבלה, הללו שלמעלה), שֶׁהוּא לְמַעְלָה מִכֻּלָּם, נֶאֱמַר בּוֹ (בראשית א) וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם.</p>\n<p>שֶׁאְוֹתָם מוֹרֵי הַמִּשְׁנָה, הַתַּנִּינִים, הַתַּנִּין הַגָּדוֹל, נָחָשׁ בָּרִיחַ, כְּנֶגֶד וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים, בִּזְמַן שֶׁהַתַּנִּינִים, בַּעֲלֵי הַמִּשְׁנָה, יֵשׁ מַחֲלֹקֶת וּמַקְשִׁים זֶה עַל זֶה, בּוֹלֵעַ אֶת חֲבֵרוֹ, וְזֶה תַּלְמִיד קָטָן שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה, חַיָּב מִיתָה. וְאִם הֵם שָׁוִים זֶה לָזֶה וְיֵשׁ בָּהֶם מַחֲלֹקֶת וְקֻשְׁיָה, נֶאֱמַר בָּהֶם (לבסוף) (במדבר כא) אֶת וָהֵב בְּסוּפָה, וּפֵרְשׁוּהָ - אַהֲבָה בְּסוֹפָהּ. (עד כאן רעיא מהימנא).</p>"],[9522012038,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר אִשָּׁה כִי תַזְרִיעַ וְיָלְדָה זָכָר וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (שיר ג) עַל מִשְׁכָּבִי בַּלֵּילוֹת בִּקַּשְׁתִּי וְגוֹ'. עַל מִשְׁכָּבִי?! בְּמִשְׁכָּבִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה עַל מִשְׁכָּבִי? אֶלָּא כְּנֶסֶת יִשְׂרָאֵל אָמְרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמְבַקֶּשֶׁת מִמֶּנּוּ עַל הַגָּלוּת, מִשּׁוּם שֶׁהִיא יוֹשֶׁבֶת בֵּין שְׁאָר הָעַמִּים עִם בָּנֶיהָ וְשׁוֹכֶבֶת לֶעָפָר. וְעַל שֶׁהִיא שׁוֹכֶבֶת בְּאֶרֶץ טְמֵאָה אַחֶרֶת, אוֹמֶרֶת: עַל מִשְׁכָּבִי אֲנִי מְבַקֶּשֶׁת, שֶׁאֲנִי כּוֹאֶבֶת (שוכבת) בַּגָּלוּת, וְעַל זֶה - בִּקַּשְׁתִּי אֵת שֶׁאָהֲבָה נַפְשִׁי, וּלְהוֹצִיא אוֹתִי מִמֶּנּוּ.</p>\n<p>בִּקַּשְׁתִּיו וְלֹא מְצָאתִיו, שֶׁאֵין דַּרְכּוֹ לְהִזְדַּוֵּג עִמִּי אֶלָא בְּהֵיכָלוֹ, קְרָאתִיו וְלֹא עָנָנִי. שֶׁהִנֵּה בֵּין עַמִּים אֲחֵרִים אֲנִי יוֹשֶׁבֶת, וְאֵין שׁוֹמְעִים אֶת קוֹלוֹ אֶלָּא בָּנָיו, שֶׁכָּתוּב (דברים ד) הֲשָׁמַע עָם קוֹל אֱלֹהִים וְגוֹ'.</p>\n<p>רַבִּי יִצְחָק אָמַר, עַל מִשְׁכָּבִי בַּלֵּילוֹת - אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, עַל מִשְׁכָּבִי הִתְרַעַמְתִּי לְפָנָיו, שֶׁהָיָה מִזְדַּוֵּג עִמִּי לְשַׂמֵּחַ אוֹתִי וּלְבָרֵךְ אוֹתִי בְּשִׂמְחָה שְׁלֵמָה. שֶׁכָּךְ שָׁנִינוּ, שֶׁמִּזִּוּוּג שֶׁל הַמֶּלֶךְ עִם כְּנֶסֶת יִשְׂרָאֵל כַּמָּה צַדִּיקִים יָרְשׁוּ יְרֻשַּׁת נַחֲלָה הַקְּדוֹשָׁה, וְכַמָּה בְרָכוֹת נִמְצָאוֹת בָּעוֹלָם.</p>"],[9522012039,"<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ לִכְפָר קַנְיָא (בסחורה) לִמְעָרַת לוֹד, וְהָיוּ עִמִּי רַבִּי יוֹסֵי וְרַבִּי חִיָּיא. אָמַר רַבִּי יוֹסֵי, כָּתוּב (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ וְגוֹ'. אֵשֶׁת חַיִל - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּכְרָקָב בְּעַצְמוֹתָיו מְבִישָׁה - אֵלּוּ (זו האמונה של שאר) הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא יָכוֹל לִסְבֹּל אוֹתָם בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא ב) וָאָקוּץ בָּם. כְּאוֹתָם קוֹצִים וְדַרְדָּרִים שֶׁדּוֹחֲקִים אֶת הָאָדָם וְלֹא יָכוֹל לִסְבֹּל אוֹתָם. אָמַר רַבִּי אַבָּא, כָּךְ זֶה וַדַּאי. אֵשֶׁת חַיִל - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא הַגְּבֶרֶת מִכַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת שֶׁנִּמְצָאִים בָּעוֹלָם. עֲטֶרֶת בַּעְלָהּ - כְּמוֹ שֶׁנֶּאֱמַר עֲטֶרֶת תִּפְאֶרֶת, וְהַכֹּל אֶחָד. (ל\"ג אשת חיל זו כנסת ישראל, שהריבזווג המלך הוציאה כמה חילות, כמה מחנות, כמה צדיקים בעולם, וכלם נקראים בנים להקדוש ברוך הוא ולכנסת ישראל, כמו שכתוב (דברים יד) בנים אתם לה' אלהיכם) עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אַבָּא, כָּל אֶחָד יֹאמַר דָּבָר בִּכְנֶסֶת יִשְׂרָאֵל.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, אֵשֶׁת חַיִל מִי יִמְצָא - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא אֵשֶׁת חַיִל, כְּמוֹ שֶׁאָמַרְנוּ. מִי יִמְצָא, כְּמוֹ שֶׁנֶּאֱמַר אֲשֶׁר יִמְצָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים. (ל\"ג מי ימצא להגיח בו קרב) מִי יִמְצָא - מִי יִזְכֶּה לִהְיוֹת עִמָּהּ בִּשְׁלֵמוּת וּלְהִמָּצֵא עִמָּהּ תָּמִיד.</p>\n<p>וְרָחוֹק מִפְּנִינִים מִכְרָהּ, מִכְרָהּ?! מִקָּחָהּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְכָל אוֹתָם שֶׁלֹּא נִדְבְּקוּ עִמָּהּ בִּשְׁלֵמוּת וְלֹא שְׁלֵמִים עִמָּהּ, הִיא מָכְרָה אוֹתָם וְהִסְגִּירָה אוֹתָם בִּידֵי עַמִּים אֲחֵרִים, כְּמוֹ שֶׁנֶּאֱמַר וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת ה', וַיִּמְכֹּר אֹתָם בְּיַד סִיסְרָא. וְאָז הִתְרַחֲקוּ כֻלָּם מֵאוֹתָן פְּנִינִים עֶלְיוֹנוֹת קְדוֹשׁוֹת, שֶׁלֹּא יְהֵא חֵלֶק בָּהֶן. זֶהוּ שֶׁכָּתוּב וְרָחוֹק מִפְּנִינִים מִכְרָהּ.</p>\n<p>רַבִּי חִיָּיא פָּתַח בַּפָּסוּק אַחֲרָיו וְאָמַר, בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר, בָּטַח בָּהּ לֵב בַּעְלָהּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁמִּשּׁוּם כָּךְ מִנָּה אוֹתָהּ עַל הָעוֹלָם לְהַנְהִיג אוֹתוֹ, כָּל כְּלֵי הַזַּיִן שֶׁלּוֹ הִפְקִיד בְּיָדֶיהָ, וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב, וְעַל כֵּן וְשָׁלָל לֹא יֶחְסָר.</p>\n<p>רַבִּי יוֹסֵי פָּתַח בַּפָּסוּק אַחֲרָיו וְאָמַר, גְּמָלַתְהוּ טוֹב וְלֹא רָע כָּל יְמֵי חַיֶּיהָ. גְּמָלַתְהוּ טוֹב, הִיא הִזְמִינָה טוֹב לָעוֹלָם, הִזְמִינָה טוֹב לְהֵיכַל הַמֶּלֶךְ וְלִבְנֵי הֵיכָלוֹ. וְלֹא רָע, מִשּׁוּם שֶׁכָּתוּב (בראשית ב) וְעֵץ הַדַּעַת טוֹב וָרָע. מָתַי טוֹב? בִּזְמַן שֶׁאוֹתָם יְמֵי הַשָּׁמַיִם מְאִירִים עָלֶיהָ וּמִזְדַּוְּגִים עִמָּהּ כָּרָאוּי, שֶׁהֵם יְמֵי חַיֶּיהָ. מִשּׁוּם שֶׁעֵץ הַחַיִּים שׁוֹלֵחַ לָהּ חַיִּים וּמֵאִיר לָהּ, וּבְאוֹתוֹ זְמַן - גְּמָלַתְהוּ טוֹב וְלֹא רָע. אָמַר רַבִּי אַבָּא, יָפֶה הוּא, וְכָל הַפְּסוּקִים נֶאֶמְרוּ עַל כְּנֶסֶת יִשְׂרָאֵל.</p>"],[9522012040,"<p>אִשָּׁה כִּי תַזְרִיעַ. שָׁנִינוּ, אִשָּׁה מַזְרַעַת תְּחִלָּה, יוֹלֶדֶת זָכָר. רַבִּי אָחָא אָמַר, הֲרֵי שָׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גָּזַר עַל הַטִּפָּה הַהִיא אִם הִיא זָכָר אִם הִיא נְקֵבָה, וְאַתָּה אוֹמֵר אִשָּׁה מַזְרַעַת תְּחִלָּה יוֹלֶדֶת זָכָר? אָמַר רַבִּי יוֹסֵי, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַבְחִין בֵּין טִפָּה שֶׁל זָכָר וּבֵין טִפָּה שֶׁל נְקֵבָה, וּמִשּׁוּם שֶׁמַּבְחִין בָּהּ, גּוֹזֵר עָלֶיהָ אִם תִּהְיֶה זָכָר אוֹ נְקֵבָה.</p>\n<p>אָמַר רַבִּי אָחָא, וְיָלְדָה זָכָר - וְכִי כֵּיוָן שֶׁמַּזְרַעַת יוֹלֶדֶת, שֶׁכָּתוּב וְיָלְדָה? (אלא) הַפָּסוּק הַזֶּה כָּךְ הָיָה צָרִיךְ לִהְיוֹת: אִשָּׁה כִּי תַהַר וְיָלְדָה זָכָר. (תזריעויהיהזכר) מַה זֶּה כִּי תַזְרִיעַ וְיָלְדָה? אָמַר רַבִּי יוֹסֵי, אִשָּׁה, מִיּוֹם שֶׁמִּתְעַבֶּרֶת עַד הַיּוֹם שֶׁמּוֹלִידָה, אֵין לָהּ בְּפִיהָ אֶלָּא הַיִּלּוֹד שֶׁלָּהּ אִם יִהְיֶה זָכָר, וְעַל כֵּן - אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר.</p>\n<p>אִשָּׁה כִּי תַזְרִיעַ. רַבִּי חִזְקִיָּה פָּתַח, מָה רַבּוּ מַעֲשֶׂיךְ ה', כַּמָּה רַבִּים מַעֲשֵׂי הַמֶּלֶךְ הַקָּדוֹשׁ בָּעוֹלָם. מָשָׁל לְאָדָם שֶׁלָּקַח בְּיָדוֹ כַּמָּה זְרָעִים יַחַד, וְזָרַע אוֹתָם בְּפַעַם אַחַת, וְאַחַר כָּךְ יוֹצֵא כָּל אֶחָד וְאֶחָד לְבַדּוֹ. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה מַעֲשָׂיו בְּחָכְמָה, וּבְחָכְמָה נָטַל הַכֹּל יַחַד וְזָרַע אוֹתָם, וְאַחַר כָּךְ יָצְאוּ כָּל אֶחָד וְאֶחָד בִּזְמַנּוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9522012041,"<p>אָמַר רַבִּי אַבָּא, מָה רַבּוּ מַעֲשֶׂיךְ ה', כַּמָּה רַבִּים מַעֲשֵׂי הַמֶּלֶךְ הַקָּדוֹשׁ, וְכֻלָּם סְתוּמִים בְּחָכְמָה. זֶהוּ שֶׁכָּתוּב כֻּלָּם בְּחָכְמָה עָשִׂיתָ. כֻּלָּם כְּלוּלִים בְּחָכְמָה, וְלֹא יוֹצְאִים הַחוּצָה אֶלָּא בִּשְׁבִילִים יְדוּעִים כְּלַפֵּי הַבִּינָה, וּמִשָּׁם נַעֲשִׂים הַכֹּל וְנִתְתַּקְּנִים. זֶהוּ שֶׁכָּתוּב (משלי כד) וּבִתְבוּנָה יִתְכּוֹנָן, וְעַל זֶה - כֻּלָּם בְּחָכְמָה עָשִׂיתָ, בְּבִינָה.</p>\n<p>מָלְאָה הָאָרֶץ. הָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּשָּׁם הַכֹּל מִתְמַלֵּא, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'. קִנְיָנֶךְ - שֶׁהִיא מוֹצִיאָה אוֹתָם אַחַר כָּךְ. זֶהוּ שֶׁכָּתוּב (בראשיתב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. מִשּׁוּם כָּךְ, מָלְאָה הָאָרֶץ קִנְיָנֶךְ.</p>"]]});
